window.IAIO = {"muc":{"1":"Tiền xử lý dữ liệu","2":"Đánh giá mô hình","3":"Bias, variance và điều chuẩn","4":"Toán nền tảng","5":"Hồi quy và SVM","6":"Cây, ensemble và kNN","7":"Phân cụm và giảm chiều","8":"Mạng nơ-ron","9":"Hệ gợi ý và học tăng cường","10":"Tìm kiếm, ràng buộc và logic"},"sets":[{"id":"light","title":"Light","minutes":180,"questions":[{"id":"LB011","muc":1,"q":"Bảng chiều cao học sinh lớp 10 có một dòng ghi 1700 cm, có lẽ do gõ thừa số 0. Giá trị khác thường như vậy gọi là gì?","options":["Giá trị thiếu","Nhãn nhiễu","Rò rỉ dữ liệu","Giá trị ngoại lai"],"answer":[3],"multi":false,"why":"Giá trị ngoại lai (outlier) nằm rất xa phần còn lại. Có khi đó là lỗi nhập liệu như ở đây, có khi là trường hợp thật nhưng hiếm. Cần xem kỹ rồi mới sửa hay bỏ."},{"id":"LD029","muc":1,"q":"Chuẩn hóa z-score (standardization) một cột dữ liệu làm thế nào?","options":["Trừ độ lệch chuẩn rồi chia trung bình","Trừ giá trị nhỏ nhất rồi chia khoảng","Chia cho giá trị lớn nhất của cột","Trừ trung bình rồi chia độ lệch chuẩn"],"answer":[3],"multi":false,"why":"Sau chuẩn hóa, cột có trung bình 0 và độ lệch chuẩn 1. Trừ nhỏ nhất rồi chia cho khoảng (lớn nhất − nhỏ nhất) là min-max, đưa về 0 đến 1."},{"id":"LC033","muc":1,"q":"Cột “màu xe” có vài ô bị trống. Cách điền đơn giản và hợp lý là gì?","options":["Điền màu xuất hiện nhiều nhất","Điền trung bình cộng các màu","Điền số 0 vào ô trống","Điền màu hiếm gặp nhất"],"answer":[0],"multi":false,"why":"Với cột hạng mục, “trung bình” không có nghĩa. Giá trị xuất hiện nhiều nhất (yếu vị) là lựa chọn đơn giản. Như mọi bước tiền xử lý, nó chỉ được tính trên tập train."},{"id":"LB010","muc":1,"q":"Lương của năm người là 8, 9, 10, 11 và 100 triệu đồng. Con số nào cho thấy mức lương thường gặp trong nhóm tốt hơn?","options":["Trung bình, bằng 27,6 triệu","Trung vị, bằng 10 triệu","Giá trị lớn nhất, 100 triệu","Giá trị nhỏ nhất, 8 triệu"],"answer":[1],"multi":false,"why":"Trung vị là giá trị đứng giữa khi xếp theo thứ tự. Một người lương 100 triệu kéo trung bình lên 27,6 triệu, cao hơn hẳn bốn người còn lại. Trung vị thì không bị kéo theo."},{"id":"M024","muc":1,"q":"Cột “thành phố” có ba giá trị Hà Nội, Huế, Đà Nẵng. Mã hóa thành 1, 2, 3 cho hồi quy tuyến tính thì có vấn đề gì?","options":["Hồi quy tuyến tính không nhận số nguyên","Không có vấn đề gì, vì chỉ là mã số","Mô hình ngầm hiểu các thành phố có thứ tự","Số cột tăng lên quá nhiều so với dữ liệu"],"answer":[2],"multi":false,"why":"Với mã 1, 2, 3, mô hình coi Huế nằm “giữa” và Đà Nẵng “gấp ba” Hà Nội. Mã hóa one-hot tạo ba cột 0 hoặc 1, mỗi cột cho một thành phố, nên không áp đặt thứ tự nào. Số cột tăng là nhược điểm của one-hot, không phải của cách đánh số."},{"id":"LB017","muc":1,"q":"Cột “mã khách hàng” là dãy số do hệ thống cấp ngẫu nhiên. Có nên dùng cột này làm đặc trưng để đoán khách có mua hàng không?","options":["Có, vì đó là cột số nên mô hình dùng được","Có, vì mỗi khách có một mã riêng","Có, vì càng nhiều cột mô hình càng tốt","Không, vì mã ngẫu nhiên không nói gì về khách"],"answer":[3],"multi":false,"why":"Mã được cấp ngẫu nhiên nên không liên quan đến việc mua hàng. Đưa vào chỉ thêm nhiễu, và mô hình có thể học thuộc từng mã nên dễ quá khớp."},{"id":"A-L-1-01","muc":1,"q":"Cột giá trị trên tập train có bốn số 10, 20, 30 và 50. Em chuẩn hóa min-max về đoạn [0, 1], với min và max lấy từ tập train. Một mẫu test có giá trị 40. Sau khi chuẩn hóa, mẫu này bằng bao nhiêu?","options":["0,75","0,8","0,6","1"],"answer":[0],"multi":false,"why":"Min của train là 10, max là 50, nên giá trị mới là (40 − 10)/(50 − 10) = 30/40 = 0,75. Số 0,8 là do quên trừ min (40/50). Số 0,6 là do chia 30 cho max thay vì cho khoảng max − min (30/50). Số 1 là do quên trừ min rồi chia cho khoảng 40."},{"id":"A-L-1-02","muc":1,"q":"Trên tập train, cột chiều cao có trung bình 160 cm và độ lệch chuẩn 5 cm. Em chuẩn hóa z-score bằng hai số này. Một học sinh cao 170 cm được đổi thành bao nhiêu?","options":["2","10","34","1,0625"],"answer":[0],"multi":false,"why":"z = (170 − 160)/5 = 2. Số 10 là quên chia cho độ lệch chuẩn. Số 34 là lấy 170/5, quên trừ trung bình. Số 1,0625 là lấy 170/160, chia nhầm cho trung bình."},{"id":"A-L-1-03","muc":1,"q":"Một số thuật toán nhạy với thang đo của các đặc trưng nên cần chuẩn hóa. Chọn tất cả thuật toán cần chuẩn hóa.","options":["kNN","Rừng ngẫu nhiên (random forest)","Gradient boosting trên cây quyết định","PCA"],"answer":[0,3],"multi":true,"why":"kNN dùng khoảng cách, PCA tìm hướng có phương sai lớn nên đặc trưng có số đo lớn sẽ lấn át. Rừng ngẫu nhiên và boosting trên cây chỉ dùng phép so sánh với ngưỡng nên không cần chuẩn hóa."},{"id":"A-L-1-04","muc":1,"q":"Em cần chuẩn hóa dữ liệu mà không gây rò rỉ (data leakage). Chọn tất cả cách làm đúng.","options":["Tính mean và độ lệch chuẩn trên toàn bộ dữ liệu, rồi mới chia train và test.","Chia train và test trước, rồi mới tính tham số chuẩn hóa.","Tính mean và độ lệch chuẩn riêng trên test để biến đổi test.","Tính mean và độ lệch chuẩn trên train, rồi dùng chính các giá trị đó để biến đổi test."],"answer":[1,3],"multi":true,"why":"Tham số chuẩn hóa chỉ được học từ train, sau đó áp dụng nguyên xi cho test. Tính trên toàn bộ dữ liệu làm thông tin của test lọt vào quá trình học. Tính riêng trên test thì test và train bị đưa về hai thang đo khác nhau."},{"id":"LB030","muc":2,"q":"Trong dữ liệu, 70% khách ở lại và 30% khách rời đi. Một mô hình luôn đoán “ở lại”. Accuracy của nó bằng bao nhiêu?","options":["30%","50%","100%","70%"],"answer":[3],"multi":false,"why":"Mô hình này đúng với mọi khách ở lại, tức 70% dữ liệu. Mô hình thật phải vượt rõ mốc 70% này mới có ích."},{"id":"LB033","muc":2,"q":"Mô hình sàng lọc một bệnh nguy hiểm. Ai bị báo nghi mắc sẽ được xét nghiệm lại. Bỏ sót người bệnh là điều tệ nhất. Nên ưu tiên chỉ số nào?","options":["Precision (độ chuẩn xác)","Recall (độ bao phủ)","Accuracy (độ chính xác)","MAE (sai số tuyệt đối trung bình)"],"answer":[1],"multi":false,"why":"Recall đo trong số người thật sự mắc bệnh, mô hình tìm ra được bao nhiêu. Báo nhầm một người khỏe chỉ tốn thêm một lần xét nghiệm. Bỏ sót người bệnh thì hậu quả nặng hơn nhiều."},{"id":"LC019","muc":2,"q":"Ứng dụng đoán chó có đói hay không. Phần lớn thời gian chó không đói. Nếu báo nhầm là đói, chủ sẽ cho ăn thêm và chó dễ sinh bệnh. Nên ưu tiên chỉ số nào?","options":["Accuracy","Precision","Recall","Tỉ lệ ảnh có chó"],"answer":[1],"multi":false,"why":"Báo nhầm là “đói” gây hại, nên khi mô hình nói “đói” thì phải đáng tin, tức precision cao. Accuracy dễ gây hiểu lầm vì chó hầu như không đói: đoán “không đói” mãi cũng được accuracy cao."},{"id":"L035","muc":2,"q":"Mô hình cho ra xác suất một email là thư rác. Ta hạ ngưỡng từ 0,5 xuống 0,3. Điều gì thường xảy ra?","options":["Bắt ít thư rác hơn và báo nhầm ít hơn","Accuracy chắc chắn tăng theo","Bắt nhiều thư rác hơn, báo nhầm cũng nhiều hơn","Không có gì thay đổi vì mô hình vẫn vậy"],"answer":[2],"multi":false,"why":"Ngưỡng thấp hơn thì nhiều thư bị gọi là rác hơn. Recall tăng, còn precision thường giảm. Chọn ngưỡng là chọn điểm cân bằng giữa hai chỉ số này."},{"id":"LB032","muc":2,"q":"Lớp dương là “thư rác”. Một email bình thường bị mô hình đánh dấu là thư rác. Đây là loại lỗi gì?","options":["Âm tính giả (false negative)","Dương tính giả (false positive)","Dương tính thật (true positive)","Âm tính thật (true negative)"],"answer":[1],"multi":false,"why":"Mô hình báo “dương” nhưng thực tế là “âm”, nên gọi là dương tính giả. Còn thư rác lọt vào hộp thư chính là âm tính giả."},{"id":"LB031","muc":2,"q":"Ma trận nhầm lẫn có hàng là nhãn thật, cột là nhãn dự đoán. Các ô trên đường chéo chính cho biết gì?","options":["Số ví dụ đoán sai của từng lớp","Số ví dụ đoán đúng của từng lớp","Tổng số ví dụ của tập kiểm tra","Xác suất mô hình gán cho từng lớp"],"answer":[1],"multi":false,"why":"Trên đường chéo, nhãn thật trùng nhãn dự đoán, tức là đoán đúng. Cộng các ô trên đường chéo rồi chia cho tổng số ví dụ là ra accuracy."},{"id":"A-L-2-01","muc":2,"q":"Một mô hình phát hiện thư rác cho kết quả trên 200 thư như sau.\nTP = 40\nFP = 10\nFN = 20\nTN = 130\nPrecision của mô hình bằng bao nhiêu?","options":["0,67","0,8","0,85","0,07"],"answer":[1],"multi":false,"why":"Precision = TP/(TP + FP) = 40/50 = 0,8. Số 0,67 là recall (40/60). Số 0,85 là accuracy (170/200). Số 0,07 là FPR (10/140)."},{"id":"A-L-2-02","muc":2,"q":"Một mô hình chẩn đoán bệnh cho kết quả như sau.\nTP = 30\nFN = 10\nFP = 20\nTN = 140\nSpecificity (TNR) của mô hình bằng bao nhiêu?","options":["0,75","0,6","0,125","0,875"],"answer":[3],"multi":false,"why":"Specificity = TN/(TN + FP) = 140/160 = 0,875. Số 0,75 là recall (30/40). Số 0,6 là precision (30/50). Số 0,125 là FPR = 1 − specificity."},{"id":"A-L-2-03","muc":2,"q":"Về đường ROC của một mô hình phân loại hai lớp. Chọn tất cả phát biểu đúng.","options":["Trục hoành là FPR, trục tung là TPR (recall).","Mô hình cho điểm ngẫu nhiên có đường ROC gần đường chéo, AUC khoảng 0,5.","AUC bằng 1 nghĩa là ở ngưỡng nào mô hình cũng đúng 100%.","Hạ ngưỡng phân loại thì điểm trên đường ROC dịch về phía gốc (0, 0)."],"answer":[0,1],"multi":true,"why":"Mỗi ngưỡng cho một điểm (FPR, TPR) trên đường ROC. Hạ ngưỡng thì nhiều mẫu được gọi là dương hơn, TPR và FPR cùng tăng, nên điểm đi về phía (1, 1) chứ không về (0, 0). AUC bằng 1 nghĩa là mọi mẫu dương đều có điểm cao hơn mọi mẫu âm, nên tồn tại một ngưỡng tách đúng hết; đặt ngưỡng sai chỗ thì vẫn đoán sai. Mô hình cho điểm ngẫu nhiên có đường gần đường chéo, AUC khoảng 0,5."},{"id":"A-L-2-04","muc":2,"q":"Một mô hình có TP = 30, FP = 30 và FN = 10. F1 của mô hình bằng bao nhiêu?","options":["0,5","0,75","0,625","0,6"],"answer":[3],"multi":false,"why":"F1 = 2TP/(2TP + FP + FN) = 60/(60 + 30 + 10) = 0,6. Số 0,5 là precision (30/60). Số 0,75 là recall (30/40). Số 0,625 là trung bình cộng của precision và recall, không phải trung bình điều hòa."},{"id":"M001","muc":3,"q":"Một bài toán mà người làm tay đạt khoảng 95%. Mô hình chỉ đạt 62% trên train và 61% trên validation. Mô hình đang gặp vấn đề gì?","options":["Chưa khớp: mô hình quá đơn giản","Quá khớp: mô hình học thuộc train","Rò rỉ dữ liệu giữa train và validation","Tập validation quá dễ"],"answer":[0],"multi":false,"why":"Train và validation đều thấp và gần bằng nhau, tức là mô hình chưa học nổi ngay cả dữ liệu đã thấy. Đó là chưa khớp (bias cao). Quá khớp thì điểm train phải cao hơn hẳn validation. Cách sửa là tăng độ phức tạp của mô hình hoặc thêm đặc trưng."},{"id":"LC031","muc":3,"q":"Hai mô hình cho kết quả như nhau trên tập validation. Một mô hình rất đơn giản, một mô hình rất phức tạp. Nên chọn mô hình nào?","options":["Mô hình phức tạp hơn","Mô hình đơn giản hơn","Chọn ngẫu nhiên một mô hình","Mô hình chạy chậm hơn"],"answer":[1],"multi":false,"why":"Khi kết quả như nhau, mô hình đơn giản thường ít quá khớp hơn, chạy nhanh hơn và dễ giải thích hơn. Đây là tinh thần của nguyên tắc dao cạo Occam."},{"id":"LB007","muc":3,"q":"Mô hình đúng gần hết trên dữ liệu học nhưng làm kém trên tập kiểm định. Cách nào thường giúp?","options":["Huấn luyện thêm nhiều epoch nữa","Dùng mô hình phức tạp hơn nữa","Thu thập thêm dữ liệu huấn luyện","Lấy cả tập kiểm tra để huấn luyện"],"answer":[2],"multi":false,"why":"Có thêm dữ liệu, mô hình khó học thuộc từng ví dụ hơn và phải tìm quy luật chung. Học thêm epoch hay dùng mô hình phức tạp hơn thường làm quá khớp nặng thêm."},{"id":"LC017","muc":3,"q":"Thường thì mô hình quá đơn giản và mô hình quá phức tạp gặp vấn đề gì?","options":["Đơn giản thì variance cao, phức tạp thì bias cao","Đơn giản thì bias cao, phức tạp thì variance cao","Cả hai đều có bias bằng variance","Bias và variance không liên quan độ phức tạp"],"answer":[1],"multi":false,"why":"Bias cao là mô hình đoán lệch một cách có hệ thống vì quá cứng nhắc, tức chưa khớp. Variance cao là mô hình đổi kết quả nhiều khi dữ liệu học thay đổi một chút, tức dễ quá khớp. Ta tìm độ phức tạp ở giữa."},{"id":"M016","muc":3,"q":"Với K = 1, kNN đạt 100% trên train nhưng validation thấp. Tăng K lên vừa phải thường làm gì?","options":["Ranh giới gồ ghề hơn, quá khớp nặng hơn","Mô hình học thêm trọng số mới","Ranh giới mượt hơn, bớt quá khớp","Train vẫn luôn đúng 100%"],"answer":[2],"multi":false,"why":"Với K = 1, mỗi điểm train được chính nó “bỏ phiếu” nên train luôn đúng hết. K lớn hơn lấy ý kiến của nhiều láng giềng, nên bớt nhạy với điểm nhiễu. Nhưng K quá lớn thì mô hình lại chưa khớp."},{"id":"M017","muc":3,"q":"Cây quyết định không giới hạn độ sâu đạt 100% trên train, 70% trên validation. Nên chỉnh gì trước?","options":["Bỏ mọi giới hạn để cây sâu hơn nữa","Chuẩn hóa các đặc trưng về cùng thang đo","Đổi sang một tập validation cho điểm cao hơn","Giới hạn độ sâu hoặc số mẫu tối thiểu ở mỗi lá"],"answer":[3],"multi":false,"why":"Cây càng sâu càng chia nhỏ dữ liệu, đến khi mỗi lá chỉ còn vài mẫu, kể cả mẫu nhiễu. Giới hạn độ sâu giúp giảm quá khớp. Chuẩn hóa không giúp gì, vì cây chỉ so từng cột với một ngưỡng."},{"id":"A-L-3-01","muc":3,"q":"Một mô hình có lỗi 2% trên tập train và 25% trên tập validation. Em kết luận thế nào?","options":["Mô hình bị underfit (bias cao).","Mô hình bị overfit (variance cao).","Mô hình tốt, vì lỗi train rất thấp.","Tập validation dễ hơn tập train."],"answer":[1],"multi":false,"why":"Lỗi train rất thấp nhưng lỗi validation cao hơn nhiều là dấu hiệu overfit: mô hình thuộc lòng train mà không tổng quát hóa. Underfit thì lỗi train đã cao. Tập validation có lỗi cao hơn nên nó khó hơn chứ không dễ hơn."},{"id":"A-L-3-02","muc":3,"q":"Một mô hình có lỗi 30% trên tập train và 32% trên tập validation. Hai con số này gần nhau. Em nên làm gì?","options":["Tăng regularization mạnh hơn.","Giảm số đặc trưng đi.","Dùng mô hình phức tạp hơn, vì mô hình đang underfit.","Chỉ cần thu thập thêm dữ liệu rồi giữ nguyên mô hình."],"answer":[2],"multi":false,"why":"Lỗi cao ngay trên train nghĩa là bias cao, mô hình quá đơn giản. Cần tăng độ phức tạp hoặc thêm đặc trưng. Tăng regularization hay giảm đặc trưng chỉ làm mô hình đơn giản hơn nữa. Thêm dữ liệu không giúp nhiều khi mô hình không đủ khả năng học."},{"id":"A-L-3-03","muc":3,"q":"Về regularization L1 và L2. Chọn tất cả phát biểu đúng.","options":["L2 luôn tạo ra mô hình thưa hơn L1.","L1 có thể đưa một số trọng số về đúng 0.","L1 có thể dùng để chọn đặc trưng.","L2 co các trọng số nhỏ lại nhưng thường không đưa chúng về đúng 0."],"answer":[1,2,3],"multi":true,"why":"L1 phạt tổng |w| nên nghiệm thường có nhiều trọng số bằng 0, dùng để chọn đặc trưng. L2 phạt tổng w², chỉ làm trọng số nhỏ dần chứ ít khi bằng 0. Vì vậy L1 mới là bên cho mô hình thưa."},{"id":"A-L-3-04","muc":3,"q":"Em tăng hệ số regularization λ lên một giá trị lớn hơn. Chọn tất cả phát biểu đúng.","options":["Các trọng số bị co nhỏ lại.","Lỗi trên train chắc chắn giảm.","Bias của mô hình thường tăng.","Variance của mô hình thường giảm."],"answer":[0,2,3],"multi":true,"why":"λ lớn làm hình phạt nặng hơn, mô hình bị ép đơn giản lại: trọng số nhỏ hơn, bias tăng, variance giảm. Vì mô hình kém linh hoạt, lỗi trên train thường tăng chứ không giảm."},{"id":"LB024","muc":4,"q":"Hai điểm có tọa độ (0, 0) và (3, 4). Khoảng cách Euclid giữa chúng bằng bao nhiêu?","options":["7","5","1","25"],"answer":[1],"multi":false,"why":"Khoảng cách Euclid = √(3² + 4²) = √25 = 5. Đây là khoảng cách đường thẳng mà kNN và K-means thường dùng."},{"id":"LC006","muc":4,"q":"Gieo một con xúc xắc cân đối 6 mặt. Xác suất ra mặt từ 5 trở lên là bao nhiêu?","options":["1/6","1/3","1/2","5/6"],"answer":[1],"multi":false,"why":"Có 2 mặt thỏa mãn là 5 và 6, trong 6 mặt có khả năng như nhau: 2/6 = 1/3."},{"id":"LE019","muc":4,"q":"Hiệp phương sai đo hai biến cùng tăng giảm với nhau mạnh đến đâu. Hiệp phương sai của X với chính X bằng gì?","options":["Phương sai của X","Luôn bằng 0","Luôn bằng 1","Giá trị trung bình của X"],"answer":[0],"multi":false,"why":"Thay Y bằng X vào công thức, ta được trung bình của (X − trung bình)², đúng là phương sai. Hệ số tương quan của X với chính nó mới bằng 1."},{"id":"LC009","muc":4,"q":"Nhân ma trận cỡ 3 × 2 với ma trận cỡ 2 × 4 thì được ma trận cỡ bao nhiêu?","options":["3 × 4","2 × 2","3 × 2","Không nhân được"],"answer":[0],"multi":false,"why":"Số cột của ma trận trước (2) phải bằng số hàng của ma trận sau (2). Kết quả có số hàng của ma trận trước và số cột của ma trận sau: 3 × 4."},{"id":"LE033","muc":4,"q":"Lớp có 30 bạn, 12 bạn nữ, trong đó 3 bạn nữ đeo kính. Chọn ngẫu nhiên một bạn nữ, xác suất bạn đó đeo kính là bao nhiêu?","options":["1/10","2/5","1/4","1/3"],"answer":[2],"multi":false,"why":"Biết đã chọn bạn nữ, ta chỉ xét 12 bạn nữ, có 3 bạn đeo kính, nên được 3/12 = 1/4. 1/10 là 3/30, tức nhầm sang chia cho cả lớp."},{"id":"LC008","muc":4,"q":"Tích vô hướng của hai vector (1, 2, 3) và (4, 5, 6) bằng bao nhiêu?","options":["21","28","32","36"],"answer":[2],"multi":false,"why":"1 × 4 + 2 × 5 + 3 × 6 = 4 + 10 + 18 = 32. Một nơ-ron tính đúng phép này giữa đầu vào và trọng số của nó."},{"id":"A-L-4-01","muc":4,"q":"Hai điểm trên mặt phẳng là A = (1, 2) và B = (4, 6). Khoảng cách Manhattan giữa A và B bằng bao nhiêu?","options":["7","5","25","3"],"answer":[0],"multi":false,"why":"Manhattan = |4 − 1| + |6 − 2| = 3 + 4 = 7. Số 5 là khoảng cách Euclid √(9 + 16). Số 25 là bình phương khoảng cách Euclid. Số 3 chỉ là hiệu theo trục đầu tiên."},{"id":"A-L-4-02","muc":4,"q":"Em tối thiểu hóa f(w) = w². Điểm xuất phát là w = 3 và learning rate η = 0,1. Sau một bước gradient descent, w bằng bao nhiêu?","options":["2,4","2,7","0,6","3,6"],"answer":[0],"multi":false,"why":"Đạo hàm f′(w) = 2w = 6 tại w = 3. Bước cập nhật: w = 3 − 0,1·6 = 2,4. Số 2,7 là do lấy đạo hàm bằng w thay vì 2w. Số 0,6 chỉ là độ dài bước, chưa trừ khỏi w. Số 3,6 là do cộng thay vì trừ."},{"id":"A-L-4-03","muc":4,"q":"Trong một lô sản phẩm, 20% bị lỗi. Máy kiểm tra báo động với 90% số sản phẩm lỗi. Tính chung cả lô, máy báo động với 30% số sản phẩm. Một sản phẩm vừa bị báo động. Xác suất nó bị lỗi bằng bao nhiêu?","options":["0,9","0,18","0,6","1,35"],"answer":[2],"multi":false,"why":"Theo công thức Bayes: P(lỗi | báo) = P(báo | lỗi)·P(lỗi)/P(báo) = 0,9·0,2/0,3 = 0,6. Số 0,9 là P(báo | lỗi), chưa đảo điều kiện. Số 0,18 là tử số, chưa chia cho P(báo). Số 1,35 là do chia ngược 0,9·0,3/0,2, và xác suất không thể vượt 1."},{"id":"A-L-4-04","muc":4,"q":"Cho hai vector a = (3, 4) và b = (4, 3). Chọn tất cả phát biểu đúng.","options":["Khoảng cách Euclid giữa a và b bằng 2.","Tích vô hướng a·b bằng 24.","Cosine giữa a và b bằng 0,96.","Khoảng cách Manhattan giữa a và b bằng 2."],"answer":[1,2,3],"multi":true,"why":"a·b = 12 + 12 = 24. Hai vector đều có độ dài 5 nên cosine = 24/25 = 0,96. Manhattan = 1 + 1 = 2. Khoảng cách Euclid là √(1 + 1) = √2, không phải 2."},{"id":"LD016","muc":5,"q":"Dự đoán giá căn hộ từ diện tích, khoảng cách tới trung tâm và số tầng. Mô hình nào hợp hơn?","options":["Hồi quy logistic","Phân cụm K-means","Hồi quy tuyến tính","Phân loại bằng kNN"],"answer":[2],"multi":false,"why":"Giá là một con số, nên đây là hồi quy. Hồi quy logistic dù có chữ “hồi quy” lại dùng để phân loại, cho ra xác suất thuộc một lớp."},{"id":"LC042","muc":5,"q":"Một nơ-ron có hàm kích hoạt sigmoid phân loại các điểm trên mặt phẳng thành hai lớp. Ranh giới quyết định của nó có hình gì?","options":["Đường cong hình chữ S","Đường tròn","Đường thẳng","Hình vuông"],"answer":[2],"multi":false,"why":"Nơ-ron đoán lớp 1 khi σ(w·x + b) > 0,5, tức w·x + b > 0. Ranh giới w·x + b = 0 là một đường thẳng. Hình chữ S là đồ thị của sigmoid, không phải hình của ranh giới."},{"id":"L023","muc":5,"q":"Thuật toán phân loại nào tìm đường ranh giới nằm cách hai lớp xa nhất có thể?","options":["k láng giềng gần nhất (kNN)","Máy vector hỗ trợ (SVM)","Cây quyết định","K-means"],"answer":[1],"multi":false,"why":"SVM (support vector machine) chọn ranh giới có lề rộng nhất giữa hai lớp. Lề rộng thường giúp phân loại ví dụ mới vững hơn."},{"id":"LB020","muc":5,"q":"Mô hình dự đoán giá = 30 × diện tích + 100, giá tính bằng triệu đồng, diện tích tính bằng m². Diện tích tăng thêm 1 m² thì giá dự đoán tăng bao nhiêu?","options":["30 triệu đồng","100 triệu đồng","130 triệu đồng","1 triệu đồng"],"answer":[0],"multi":false,"why":"Mỗi m² thêm vào được nhân với 30, nên giá tăng 30 triệu. Số 100 là phần cộng sẵn, không đổi theo diện tích."},{"id":"H005","muc":5,"q":"SVM tuyến tính đã học được w = (1, −2) và b = 0,5, dự đoán theo dấu của w·x + b. Điểm nào được dự đoán thuộc lớp −1?","options":["(1, 1)","(3, 1)","(2, 0)","(4, 1)"],"answer":[0],"multi":false,"why":"Tính w·x + b: (3, 1) cho 1,5; (1, 1) cho 1 − 2 + 0,5 = −0,5; (2, 0) cho 2,5; (4, 1) cho 2,5. Chỉ (1, 1) cho giá trị âm."},{"id":"LE039","muc":5,"q":"Đạo hàm của sigmoid bằng σ × (1 − σ). Tại điểm mà sigmoid cho ra 0,4, đạo hàm bằng bao nhiêu?","options":["0,24","0,16","0,4","0,6"],"answer":[0],"multi":false,"why":"0,4 × (1 − 0,4) = 0,4 × 0,6 = 0,24. Đạo hàm này lớn nhất bằng 0,25 khi sigmoid cho 0,5, và gần 0 khi đầu ra sát 0 hoặc 1."},{"id":"B-L-5-01","muc":5,"q":"Một mô hình hồi quy logistic có z = 2x − 4.\nVới x = 2, mô hình dự đoán P(y = 1) bằng bao nhiêu?","options":["0","0,5","1","0,25"],"answer":[1],"multi":false,"why":"Với x = 2 thì z = 2·2 − 4 = 0. Khi đó σ(0) = 1/(1 + e⁰) = 1/2 = 0,5. Chọn 0,25 là nhầm σ(0) với đạo hàm σ'(0) = σ(0)(1 − σ(0)) = 0,25. Chọn 0 hoặc 1 là nhầm với giá trị giới hạn khi z → −∞ hoặc z → +∞."},{"id":"B-L-5-02","muc":5,"q":"Một SVM tuyến tính có vector trọng số w với ‖w‖ = 2.\nLề (margin) giữa hai biên bằng bao nhiêu?","options":["2","1","0,5","4"],"answer":[1],"multi":false,"why":"Lề của SVM bằng 2/‖w‖ = 2/2 = 1. Chọn 0,5 là dùng 1/‖w‖, tức chỉ tính nửa lề. Chọn 2 là nhầm lề bằng ‖w‖. Chọn 4 là lấy ‖w‖²."},{"id":"B-L-5-03","muc":5,"q":"Một SVM có w = (1, 2) và b = −2.\nĐiểm x = (1, 0) có nhãn y = +1.\nHinge loss max(0, 1 − y(wᵀx + b)) của điểm này bằng bao nhiêu?","options":["2","0","1","4"],"answer":[0],"multi":false,"why":"Ta có wᵀx + b = 1·1 + 2·0 − 2 = −1. Nên y(wᵀx + b) = −1 và hinge loss = max(0, 1 − (−1)) = 2. Chọn 0 là quên b: khi đó wᵀx = 1, y(wᵀx) = 1 và loss bằng 0. Chọn 4 là bình phương hinge loss. Chọn 1 là lấy giá trị |wᵀx + b| mà bỏ bước 1 − y(...)."},{"id":"B-L-5-04","muc":5,"q":"Cho hồi quy logistic với hàm sigmoid σ(z).\nChọn tất cả phát biểu đúng.","options":["Hàm mất mát chuẩn của hồi quy logistic là MSE.","Đạo hàm của sigmoid là σ'(z) = σ(z)(1 − σ(z)).","Đạo hàm σ'(z) có giá trị lớn nhất bằng 1.","σ(z) luôn nằm trong khoảng (0, 1)."],"answer":[1,3],"multi":true,"why":"Sigmoid cho giá trị trong (0, 1) và có đạo hàm σ(1 − σ). Giá trị lớn nhất của σ(1 − σ) là 1/2·1/2 = 0,25 chứ không phải 1. Hồi quy logistic dùng log loss (cross-entropy), không dùng MSE."},{"id":"LB023","muc":6,"q":"Dùng kNN với K = 3. Ba điểm gần điểm mới nhất có nhãn mèo, chó, mèo. kNN đoán điểm mới là gì?","options":["Chó","Nửa mèo nửa chó","Chưa đoán được vì có hai nhãn","Mèo"],"answer":[3],"multi":false,"why":"Ba láng giềng bỏ phiếu: mèo được 2 phiếu, chó được 1 phiếu. Mèo nhiều phiếu hơn. Với bài hai lớp, người ta hay chọn K lẻ để không bị hòa phiếu."},{"id":"LE022","muc":6,"q":"Ba căn nhà gần căn mới nhất có giá 2, 3 và 4 tỉ đồng. Dùng kNN với k = 3 để đoán giá, kết quả là bao nhiêu?","options":["Không đoán được, kNN chỉ dùng để phân loại","4 tỉ, giá cao nhất trong ba căn","3 tỉ, trung bình của ba căn","9 tỉ, tổng giá của ba căn"],"answer":[2],"multi":false,"why":"kNN làm được cả hồi quy. Thay vì bỏ phiếu chọn lớp, nó lấy trung bình giá trị của k hàng xóm gần nhất."},{"id":"LE010","muc":6,"q":"Bốn điểm train là (0, 0) lớp 0, (4, 0) lớp 0, (0, 3) lớp 1, (2, 2) lớp 1. Dùng khoảng cách Euclid, 3-NN dự đoán điểm (1, 1) thuộc lớp nào?","options":["Lớp 0","Hòa, không quyết định được","Lớp 1","Tùy vào thứ tự các điểm trong dữ liệu"],"answer":[2],"multi":false,"why":"Khoảng cách từ (1, 1) lần lượt là √2, √10, √5, √2. Ba điểm gần nhất là (0, 0), (2, 2), (0, 3), mang nhãn 0, 1, 1. Bỏ phiếu được lớp 1."},{"id":"LE027","muc":6,"q":"Rừng ngẫu nhiên đoán giá nhà báo rằng cột “diện tích” quan trọng nhất. Hiểu thế nào cho đúng?","options":["Diện tích là nguyên nhân duy nhất làm giá nhà tăng","Các cột khác có thể xóa đi mà không ảnh hưởng gì","Cột này có ít giá trị thiếu nhất","Mô hình dựa vào cột này nhiều nhất khi đoán"],"answer":[3],"multi":false,"why":"Độ quan trọng cho biết mô hình dùng cột nào nhiều. Nó không chứng minh quan hệ nhân quả, và các cột ít quan trọng vẫn có thể góp phần khi kết hợp với nhau."},{"id":"LD028","muc":6,"q":"Cây quyết định chọn câu hỏi để chia dữ liệu dựa vào gì?","options":["Chọn ngẫu nhiên một đặc trưng bất kỳ","Theo thứ tự chữ cái tên đặc trưng","Đặc trưng và ngưỡng tách lớp tốt nhất","Đặc trưng có tên dài nhất"],"answer":[2],"multi":false,"why":"Ở mỗi nút, cây thử nhiều đặc trưng và ngưỡng, rồi chọn cách chia làm hai nhánh “thuần” nhất, tức mỗi nhánh gần như chỉ còn một lớp."},{"id":"E011","muc":6,"q":"Ba cây của rừng ngẫu nhiên cho xác suất lớp A lần lượt 0,9; 0,4; 0,4 (bài hai lớp A, B). Bỏ phiếu cứng và lấy trung bình xác suất (bỏ phiếu mềm) cho kết quả nào?","options":["Cứng ra A, mềm ra B","Cứng ra B, mềm ra A","Cả hai ra A","Cả hai ra B"],"answer":[1],"multi":false,"why":"Phiếu cứng: hai cây có xác suất A dưới 0,5 nên bầu B, B thắng 2–1. Phiếu mềm: trung bình (0,9 + 0,4 + 0,4)/3 ≈ 0,57 > 0,5 nên ra A. scikit-learn dùng cách lấy trung bình xác suất cho RandomForestClassifier."},{"id":"B-L-6-01","muc":6,"q":"Một nút của cây quyết định có 4 mẫu, gồm 2 mẫu dương và 2 mẫu âm.\nEntropy (dùng log₂) và Gini của nút này lần lượt bằng bao nhiêu?","options":["0,5 và 1","1 và 1","0 và 0,5","1 và 0,5"],"answer":[3],"multi":false,"why":"Với p = (1/2, 1/2) thì entropy = −2·(1/2)·log₂(1/2) = 1. Gini = 1 − (1/4 + 1/4) = 0,5. Chọn 0,5 và 1 là đảo hai giá trị. Chọn 0 và 0,5 là tính nhầm entropy như nút thuần."},{"id":"B-L-6-02","muc":6,"q":"Bài toán phân loại có 5 điểm huấn luyện một chiều.\nx = 1, lớp A\nx = 4, lớp B\nx = 6, lớp B\nx = 8, lớp A\nx = 9, lớp A\nCần dự đoán lớp của x = 5.\nkNN dự đoán lớp nào khi k = 1 và khi k = 5?","options":["k = 1: lớp A; k = 5: lớp A","k = 1: lớp B; k = 5: lớp B","k = 1: lớp B; k = 5: lớp A","k = 1: lớp A; k = 5: lớp B"],"answer":[2],"multi":false,"why":"Khi k = 1, điểm gần nhất cách 1 đơn vị là x = 4 và x = 6, cả hai đều lớp B. Khi k = 5, ta lấy cả 5 điểm: 3 điểm lớp A và 2 điểm lớp B, nên lớp A thắng. Hai lựa chọn còn lại đảo hoặc giữ nguyên kết quả của k = 1 và k = 5."},{"id":"B-L-6-03","muc":6,"q":"Chọn tất cả phát biểu đúng về random forest và boosting.","options":["Random forest giảm variance bằng cách lấy trung bình nhiều cây huấn luyện trên các mẫu bootstrap.","Boosting huấn luyện các mô hình lần lượt, mỗi mô hình tập trung vào lỗi của mô hình trước.","Boosting huấn luyện các mô hình độc lập rồi lấy trung bình.","Cây quyết định rất sâu thường có variance thấp."],"answer":[0,1],"multi":true,"why":"Random forest lấy trung bình nhiều cây nên giảm variance. Boosting thêm mô hình theo thứ tự để sửa lỗi của các mô hình trước, nên giảm bias. Cây rất sâu bám sát dữ liệu huấn luyện, nên có variance cao chứ không thấp."},{"id":"B-L-6-04","muc":6,"q":"Nút cha có 8 mẫu, gồm 4 dương và 4 âm, nên entropy bằng 1.\nPhép chia X tạo hai nút: (4 dương, 0 âm) và (0 dương, 4 âm).\nPhép chia Y tạo hai nút: (2 dương, 2 âm) và (2 dương, 2 âm).\nChọn tất cả phát biểu đúng.","options":["Information gain của phép chia X bằng 1.","Information gain của phép chia Y bằng 0.","Mỗi nút con của phép chia Y có entropy 0,5.","Cây nên chọn Y vì hai nút con có số mẫu bằng nhau."],"answer":[0,1],"multi":true,"why":"Hai nút con của X đều thuần nên entropy bằng 0, IG = 1 − 0 = 1. Hai nút con của Y vẫn chia đôi 2–2 nên entropy vẫn bằng 1, IG = 1 − 1 = 0: phép chia này không tách được gì. Cây chọn phép chia có IG lớn nhất, tức X. Số mẫu ở hai nhánh bằng nhau không phải tiêu chí chọn."},{"id":"LE024","muc":7,"q":"K-means đang có hai tâm cụm là (1, 1) và (5, 5). Ở bước gán, điểm (2, 3) thuộc cụm nào?","options":["Cụm của tâm (5, 5)","Cụm của tâm (1, 1)","Thuộc cả hai cụm cùng lúc","Chưa gán được, phải chờ tính xong tâm mới"],"answer":[1],"multi":false,"why":"Bình phương khoảng cách tới (1, 1) là 1 + 4 = 5, tới (5, 5) là 9 + 4 = 13. Mỗi điểm về cụm có tâm gần nhất, nên (2, 3) về cụm (1, 1)."},{"id":"LE011","muc":7,"q":"Chạy K-means hai lần trên cùng dữ liệu, cùng K = 3, nhưng ra hai cách chia cụm hơi khác nhau. Vì sao?","options":["Dữ liệu bị thay đổi giữa hai lần chạy","Tâm cụm ban đầu được chọn ngẫu nhiên","K-means luôn tìm được cách chia tốt nhất","Máy tính tính sai ở một trong hai lần"],"answer":[1],"multi":false,"why":"K-means bắt đầu từ các tâm ngẫu nhiên rồi chỉnh dần, nên có thể dừng ở những cách chia khác nhau. Người ta thường chạy nhiều lần và giữ kết quả có tổng khoảng cách nhỏ nhất."},{"id":"M025","muc":7,"q":"Chạy K-means với K từ 1 đến 10, vẽ tổng khoảng cách từ mỗi điểm đến tâm cụm của nó. Đường giảm nhanh đến K = 4 rồi gần như nằm ngang. Nên chọn K bằng bao nhiêu?","options":["1","10","2","4"],"answer":[3],"multi":false,"why":"Đây là phương pháp khuỷu tay (elbow). Tổng khoảng cách luôn giảm khi K tăng, nên K = 10 cho số nhỏ nhất chỉ vì chia vụn dữ liệu. Điểm gãy K = 4 là nơi thêm cụm không còn đáng công."},{"id":"LC035","muc":7,"q":"Chữ k trong kNN và chữ K trong K-means có cùng ý nghĩa không?","options":["Có, cả hai đều là số láng giềng","Có, cả hai đều là số cụm","Không, một bên là số láng giềng, một bên là số cụm","Không, một bên là số lớp, một bên là số đặc trưng"],"answer":[2],"multi":false,"why":"Trong kNN, k là số điểm gần nhất được hỏi ý kiến khi phân loại. Trong K-means, K là số cụm cần chia. Một thuật toán có giám sát, một thuật toán không giám sát."},{"id":"M026","muc":7,"q":"Dữ liệu vị trí có các cụm hình cong, kèm nhiều điểm nhiễu lẻ tẻ. Thuật toán gom cụm nào hợp hơn K-means?","options":["Hồi quy logistic","PCA","kNN","DBSCAN"],"answer":[3],"multi":false,"why":"K-means giả định cụm tròn quanh một tâm và buộc mọi điểm vào một cụm. DBSCAN nối các điểm nằm đủ dày gần nhau, nên đi theo được cụm hình cong và để riêng các điểm nhiễu. Ba phương án còn lại không phải thuật toán gom cụm."},{"id":"L025","muc":7,"q":"Bảng dữ liệu có rất nhiều cột. Ta muốn gộp lại thành ít cột hơn mà vẫn giữ phần lớn sự khác nhau giữa các mẫu. Thường dùng phương pháp nào?","options":["K-means","PCA","Rừng ngẫu nhiên","k láng giềng gần nhất (kNN)"],"answer":[1],"multi":false,"why":"PCA (phân tích thành phần chính) tạo ra ít cột tóm tắt hơn từ các cột ban đầu. Đây là cách giảm số chiều. Nó không gom cụm và không gán nhãn."},{"id":"B-L-7-01","muc":7,"q":"Một cụm K-Means gồm ba điểm.\n(1, 2)\n(3, 8)\n(5, 2)\nSau bước cập nhật, tâm mới của cụm là gì?","options":["(3, 4)","(3, 2)","(9, 12)","(1, 2)"],"answer":[0],"multi":false,"why":"Tâm là trung bình từng tọa độ: x = (1 + 3 + 5)/3 = 3 và y = (2 + 8 + 2)/3 = 4. Chọn (3, 2) là lấy trung vị. Chọn (9, 12) là cộng mà quên chia cho 3."},{"id":"B-L-7-02","muc":7,"q":"Cụm {A, B} và điểm C có d(A, C) = 4 và d(B, C) = 6.\nKhoảng cách giữa {A, B} và {C} theo single linkage và theo complete linkage lần lượt là bao nhiêu?","options":["6 và 4","5 và 5","4 và 6","4 và 10"],"answer":[2],"multi":false,"why":"Single linkage lấy khoảng cách nhỏ nhất giữa hai cụm, tức 4. Complete linkage lấy khoảng cách lớn nhất, tức 6. Chọn 6 và 4 là đảo hai loại. Chọn 5 và 5 là lấy trung bình (average linkage)."},{"id":"B-L-7-03","muc":7,"q":"Ma trận hiệp phương sai của một tập dữ liệu có hai trị riêng là 6 và 2.\nNếu chỉ giữ thành phần chính thứ nhất (PC1), tỉ lệ phương sai giữ lại bằng bao nhiêu?","options":["25%","75%","50%","300%"],"answer":[1],"multi":false,"why":"Tỉ lệ phương sai của PC1 là 6/(6 + 2) = 0,75 = 75%. Chọn 25% là tỉ lệ của PC2. Chọn 300% là chia 6 cho 2 thay vì chia cho tổng."},{"id":"B-L-7-04","muc":7,"q":"Chọn tất cả phát biểu đúng về PCA và t-SNE.","options":["Khoảng cách giữa hai cụm trong ảnh t-SNE luôn phản ánh đúng khoảng cách của chúng trong dữ liệu gốc.","PCA cần nhãn lớp của dữ liệu để chạy.","PCA là phép biến đổi tuyến tính.","t-SNE là phép biến đổi phi tuyến và chủ yếu dùng để trực quan hóa."],"answer":[2,3],"multi":true,"why":"PCA chiếu dữ liệu lên các hướng tuyến tính. t-SNE phi tuyến và chủ yếu để vẽ hình. Khoảng cách giữa các cụm trong ảnh t-SNE không đáng tin về mặt định lượng. PCA là phương pháp không giám sát nên không cần nhãn."},{"id":"M052","muc":8,"q":"Ảnh 64 × 64, bộ lọc 3 × 3, stride 1. Cần padding bao nhiêu để đầu ra vẫn là 64 × 64?","options":["1","0","2","3"],"answer":[0],"multi":false,"why":"(64 − 3 + 2p) + 1 = 64 cho p = 1. Quy tắc nhanh: bộ lọc k × k với k lẻ cần padding (k − 1) / 2."},{"id":"M053","muc":8,"q":"Ảnh 28 × 28 đi qua max pooling 2 × 2, stride 2. Đầu ra có kích thước bao nhiêu?","options":["27 × 27","26 × 26","7 × 7","14 × 14"],"answer":[3],"multi":false,"why":"(28 − 2) / 2 + 1 = 14. Mỗi ô 2 × 2 không chồng lên nhau gộp thành một số, nên chiều rộng và chiều cao còn một nửa. Con số 27 là kết quả nếu stride bằng 1."},{"id":"LC054","muc":8,"q":"Vì sao lớp tích chập cần ít tham số hơn hẳn lớp kết nối đầy đủ khi xử lý ảnh?","options":["Mỗi pixel có một trọng số riêng","Chỉ chạy được trên ảnh xám","Bỏ qua hết các pixel ở mép ảnh","Dùng cùng một bộ lọc nhỏ ở mọi vị trí"],"answer":[3],"multi":false,"why":"Một bộ lọc 3 × 3 chỉ có 9 trọng số, nhưng được trượt khắp ảnh để tìm cùng một mẫu ở mọi chỗ. Lớp kết nối đầy đủ thì cần một trọng số cho mỗi cặp pixel và nơ-ron, nên lên tới hàng triệu."},{"id":"LC056","muc":8,"q":"Lớp max pooling 2 × 2 có bao nhiêu tham số cần học?","options":["4","0","1","2 × 2 × số kênh"],"answer":[1],"multi":false,"why":"Max pooling chỉ lấy số lớn nhất trong mỗi ô, không có trọng số nào để học. Nó làm bản đồ đặc trưng nhỏ lại và giúp mạng chịu được dịch chuyển nhỏ."},{"id":"H033","muc":8,"q":"Nơ-ron có đầu vào (2, −1, 3), trọng số (0,5; 2; −1), bias 1 và hàm kích hoạt ReLU. Đầu ra bằng bao nhiêu?","options":["−3","0","3","1"],"answer":[1],"multi":false,"why":"Tổng có trọng số: 0,5·2 + 2·(−1) + (−1)·3 + 1 = 1 − 2 − 3 + 1 = −3. ReLU đưa số âm về 0. Phương án −3 quên áp ReLU."},{"id":"LC048","muc":8,"q":"Một nơ-ron nhận 3 đầu vào và có một bias. Nó có bao nhiêu tham số cần học?","options":["3","1","6","4"],"answer":[3],"multi":false,"why":"Mỗi đầu vào có một trọng số, tức 3 trọng số, cộng thêm 1 bias là 4 tham số."},{"id":"B-L-8-01","muc":8,"q":"Ảnh đầu vào có chiều rộng W = 32.\nLớp Conv2D dùng bộ lọc K = 5, padding P = 0 và stride S = 1.\nChiều rộng đầu ra bằng bao nhiêu?","options":["28","27","32","36"],"answer":[0],"multi":false,"why":"W_out = ⌊(32 − 5 + 2·0)/1⌋ + 1 = 27 + 1 = 28. Chọn 27 là quên +1. Chọn 32 là nhầm với padding giữ nguyên kích thước. Chọn 36 là cộng K thay vì trừ."},{"id":"B-L-8-02","muc":8,"q":"Một lớp Conv2D có bộ lọc 3×3, nhận đầu vào 3 kênh và tạo 4 kênh đầu ra.\nLớp này có bao nhiêu tham số, tính cả bias?","options":["112","108","28","40"],"answer":[0],"multi":false,"why":"Số tham số = (K·K·C_in + 1)·C_out = (3·3·3 + 1)·4 = 28·4 = 112. Chọn 108 là quên bias. Chọn 28 là chỉ tính một bộ lọc. Chọn 40 là quên nhân với số kênh đầu vào."},{"id":"B-L-8-03","muc":8,"q":"Chọn tất cả phát biểu đúng về hàm kích hoạt ReLU.","options":["ReLU(−3) = −3.","Mỗi nơ-ron ReLU có thêm một tham số học được để quyết định độ dốc.","ReLU(x) = max(0, x).","Nơ-ron ReLU có thể bị dying ReLU khi đầu vào luôn âm, vì khi đó gradient bằng 0."],"answer":[2,3],"multi":true,"why":"ReLU giữ số dương và đưa số âm về 0, nên ReLU(−3) = 0. Với đầu vào âm, đạo hàm bằng 0 nên nơ-ron không còn được cập nhật, đó là dying ReLU. ReLU chuẩn không có tham số học."},{"id":"B-L-8-04","muc":8,"q":"Một lớp dropout có xác suất tắt p = 0,5.\nMạng đã huấn luyện xong và đang dùng để dự đoán.\nLớp dropout làm gì lúc này?","options":["Tắt ngẫu nhiên một nửa số nơ-ron, giống lúc huấn luyện.","Tắt cố định một nửa số nơ-ron đầu tiên của lớp.","Dùng tất cả nơ-ron, không tắt nơ-ron nào.","Đặt toàn bộ đầu ra của lớp bằng 0."],"answer":[2],"multi":false,"why":"Dropout chỉ tắt nơ-ron ngẫu nhiên trong lúc huấn luyện để giảm overfit. Khi dự đoán, mọi nơ-ron đều được dùng (với inverted dropout, hệ số bù đã được nhân từ lúc huấn luyện)."},{"id":"A-L-9-01","muc":9,"q":"Một ứng dụng gợi ý phim chỉ dựa vào thể loại, đạo diễn và diễn viên của những phim mà em đã xem. Ứng dụng này thuộc loại hệ gợi ý nào?","options":["Collaborative filtering user-based.","Collaborative filtering item-based.","Học tăng cường.","Content-based (dựa trên nội dung)."],"answer":[3],"multi":false,"why":"Hệ chỉ dùng đặc điểm của chính sản phẩm và hồ sơ người dùng nên là content-based. Collaborative filtering dựa vào điểm đánh giá của nhiều người dùng. Học tăng cường là bài toán khác, có tác nhân và phần thưởng."},{"id":"A-L-9-02","muc":9,"q":"Một từ xuất hiện 3 lần trong tài liệu d. Kho có N = 8 tài liệu, trong đó 2 tài liệu chứa từ này. Em dùng TF là số lần xuất hiện và IDF = log₂(N/DF). TF-IDF của từ trong d bằng bao nhiêu?","options":["12","6","3","9"],"answer":[1],"multi":false,"why":"IDF = log₂(8/2) = log₂ 4 = 2, nên TF-IDF = 3·2 = 6. Số 12 là do quên log (3·4). Số 3 chỉ là TF. Số 9 là do bỏ qua DF (3·log₂ 8)."},{"id":"A-L-9-03","muc":9,"q":"Về collaborative filtering (lọc cộng tác). Chọn tất cả phát biểu đúng.","options":["User-based tìm những người dùng có sở thích giống người cần gợi ý.","Collaborative filtering cần văn bản mô tả của từng sản phẩm.","Item-based dựa trên độ giống giữa các sản phẩm, tính từ điểm đánh giá.","Collaborative filtering không cần dữ liệu đánh giá của người dùng."],"answer":[0,2],"multi":true,"why":"Collaborative filtering chỉ cần ma trận đánh giá: user-based so sánh các hàng (người dùng), item-based so sánh các cột (sản phẩm). Việc cần mô tả sản phẩm là của content-based."},{"id":"A-L-9-04","muc":9,"q":"Em muốn đoán điểm An sẽ chấm một phim. Có hai người giống An. Bình có độ giống 0,6 và đã chấm 5. Chi có độ giống 0,2 và đã chấm 1. Dự đoán = Σ sim·r / Σ |sim|. Điểm dự đoán bằng bao nhiêu?","options":["3,2","3","4","0,8"],"answer":[2],"multi":false,"why":"Tử số: 0,6·5 + 0,2·1 = 3,2. Mẫu số: 0,6 + 0,2 = 0,8. Dự đoán = 3,2/0,8 = 4. Số 3,2 là quên chia. Số 3 là trung bình cộng không trọng số (5 + 1)/2. Số 0,8 chỉ là mẫu số."},{"id":"A-L-9-05","muc":9,"q":"Trong hệ gợi ý, hệ số Pearson giữa hai người dùng được tính như thế nào?","options":["Là cosine của hai vector điểm gốc, không trừ gì.","Là cosine của hai vector điểm sau khi trừ điểm trung bình của từng người.","Là hiệu giữa hai điểm trung bình.","Là tổng hai vector điểm chia cho số sản phẩm."],"answer":[1],"multi":false,"why":"Pearson chính là cosine sau khi đưa mỗi người về trung bình 0. Nhờ vậy người hay chấm cao và người hay chấm thấp vẫn so sánh được. Cosine trên điểm gốc không làm việc đó."},{"id":"A-L-9-06","muc":9,"q":"Tác nhân nhận lần lượt các phần thưởng 3, 2 và 4 ở ba bước đầu, gọi là bước 0, 1 và 2. Hệ số chiết khấu γ = 0,5. Return G = r₀ + γ·r₁ + γ²·r₂ bằng bao nhiêu?","options":["5","9","6","4,5"],"answer":[0],"multi":false,"why":"G = 3 + 0,5·2 + 0,25·4 = 3 + 1 + 1 = 5. Số 9 là tổng không chiết khấu. Số 6 là do dùng γ thay cho γ² ở bước thứ ba (3 + 1 + 2). Số 4,5 là tổng chia đôi."},{"id":"A-L-9-07","muc":9,"q":"Tác nhân dùng chính sách ε-greedy với ε = 0,1. Điều đó có nghĩa gì?","options":["Tác nhân chỉ khám phá trong 10 bước đầu rồi chỉ khai thác.","Mỗi hành động được chọn với xác suất 0,1.","Hệ số chiết khấu γ bằng 0,1.","Với xác suất 0,1 tác nhân chọn hành động ngẫu nhiên (khám phá). Còn lại nó chọn hành động có Q lớn nhất."],"answer":[3],"multi":false,"why":"ε-greedy là sự cân bằng giữa khám phá và khai thác ở mỗi bước: xác suất ε thử ngẫu nhiên, xác suất 1 − ε chọn hành động tốt nhất hiện biết. ε không liên quan đến số bước và không phải γ."},{"id":"A-L-9-08","muc":9,"q":"Tác nhân đang ở trạng thái s và làm hành động a. Giá trị hiện tại là Q(s, a) = 2. Tác nhân nhận phần thưởng r = 4 và sang trạng thái s′, với max Q(s′, ·) = 6. Biết α = 0,5 và γ = 0,5. Q(s, a) mới bằng bao nhiêu?","options":["7","6","3","4,5"],"answer":[3],"multi":false,"why":"Mục tiêu = r + γ·max Q(s′, ·) = 4 + 0,5·6 = 7. Q mới = 2 + 0,5·(7 − 2) = 4,5. Số 7 là mục tiêu, chưa cập nhật. Số 6 là do quên γ ở mục tiêu (4 + 6 = 10 rồi 2 + 0,5·8). Số 3 là do bỏ phần max (2 + 0,5·(4 − 2))."},{"id":"A-L-9-09","muc":9,"q":"Về quá trình quyết định Markov (MDP) và học tăng cường. Chọn tất cả phát biểu đúng.","options":["Hệ số γ gần 0 làm tác nhân chỉ quan tâm phần thưởng gần.","Q-learning phải biết trước xác suất chuyển trạng thái của môi trường.","Hệ số γ gần 1 làm tác nhân nhìn xa hơn.","Policy (chính sách) là quy tắc chọn hành động ứng với mỗi trạng thái."],"answer":[0,2,3],"multi":true,"why":"γ nhỏ thì phần thưởng xa bị chiết khấu mạnh, γ lớn thì giữ được giá trị của tương lai. Policy ánh xạ trạng thái sang hành động. Q-learning là phương pháp không cần mô hình môi trường (model-free), nó học từ trải nghiệm."},{"id":"A-L-9-10","muc":9,"q":"Tác nhân luôn chọn hành động có Q lớn nhất và không bao giờ thử hành động khác. Tác nhân này đang thiếu điều gì?","options":["Khai thác (exploitation).","Hệ số chiết khấu.","Khám phá (exploration).","Phần thưởng."],"answer":[2],"multi":false,"why":"Chỉ chọn hành động tốt nhất hiện biết là khai thác thuần túy. Tác nhân có thể kẹt ở hành động chưa tốt vì chưa bao giờ thử những hành động còn lại. Cần khám phá, chẳng hạn bằng ε-greedy."},{"id":"B-L-10-01","muc":10,"q":"Đồ thị có hướng sau có đỉnh xuất phát là S, đích là G.\nS → A\nS → B\nA → C\nA → D\nB → D\nB → E\nC → G\nD → G\nE → G\nBFS dùng hàng đợi (queue) và xét các đỉnh kề theo thứ tự bảng chữ cái.\nBFS mở các đỉnh theo thứ tự nào, cho đến khi mở G?","options":["S, A, C, G","S, B, A, E, D, C, G","S, B, E, G","S, A, B, C, D, E, G"],"answer":[3],"multi":false,"why":"BFS mở theo từng tầng: S, rồi A và B, rồi C, D, E, rồi G. Đỉnh nào vào hàng đợi trước thì được mở trước. Các phương án khác là thứ tự của DFS hoặc của BFS xét đỉnh kề theo thứ tự ngược."},{"id":"B-L-10-02","muc":10,"q":"Đồ thị có hướng sau có đỉnh xuất phát là S, đích là G.\nS → A\nS → B\nA → C\nA → D\nC → E\nD → G\nB → G\nDFS đi sâu nhất có thể, xét các đỉnh kề theo thứ tự bảng chữ cái, và quay lui khi hết đường.\nDFS thăm các đỉnh theo thứ tự nào, cho đến khi thăm G?","options":["S, A, B, C, D, G","S, B, G","S, A, C, E, D, G","S, B, A, G"],"answer":[2],"multi":false,"why":"DFS đi S → A → C → E rồi gặp ngõ cụt, nên quay lui về A để đi tiếp D, rồi G. Thứ tự là S, A, C, E, D, G. Phương án S, A, B, C, D, G là thứ tự của BFS."},{"id":"B-L-10-03","muc":10,"q":"A* đang có bốn đỉnh trong tập biên (frontier).\nA: g = 2, h = 6\nB: g = 5, h = 2\nC: g = 3, h = 3\nD: g = 1, h = 8\nA* mở đỉnh nào tiếp theo?","options":["A","B","D","C"],"answer":[3],"multi":false,"why":"A* chọn đỉnh có f = g + h nhỏ nhất. Ta có f(A) = 8, f(B) = 7, f(C) = 6, f(D) = 9. Vậy A* mở C. Đỉnh D là lựa chọn của UCS (g nhỏ nhất), đỉnh B là lựa chọn của greedy best-first (h nhỏ nhất)."},{"id":"B-L-10-04","muc":10,"q":"Từ đỉnh X đến đích, chi phí thật nhỏ nhất là h*(X) = 6.\nChọn tất cả giá trị h(X) mà heuristic vẫn admissible (chấp nhận được) tại đỉnh X.","options":["h(X) = 4","h(X) = 6","h(X) = 7","h(X) = 0"],"answer":[0,1,3],"multi":true,"why":"Heuristic admissible khi h(X) ≤ h*(X) = 6. Các giá trị 0, 4 và 6 thỏa mãn. Giá trị 7 đánh giá cao hơn chi phí thật nên không admissible."},{"id":"B-L-10-05","muc":10,"q":"Cây trò chơi có gốc R là nút MAX. Mỗi nút con của R là nút MIN. Các lá ghi giá trị cho MAX.\nR (MAX): M1, M2, M3\nM1 (MIN): 6, 9\nM2 (MIN): 4, 8\nM3 (MIN): 7, 5\nGiá trị minimax của gốc R bằng bao nhiêu?","options":["4","6","5","9"],"answer":[1],"multi":false,"why":"Nút MIN lấy giá trị nhỏ nhất: M1 = 6, M2 = 4, M3 = 5. Nút MAX ở gốc lấy lớn nhất của ba giá trị đó, tức 6. Chọn 9 là lấy lá lớn nhất của toàn cây. Chọn 4 là lấy giá trị nhỏ nhất ở gốc."},{"id":"B-L-10-06","muc":10,"q":"Cây trò chơi có gốc R là nút MAX, các nút con là nút MIN. Alpha-beta duyệt các lá từ trái sang phải.\nR (MAX): M1, M2, M3\nM1 (MIN): 7, 4\nM2 (MIN): 3, 8\nM3 (MIN): 1, 10\nAlpha-beta cắt tỉa (không cần duyệt) bao nhiêu lá?","options":["0","1","3","2"],"answer":[3],"multi":false,"why":"M1 cho giá trị 4, nên α = 4 ở gốc. Ở M2, lá đầu tiên là 3 ≤ 4 nên M2 không thể vượt 4, ta bỏ lá 8. Ở M3, lá đầu tiên là 1 ≤ 4 nên bỏ lá 10. Vậy có 2 lá bị cắt."},{"id":"B-L-10-07","muc":10,"q":"Một bài toán CSP có bốn biến với miền giá trị như sau.\nP ∈ {1, 2, 3}\nQ ∈ {1, 2}\nR ∈ {3}\nS ∈ {2, 3}\nTheo heuristic MRV (minimum remaining values), ta nên gán biến nào trước?","options":["P","Q","S","R"],"answer":[3],"multi":false,"why":"MRV chọn biến có ít giá trị còn lại nhất. Biến R chỉ còn 1 giá trị nên được chọn trước. P có 3 giá trị, Q và S đều có 2."},{"id":"B-L-10-08","muc":10,"q":"Chọn tất cả cặp biểu thức tương đương.","options":["¬(P ∨ Q) và ¬P ∧ ¬Q","P → Q và Q → P","P → Q và ¬P ∨ Q","¬(P ∧ Q) và ¬P ∧ ¬Q"],"answer":[0,2],"multi":true,"why":"Theo định luật De Morgan, ¬(P ∨ Q) ≡ ¬P ∧ ¬Q. Phép kéo theo P → Q tương đương ¬P ∨ Q. Còn ¬(P ∧ Q) ≡ ¬P ∨ ¬Q chứ không phải ¬P ∧ ¬Q. P → Q và Q → P không tương đương: khi P sai và Q đúng thì P → Q đúng nhưng Q → P sai."},{"id":"B-L-10-09","muc":10,"q":"Một bạn cần dự đoán giá nhà (đơn vị: triệu đồng) từ diện tích, số phòng và tuổi nhà.\nBạn ấy nên chọn tổ hợp nào?","options":["Bài toán phân loại. Dùng log loss, đánh giá bằng accuracy.","Bài toán hồi quy. Dùng MSE làm loss, đánh giá bằng RMSE.","Bài toán hồi quy. Dùng cross-entropy làm loss, đánh giá bằng F1.","Bài toán phân loại. Dùng hinge loss, đánh giá bằng precision."],"answer":[1],"multi":false,"why":"Giá nhà là một số thực, nên đây là bài toán hồi quy. Loss thường dùng là MSE, metric là RMSE hoặc MAE. Accuracy, F1, precision và cross-entropy đều dành cho bài toán phân loại."},{"id":"B-L-10-10","muc":10,"q":"Một bệnh viện huấn luyện mô hình phát hiện bệnh hiếm. Chỉ 1% bệnh nhân mắc bệnh.\nBỏ sót bệnh nhân rất nguy hiểm.\nChọn tất cả lựa chọn hợp lý.","options":["Tính z-score trên toàn bộ dữ liệu trước khi chia train/test cho tiện.","Chỉ dùng accuracy, vì mô hình đoán \"không bệnh\" cho mọi người vẫn đạt 99%.","Dùng stratified k-fold để mỗi fold đều có bệnh nhân.","Theo dõi recall (TPR) hoặc PR-AUC thay vì chỉ nhìn accuracy."],"answer":[2,3],"multi":true,"why":"Dữ liệu lệch lớp thì accuracy đánh lừa: đoán tất cả là \"không bệnh\" đã đạt 99% mà bỏ sót mọi bệnh nhân. Recall và PR-AUC phản ánh việc phát hiện lớp hiếm, còn stratified k-fold giữ tỉ lệ lớp trong từng fold. Tính z-score trên toàn bộ dữ liệu là data leakage."}]},{"id":"medium","title":"Medium","minutes":180,"questions":[{"id":"MB026","muc":1,"q":"Giá nhà lệch phải mạnh: đa số vài tỷ, một số căn vài trăm tỷ. Huấn luyện hồi quy để dự đoán log(giá) thay cho giá thường giúp gì?","options":["Mô hình chắc chắn đạt MSE bằng 0 trên train","Không cần chia train và test nữa","Sai số theo tỉ lệ, căn đắt không lấn át","Giá dự đoán luôn đúng tới từng đồng"],"answer":[2],"multi":false,"why":"Trên thang log, đoán lệch 10% ở căn 3 tỷ hay căn 300 tỷ cho sai số như nhau. Nếu học trên giá gốc, vài căn đắt chiếm gần hết MSE. Khi dự đoán, nhớ đổi ngược bằng hàm mũ."},{"id":"M022","muc":1,"q":"Thu nhập lên tới 500 000, còn tuổi chỉ từ 18 đến 80. Vì sao chuẩn hóa giúp hồi quy logistic học bằng gradient descent nhanh hơn?","options":["Chuẩn hóa xóa các giá trị ngoại lai trong dữ liệu","Bước cập nhật cân bằng hơn giữa các trọng số","Chuẩn hóa biến mô hình thành mô hình phi tuyến","Chuẩn hóa thêm đặc trưng mới cho mô hình"],"answer":[1],"multi":false,"why":"Cột có số rất lớn làm gradient theo trọng số của nó lấn át các cột khác. Bước đi phải nhỏ để khỏi văng ra xa, nên các trọng số còn lại học rất chậm. Chuẩn hóa không xóa ngoại lai và không đổi bản chất tuyến tính của mô hình."},{"id":"E005","muc":1,"q":"Cột tuổi trong train nằm từ 20 đến 60. MinMaxScaler được fit trên train. Một mẫu test có tuổi 70 sẽ được biến thành bao nhiêu?","options":["1","0,875","0,5","1,25"],"answer":[3],"multi":false,"why":"(70 − 20)/(60 − 20) = 1,25. MinMaxScaler không tự kẹp về [0, 1]; giá trị ngoài khoảng của train sẽ ra ngoài [0, 1]. Đó là chuyện bình thường, không phải lỗi."},{"id":"HB011","muc":1,"q":"Cột có giá trị 2, 4, 8 và hai ô trống. Điền hai ô trống bằng trung bình cột. Phương sai của cột sau khi điền so với phương sai của ba giá trị có sẵn thế nào?","options":["Lớn hơn","Bằng nhau","Nhỏ hơn","Không xác định được"],"answer":[2],"multi":false,"why":"Trung bình vẫn là 14/3, nhưng hai giá trị mới lệch 0 so với trung bình, nên phương sai giảm từ khoảng 6,22 xuống 3,73. Mô hình thấy cột “ổn định” hơn thực tế, nên hay thêm cột đánh dấu ô bị điền."},{"id":"MB019","muc":1,"q":"Dữ liệu tín dụng có cột số (thu nhập, tuổi), cột hạng mục (nghề nghiệp), 15% ô trống và vài thu nhập cực lớn. Quy trình tiền xử lý nào hợp lý nhất?","options":["Điền trung vị hoặc mode, chặn ngoại lai, chuẩn hóa, one-hot","Xóa mọi dòng thiếu, đưa về [0, 1], mã hóa nghề thành 1, 2, 3","Điền 0 vào ô trống, xóa dòng ngoại lai, để nguyên cột số","Chạy PCA trước rồi mới điền các giá trị bị thiếu"],"answer":[0],"multi":false,"why":"Trung vị không bị thu nhập cực lớn kéo lệch. Chặn ngoại lai rồi chuẩn hóa giúp các cột cùng thang đo. One-hot không áp đặt thứ tự cho nghề nghiệp. Mọi thông số như trung vị hay ngưỡng chặn chỉ được tính trên tập huấn luyện."},{"id":"H010","muc":1,"q":"Với phương pháp nào, chuẩn hóa thang đo các đặc trưng đầu vào gần như không làm đổi dự đoán?","options":["Mạng nơ-ron","SVM với lề mềm","kNN","Cây quyết định"],"answer":[3],"multi":false,"why":"Cây chỉ so từng đặc trưng với một ngưỡng. Đổi thang đo thì ngưỡng dời theo, cách chia dữ liệu vẫn y nguyên. kNN và SVM dựa vào khoảng cách hoặc tích vô hướng, còn mạng nơ-ron học bằng gradient, nên đều bị thang đo ảnh hưởng."},{"id":"A-M-1-01","muc":1,"q":"Một cột trên tập train gồm tám số 2, 4, 4, 4, 5, 5, 7, 9. Trung bình là 5 và độ lệch chuẩn tổng thể là 2. Em chuẩn hóa z-score bằng hai tham số này từ train. Một mẫu test có giá trị 11. Sau khi chuẩn hóa, mẫu này bằng bao nhiêu?","options":["6","1,5","3","2,2"],"answer":[2],"multi":false,"why":"z = (11 − 5)/2 = 3. Số 6 là do quên chia cho độ lệch chuẩn. Số 1,5 là do chia cho phương sai 4 thay vì độ lệch chuẩn. Số 2,2 là do chia cho trung bình (11/5)."},{"id":"A-M-1-02","muc":1,"q":"Chọn tất cả cách làm gây rò rỉ dữ liệu (data leakage).","options":["Tính median của toàn bộ dữ liệu để điền chỗ thiếu, rồi mới chia train và test.","Fit one-hot encoder trên train rồi dùng nó biến đổi test.","Fit scaler trên train rồi dùng lại tham số đó cho test.","Chọn đặc trưng theo độ tương quan với nhãn, tính trên toàn bộ dữ liệu gồm cả test."],"answer":[0,3],"multi":true,"why":"Median tính trên toàn bộ dữ liệu và việc chọn đặc trưng bằng nhãn của test đều đưa thông tin của test vào lúc huấn luyện. Hai cách còn lại là quy trình chuẩn: học tham số trên train, áp dụng cho test."},{"id":"A-M-1-03","muc":1,"q":"Cột thu nhập (triệu đồng) trên tập train có các giá trị 10, 12, 11 và 200, cùng một ô bị thiếu. Có ngoại lai 200 nên em điền ô thiếu bằng median của các giá trị có sẵn. Giá trị điền vào là bao nhiêu?","options":["11,5","58,25","12","46,6"],"answer":[0],"multi":false,"why":"Sắp xếp 10, 11, 12, 200. Median là trung bình hai số giữa: (11 + 12)/2 = 11,5. Số 58,25 là mean, bị ngoại lai 200 kéo lên. Số 12 là lấy nhầm phần tử thứ ba. Số 46,6 là mean khi coi ô thiếu bằng 0 (233/5)."},{"id":"A-M-1-04","muc":1,"q":"Một bảng có ba cột: màu (3 giá trị khác nhau), hãng (4 giá trị khác nhau) và giá (số thực). Em one-hot hai cột chữ, không bỏ cột nào, và giữ nguyên cột giá. Bảng mới có bao nhiêu cột?","options":["13","8","7","12"],"answer":[1],"multi":false,"why":"Màu cho 3 cột, hãng cho 4 cột, giá giữ 1 cột, tổng 3 + 4 + 1 = 8. Số 12 là do nhân 3·4. Số 13 là 12 cộng thêm cột giá. Số 7 là quên cột giá."},{"id":"M010","muc":2,"q":"Mô hình bắt được 180 trong 200 vụ gian lận, đồng thời gắn cờ nhầm 294 giao dịch bình thường. Đội kiểm tra xem tay được mọi giao dịch bị gắn cờ, còn bỏ sót một vụ gian lận thì rất tốn kém. Nên ưu tiên chỉ số nào?","options":["Recall của lớp gian lận","Accuracy trên toàn bộ giao dịch","Precision của lớp gian lận","Tỉ lệ giao dịch không bị gắn cờ"],"answer":[0],"multi":false,"why":"Bỏ sót thì đắt, còn báo nhầm thì rẻ vì có người xem lại. Vậy cần recall cao, ở đây là 180 / 200 = 90%. Precision chỉ khoảng 180 / 474 ≈ 38%, nhưng chấp nhận được trong hoàn cảnh này."},{"id":"MB006","muc":2,"q":"Có 20% mẫu mang nhãn dương. Một bộ phân loại luôn đoán dương. Precision và recall của nó bằng bao nhiêu?","options":["Precision 0,2, recall 1","Precision 1, recall 0,2","Precision 0,2, recall 0,2","Precision 0,8, recall 1"],"answer":[0],"multi":false,"why":"Mọi mẫu dương đều được đoán dương, nên recall = 1. Nhưng trong số mẫu bị đoán dương, chỉ 20% là dương thật, nên precision = 0,2. Vì vậy chỉ nhìn recall thì không đủ."},{"id":"HB023","muc":2,"q":"Nhãn thật là 2, 4, 6, dự đoán là 3, 4, 5. Hệ số xác định R² bằng bao nhiêu?","options":["0,25","0,75","0,5","0,9"],"answer":[1],"multi":false,"why":"Tổng bình phương sai số là 1 + 0 + 1 = 2. Tổng bình phương lệch khỏi trung bình 4 là 4 + 0 + 4 = 8. R² = 1 − 2/8 = 0,75, tức mô hình giải thích được 75% độ biến thiên của nhãn."},{"id":"HB007","muc":2,"q":"Báo nhầm (FP) tốn 1, bỏ sót (FN) tốn 10. Mô hình A: TP = 80, FP = 20, FN = 30, TN = 870. Mô hình B: TP = 60, FP = 5, FN = 50, TN = 885. Chọn mô hình nào?","options":["A, tổng chi phí 320 so với 505","B, vì báo nhầm ít hơn hẳn A","A, tổng chi phí 300 so với 500","Như nhau, vì accuracy gần bằng nhau"],"answer":[0],"multi":false,"why":"Chi phí A = 20·1 + 30·10 = 320, chi phí B = 5·1 + 50·10 = 505. Accuracy lần lượt 0,95 và 0,945, gần như nhau, nhưng B bỏ sót nhiều hơn mà bỏ sót đắt gấp 10."},{"id":"M013","muc":2,"q":"Một mô hình có AUC bằng 0,5. Điều này nghĩa là gì?","options":["Xếp hạng không hơn đoán ngẫu nhiên","Accuracy của mô hình bằng 50%","Xếp hạng hoàn hảo mọi cặp mẫu","Mô hình luôn đoán sai mọi mẫu"],"answer":[0],"multi":false,"why":"AUC là xác suất một mẫu dương bất kỳ được mô hình cho điểm cao hơn một mẫu âm bất kỳ. Mức 0,5 giống tung đồng xu, còn 1 là xếp hạng hoàn hảo. AUC bằng 0,5 không có nghĩa là accuracy bằng 50%."},{"id":"M007","muc":2,"q":"Chỉ 1% giao dịch là gian lận. Chỉ số nào dễ gây hiểu lầm nhất khi đánh giá mô hình phát hiện gian lận?","options":["Recall của lớp gian lận","Accuracy","Precision của lớp gian lận","F1 của lớp gian lận"],"answer":[1],"multi":false,"why":"Mô hình luôn đoán “bình thường” đã đạt 99% accuracy mà không bắt được vụ nào. Precision, recall và F1 của lớp gian lận đều cho thấy ngay vấn đề này."},{"id":"A-M-2-01","muc":2,"q":"Mô hình cho điểm 6 mẫu như sau.\n0,9 nhãn dương\n0,8 nhãn dương\n0,7 nhãn âm\n0,6 nhãn dương\n0,4 nhãn âm\n0,2 nhãn âm\nEm dự đoán dương khi điểm ≥ 0,5. TPR và FPR bằng bao nhiêu?","options":["TPR = 2/3 và FPR = 1/3","TPR = 1 và FPR = 2/3","TPR = 1 và FPR = 1/4","TPR = 1 và FPR = 1/3"],"answer":[3],"multi":false,"why":"Dự đoán dương gồm các mẫu 0,9, 0,8, 0,7, 0,6, trong đó TP = 3 và FP = 1. Có 3 mẫu dương và 3 mẫu âm, nên TPR = 3/3 = 1 và FPR = 1/3. TPR = 2/3 là khi bỏ sót mẫu 0,6. FPR = 2/3 là chia nhầm cho số mẫu dương dự đoán. 1/4 là 1 − precision (FP/(TP + FP)), không phải FPR."},{"id":"A-M-2-02","muc":2,"q":"Em hạ ngưỡng phân loại từ 0,7 xuống 0,4 trên cùng một tập dữ liệu và cùng một mô hình. Chọn tất cả phát biểu đúng.","options":["Precision chắc chắn tăng.","TPR không giảm.","FPR không giảm.","Số mẫu được dự đoán dương không giảm."],"answer":[1,2,3],"multi":true,"why":"Hạ ngưỡng chỉ có thể thêm mẫu vào nhóm dự đoán dương, không bỏ mẫu nào. Vì thế TP, FP và số dự đoán dương đều không giảm, nên TPR và FPR không giảm. Precision có thể tăng, giảm hoặc giữ nguyên."},{"id":"A-M-2-03","muc":2,"q":"Mô hình hồi quy sai lệch 1, 1, 1 và 9 đơn vị (tính theo trị tuyệt đối) trên bốn mẫu. MSE của mô hình bằng bao nhiêu?","options":["3","21","9","84"],"answer":[1],"multi":false,"why":"MSE = (1 + 1 + 1 + 81)/4 = 84/4 = 21. Số 3 là MAE. Số 9 là bình phương của MAE (3²). Số 84 là tổng bình phương chưa chia cho 4. Ngoại lai 9 làm MSE lớn gấp nhiều lần MAE."},{"id":"A-M-2-04","muc":2,"q":"Một mô hình có precision = 0,6 và recall = 0,3. F1 của mô hình bằng bao nhiêu?","options":["0,4","0,45","0,18","0,3"],"answer":[0],"multi":false,"why":"F1 = 2PR/(P + R) = 2·0,6·0,3/0,9 = 0,36/0,9 = 0,4. Số 0,45 là trung bình cộng. Số 0,18 là tích P·R, chưa nhân 2 và chia (P + R). Số 0,3 là giá trị nhỏ hơn trong hai số."},{"id":"MB024","muc":3,"q":"Tăng dần lượng dữ liệu huấn luyện, lỗi train và lỗi validation tiến lại gần nhau rồi cùng đi ngang ở mức khoảng 30%, cao hơn hẳn mức mong muốn. Nên làm gì tiếp?","options":["Dùng mô hình mạnh hơn, thêm đặc trưng","Thu thập thêm thật nhiều dữ liệu nữa","Tăng mạnh hệ số regularization","Giảm bớt số đặc trưng đang dùng"],"answer":[0],"multi":false,"why":"Hai đường gặp nhau ở mức lỗi cao là dấu hiệu chưa khớp (bias cao). Thêm dữ liệu không giúp nữa vì hai đường đã phẳng. Cần mô hình đủ sức biểu diễn hơn. Tăng regularization hay bớt đặc trưng chỉ làm mô hình yếu thêm."},{"id":"M003","muc":3,"q":"Có 50 bệnh nhân, mỗi người 100 chỉ số xét nghiệm. Mô hình đạt 98% trên train nhưng chỉ 62% trên validation. Nguyên nhân chính là gì?","options":["Mọi mô hình học máy đều cần ít nhất 1000 mẫu dữ liệu","Dữ liệu lệch lớp nên mô hình chỉ đoán một lớp","Số đặc trưng nhiều hơn số mẫu, mô hình dễ học thuộc","Các chỉ số khác đơn vị nên mô hình không hội tụ"],"answer":[2],"multi":false,"why":"Với 100 đặc trưng mà chỉ có 50 mẫu, mô hình đủ “tự do” để khớp cả nhiễu trong train. Có thể chọn bớt đặc trưng, thêm regularization hoặc thu thêm dữ liệu. Không có ngưỡng 1000 mẫu bắt buộc nào. Còn nếu mô hình chỉ đoán một lớp thì điểm train đã không lên tới 98%."},{"id":"MC008","muc":3,"q":"Có người nói: mô hình có bias cao thì chắc chắn variance thấp. Câu đó đúng không?","options":["Sai, đoán bừa có cả bias lẫn variance cao","Đúng, bias và variance luôn ngược chiều","Đúng, vì bias cao là mô hình quá đơn giản","Sai, vì bias và variance luôn bằng nhau"],"answer":[0],"multi":false,"why":"Bias và variance thường đánh đổi khi ta chỉnh độ phức tạp, nhưng không có định luật nào buộc chúng ngược chiều. Một mô hình đoán ngẫu nhiên lệch xa đáp án trung bình (bias cao) và mỗi lần chạy một kiểu (variance cao)."},{"id":"MB033","muc":3,"q":"Có 10 điểm dữ liệu với x khác nhau. Khớp một đa thức bậc 9 bằng bình phương tối thiểu. Lỗi trên train và trên điểm mới thường thế nào?","options":["Lỗi train lớn, nhưng lỗi trên điểm mới nhỏ","Cả hai đều bằng 0 vì khớp hoàn hảo","Lỗi train bằng 0, trên điểm mới thường lớn","Cả hai đều lớn như khi dùng đường thẳng"],"answer":[2],"multi":false,"why":"Đa thức bậc 9 có 10 hệ số, đủ để đi qua đúng 10 điểm, nên lỗi train bằng 0. Nhưng để đi qua mọi điểm, nó phải uốn lượn mạnh giữa các điểm, nên đoán điểm mới rất tệ. Đây là ví dụ kinh điển của quá khớp."},{"id":"HB005","muc":3,"q":"Mô hình có lỗi train 2% và lỗi kiểm định chéo 18%. Vẽ theo số mẫu train, lỗi kiểm định gần như đi ngang. Bước tiếp theo hợp lý nhất là gì?","options":["Thêm đặc trưng đa thức bậc cao","Tăng λ hoặc bỏ bớt đặc trưng","Giảm hệ số regularization λ","Thu thêm gấp đôi dữ liệu train"],"answer":[1],"multi":false,"why":"Khoảng cách lớn giữa lỗi train và lỗi kiểm định là dấu hiệu variance cao. Đường kiểm định đã đi ngang nên thêm dữ liệu khó giúp, cần giảm độ phức tạp. Thêm đặc trưng hay giảm λ làm variance tăng thêm."},{"id":"M004","muc":3,"q":"Nhóm A thử 50 cấu hình, lần nào cũng xem điểm trên test, rồi báo cáo điểm cao nhất là 94,2%. Nhóm B chọn cấu hình bằng validation và chỉ đánh giá trên test một lần, được 91,8%. Con số nào đáng tin hơn?","options":["Của nhóm A, vì đã thử nhiều cấu hình hơn","Của nhóm A, vì đo trên test nhiều lần nên chắc hơn","Hai con số đáng tin như nhau","Của nhóm B, vì test không tham gia vào việc chọn"],"answer":[3],"multi":false,"why":"Khi dùng test để chọn trong 50 lần thử, ta vô tình chọn cấu hình hợp với chính tập test đó. Điểm 94,2% vì thế đẹp hơn thực tế. Nhóm B giữ test sạch đến cuối, nên 91,8% mới gần với kết quả trên dữ liệu mới."},{"id":"A-M-3-01","muc":3,"q":"Em huấn luyện cây quyết định với ba độ sâu khác nhau.\nĐộ sâu 2 có lỗi train 20% và lỗi validation 22%.\nĐộ sâu 5 có lỗi train 8% và lỗi validation 12%.\nĐộ sâu 10 có lỗi train 1% và lỗi validation 25%.\nChọn tất cả phát biểu đúng.","options":["Độ sâu 5 cho lỗi validation thấp nhất nên được chọn.","Độ sâu 10 bị overfit.","Độ sâu 10 tốt nhất vì có lỗi train thấp nhất.","Độ sâu 2 bị underfit."],"answer":[0,1,3],"multi":true,"why":"Ta chọn mô hình theo lỗi validation, và đó là độ sâu 5 (12%). Độ sâu 10 có khoảng cách train–validation rất lớn (1% so với 25%), tức overfit. Độ sâu 2 có lỗi cao ở cả hai tập, tức underfit."},{"id":"A-M-3-02","muc":3,"q":"Một mô hình có lỗi 2% trên train và 20% trên validation. Chọn tất cả cách có thể giúp giảm hiện tượng này.","options":["Thêm các đặc trưng đa thức bậc cao.","Thêm dữ liệu huấn luyện.","Tăng hệ số regularization.","Giảm độ phức tạp của mô hình."],"answer":[1,2,3],"multi":true,"why":"Đây là overfit (variance cao). Thêm dữ liệu, regularization mạnh hơn hoặc mô hình đơn giản hơn đều làm giảm variance. Thêm đặc trưng đa thức bậc cao làm mô hình linh hoạt hơn nên overfit nặng thêm."},{"id":"A-M-3-03","muc":3,"q":"Một mô hình có hàm lỗi L = MSE + λ·Σ wᵢ². Với các trọng số w = (3, 4), λ = 0,1 và MSE = 2, giá trị L bằng bao nhiêu?","options":["2,7","2,5","4,5","27"],"answer":[2],"multi":false,"why":"Σ wᵢ² = 9 + 16 = 25, hình phạt là 0,1·25 = 2,5. L = 2 + 2,5 = 4,5. Số 2,7 là hình phạt L1 (0,1·7) cộng MSE. Số 2,5 là chỉ có hình phạt, quên cộng MSE. Số 27 là quên nhân λ."},{"id":"A-M-3-04","muc":3,"q":"Một mô hình có các trọng số w = (0, 5, −2). Hình phạt L1 là λ·Σ |wᵢ| với λ = 0,5. Giá trị hình phạt bằng bao nhiêu?","options":["14,5","1,5","7","3,5"],"answer":[3],"multi":false,"why":"Σ |wᵢ| = 0 + 5 + 2 = 7, nên hình phạt là 0,5·7 = 3,5. Số 14,5 là hình phạt L2 (0,5·29). Số 1,5 là do bỏ dấu giá trị tuyệt đối (0,5·(0 + 5 − 2)). Số 7 là quên nhân λ."},{"id":"MC005","muc":4,"q":"50 điểm dữ liệu có trung bình 40. Thêm một điểm có giá trị 142. Trung bình mới là bao nhiêu?","options":["91","41","40","42"],"answer":[3],"multi":false,"why":"Tổng cũ là 50 × 40 = 2000, tổng mới 2142, chia cho 51 được 42. Lấy trung bình của 40 và 142 là sai, vì số 40 đại diện cho cả 50 điểm. Một điểm lệch xa đã kéo trung bình lên 2 đơn vị."},{"id":"H021","muc":4,"q":"Có 40% email là thư rác. Chữ “free” xuất hiện trong 50% thư rác và 10% thư thường. Một email có chữ “free”, xác suất nó là thư rác xấp xỉ bao nhiêu?","options":["0,50","0,77","0,20","0,83"],"answer":[1],"multi":false,"why":"Theo Bayes: P(rác | free) = 0,4·0,5 / (0,4·0,5 + 0,6·0,1) = 0,20/0,26 ≈ 0,77. Con số 0,20 quên chia cho P(free); 0,83 bỏ qua tỉ lệ thư rác ban đầu."},{"id":"H006","muc":4,"q":"Cho f(x, y) = x²y + 3y. Gradient của f tại điểm (1, 2) là gì?","options":["(2, 4)","(4, 1)","(8, 4)","(4, 4)"],"answer":[3],"multi":false,"why":"∂f/∂x = 2xy = 4 và ∂f/∂y = x² + 3 = 4 tại (1, 2). Con số 8 là giá trị của f tại điểm đó, không phải đạo hàm."},{"id":"HB016","muc":4,"q":"Ma trận đối xứng 2 × 2 có trị riêng 7 ứng với vector riêng (1, 1), và trị riêng 1. Ma trận đó là gì?","options":["[[4, 3], [3, 4]]","[[7, 0], [0, 1]]","[[4, −3], [−3, 4]]","[[1, 3], [3, 7]]"],"answer":[0],"multi":false,"why":"Ma trận đối xứng có vector riêng vuông góc nhau, nên trị riêng 1 ứng với (1, −1). Thử lại: [[4, 3], [3, 4]]·(1, 1) = (7, 7) và ·(1, −1) = (1, −1). Ma trận có dấu trừ thì đổi vai hai trị riêng."},{"id":"MB015","muc":4,"q":"Thu nhập trong một vùng lệch phải: đa số ở mức vừa, vài người rất cao. Thứ tự thường gặp của trung bình, trung vị và yếu vị (mode) là gì?","options":["Yếu vị > trung vị > trung bình","Trung bình = trung vị = yếu vị","Trung vị > trung bình > yếu vị","Trung bình > trung vị > yếu vị"],"answer":[3],"multi":false,"why":"Yếu vị nằm ở đỉnh, chỗ đông người nhất. Vài thu nhập rất cao kéo trung bình sang phải nhiều nhất, còn trung vị chỉ dịch một chút. Vì vậy với thu nhập, giá nhà, người ta hay báo trung vị."},{"id":"H078","muc":4,"q":"Các từ có embedding w1 = (1, 0, 1), w2 = (1, 1, 0), w3 = (2, 0, 2), w4 = (0, 1, 0). Theo độ tương đồng cosine, từ nào gần w1 nhất?","options":["w2","w4","w2 và w3 bằng nhau","w3"],"answer":[3],"multi":false,"why":"w3 = 2·w1 nên cùng hướng, cosine bằng 1. cos(w1, w2) = 1/(√2·√2) = 0,5, còn cos(w1, w4) = 0. Cosine không quan tâm độ dài vector."},{"id":"A-M-4-01","muc":4,"q":"Cho ma trận A có hàng thứ nhất là (4, 1) và hàng thứ hai là (2, 3). Chọn tất cả phát biểu đúng.","options":["Vết (trace) của A bằng 7.","4 là một trị riêng của A, vì 4 nằm trên đường chéo.","Định thức của A bằng 10.","Hai trị riêng của A là 2 và 5."],"answer":[0,2,3],"multi":true,"why":"Vết = 4 + 3 = 7 và định thức = 4·3 − 1·2 = 10. Trị riêng thỏa λ² − 7λ + 10 = 0, tức λ = 2 hoặc λ = 5. Phần tử trên đường chéo chỉ là trị riêng khi ma trận là tam giác, và 4 không thỏa phương trình đặc trưng."},{"id":"A-M-4-02","muc":4,"q":"Em tối thiểu hóa f(w) = (w − 1)². Điểm xuất phát là w = 5 và learning rate η = 0,25. Sau 2 bước gradient descent, w bằng bao nhiêu?","options":["3","1","3,25","2"],"answer":[3],"multi":false,"why":"Đạo hàm là 2(w − 1). Bước 1: w = 5 − 0,25·8 = 3. Bước 2: w = 3 − 0,25·4 = 2. Số 3 là mới sau một bước. Số 1 là kết quả khi η = 0,5. Số 3,25 là do dùng đạo hàm (w − 1) thiếu hệ số 2."},{"id":"A-M-4-03","muc":4,"q":"Trong các thư spam của tập train, tổng số từ là 20, trong đó từ “free” xuất hiện 4 lần. Từ điển có |V| = 10 từ. Em làm trơn Laplace: P(free | spam) = (count + 1)/(count(spam) + |V|). Giá trị này bằng bao nhiêu?","options":["1/5","1/6","1/4","2/15"],"answer":[1],"multi":false,"why":"P = (4 + 1)/(20 + 10) = 5/30 = 1/6. Số 1/5 là 4/20, không làm trơn. Số 1/4 là 5/20, quên cộng |V| ở mẫu. Số 2/15 là 4/30, quên cộng 1 ở tử."},{"id":"A-M-4-04","muc":4,"q":"Một bệnh có 10% dân số mắc. Xét nghiệm cho kết quả dương với 90% người bệnh và với 20% người không bệnh. Một người có kết quả dương. Xác suất người đó mắc bệnh bằng bao nhiêu?","options":["0,9","0,09","1/3","0,82"],"answer":[2],"multi":false,"why":"P(dương) = 0,1·0,9 + 0,9·0,2 = 0,09 + 0,18 = 0,27. P(bệnh | dương) = 0,09/0,27 = 1/3. Số 0,9 là độ nhạy P(dương | bệnh). Số 0,09 là tử số, chưa chia. Số 0,82 là 0,9/(0,9 + 0,2), bỏ qua tỉ lệ mắc bệnh."},{"id":"MB023","muc":5,"q":"Mô hình h(x) = σ(w0 + w1·x) đoán dương khi h(x) > 0,5. Với w0 = −1 và w1 = 1, những x nào được đoán dương?","options":["x > 0","x > 1","x > −1","x > 0,5"],"answer":[1],"multi":false,"why":"σ(z) > 0,5 khi z > 0, tức là −1 + x > 0, hay x > 1. Hệ số w0 dời ranh giới. Còn nếu tăng w1 mà giữ w0 = 0 thì ranh giới vẫn ở x = 0, chỉ có xác suất dốc hơn quanh ranh giới."},{"id":"MC021","muc":5,"q":"SVM lề cứng trên trục số: x = 3 (nhãn +1), x = 1 (nhãn +1), x = −1 (nhãn −1). Mô hình đoán theo dấu của wx + b. Nghiệm w, b là gì?","options":["w = 1, b = 1","w = 0, b = 1","w = 1, b = 0","w = 0,5, b = 0,5"],"answer":[2],"multi":false,"why":"Lề rộng nhất nằm giữa hai điểm gần nhau nhất khác nhãn, x = 1 và x = −1, nên ranh giới ở 0. Hai điểm đó nằm đúng trên lề: w + b = 1 và −(−w + b) = 1, cho w = 1, b = 0. Điểm x = 3 không phải vector hỗ trợ."},{"id":"H022","muc":5,"q":"Hồi quy logistic tính được z = w·x + b = ln 3. Xác suất dự đoán σ(z) bằng bao nhiêu?","options":["0,25","0,95","0,75","0,50"],"answer":[2],"multi":false,"why":"σ(z) = 1/(1 + e⁻ᶻ) = 1/(1 + 1/3) = 3/4. Có thể nhớ: e^z chính là tỉ số odds p/(1 − p) = 3, nên p = 3/4."},{"id":"E024","muc":5,"q":"SVM tuyến tính có w = (2, −1), b = −1. Điểm nào nằm trong lề hoặc bị phân loại sai, tức y·(w·x + b) < 1?","options":["(1, 0) với nhãn +1","(2, 1) với nhãn +1","(0, 1) với nhãn −1","(0, −1) với nhãn +1"],"answer":[3],"multi":false,"why":"y·f lần lượt: (1, 0): 1·1 = 1, nằm đúng trên lề; (2, 1): 2; (0, −1): 1·0 = 0 < 1; (0, 1): −1·(−2) = 2. Chỉ (0, −1) vi phạm. Những điểm có y·f ≤ 1 là các ứng viên vector hỗ trợ."},{"id":"MC016","muc":5,"q":"Bộ phân loại tuyến tính đoán theo dấu của w·x, với w = (4, 0, −3). Điểm x = (−1, 3, 2). Phải dịch x một đoạn ngắn nhất dài bao nhiêu để chạm ranh giới?","options":["10","5","0","2"],"answer":[3],"multi":false,"why":"Khoảng cách từ x đến mặt phẳng w·x = 0 là |w·x| / ‖w‖ = |−4 + 0 − 6| / 5 = 2, dịch theo hướng của w. Đây cũng là cỡ nhiễu nhỏ nhất làm mô hình đổi dự đoán, ý tưởng nền của ví dụ đối kháng."},{"id":"MB041","muc":5,"q":"Hồi quy logistic không có bias đã huấn luyện xong, đạt accuracy A trên tập test. Chia mọi trọng số cho 2 thì accuracy thay đổi thế nào?","options":["Không đổi, vẫn là A","Giảm còn khoảng A/2","Tăng lên vì mô hình bớt tự tin","Không đoán được nếu không chạy lại"],"answer":[0],"multi":false,"why":"Dự đoán là dương khi w·x > 0. Chia w cho 2 không làm đổi dấu của w·x, nên mọi nhãn dự đoán giữ nguyên. Chỉ xác suất là gần 0,5 hơn, tức mô hình bớt tự tin, còn accuracy thì như cũ."},{"id":"B-M-5-01","muc":5,"q":"Hồi quy logistic có một đặc trưng, ban đầu w = 0 và b = 0.\nMột mẫu huấn luyện có x = 2 và y = 1.\nHàm mất mát là log loss, gradient theo w bằng (p − y)·x với p = σ(wx + b).\nDùng learning rate 0,5, thực hiện một bước gradient descent cho w.\nGiá trị w mới bằng bao nhiêu?","options":["1","−0,5","0,5","0,25"],"answer":[2],"multi":false,"why":"Ban đầu z = 0 nên p = 0,5. Gradient theo w = (0,5 − 1)·2 = −1. Vậy w mới = 0 − 0,5·(−1) = 0,5. Chọn 1 là quên learning rate. Chọn −0,5 là sai dấu khi cập nhật. Chọn 0,25 là quên nhân với x, khi đó gradient là −0,5 và w = 0,25."},{"id":"B-M-5-02","muc":5,"q":"Một bạn dùng MSE thay cho log loss khi huấn luyện hồi quy logistic (đầu ra là sigmoid).\nChọn tất cả phát biểu đúng.","options":["Hàm mất mát theo w không còn lồi.","Gradient chứa thừa số σ'(z), nên rất nhỏ khi sigmoid bão hòa dù dự đoán sai.","Với log loss, gradient theo z cũng chứa thừa số σ'(z) nên cũng nhỏ khi sigmoid bão hòa.","MSE không tính được khi nhãn là 0 hoặc 1."],"answer":[0,1],"multi":true,"why":"MSE tính được với nhãn 0 hoặc 1, nhưng kết hợp với sigmoid thì hàm mất mát không lồi và gradient có thừa số σ'(z), rất nhỏ khi z lớn. Với log loss, σ'(z) bị triệt tiêu và gradient theo z chỉ còn p − y, nên không biến mất khi dự đoán sai."},{"id":"B-M-5-03","muc":5,"q":"Một SVM có w = (3, 4) và b = −5.\nBốn điểm: P1 = (2, 0), P2 = (0, 1), P3 = (1, 1), P4 = (3, 0).\nChọn tất cả điểm là support vector, tức nằm đúng trên biên với |wᵀx + b| = 1.","options":["P3","P4","P2","P1"],"answer":[2,3],"multi":true,"why":"Ta tính wᵀx + b. Với P1 là 6 − 5 = 1. Với P2 là 4 − 5 = −1. Với P3 là 3 + 4 − 5 = 2. Với P4 là 9 − 5 = 4. Chỉ P1 và P2 có giá trị tuyệt đối bằng 1. P3 và P4 nằm ngoài biên."},{"id":"B-M-5-04","muc":5,"q":"Một SVM có w = (1, −1) và b = 0. Ba điểm huấn luyện:\nx = (3, 1), y = +1\nx = (1, 2), y = +1\nx = (2, 0), y = −1\nTổng hinge loss max(0, 1 − y(wᵀx + b)) của ba điểm bằng bao nhiêu?","options":["5","2","13","4"],"answer":[0],"multi":false,"why":"Giá trị wᵀx + b của ba điểm lần lượt là 2, −1, 2. Nhân với y ta được 2, −1, −2. Hinge loss lần lượt là 0, 2, 3, tổng bằng 5. Chọn 2 là quên nhân y ở điểm thứ ba. Chọn 13 là bình phương các loss. Chọn 4 là quên max(0, ·) nên điểm đầu tiên cho −1."},{"id":"M019","muc":6,"q":"Tăng số cây của rừng ngẫu nhiên từ 100 lên 1000, nhưng accuracy validation vẫn đứng ở 87,3%. Vì sao thêm cây không giúp?","options":["Thêm cây chỉ giảm variance, mà nó đã gần hết","Thêm cây làm rừng quá khớp nặng hơn trước","Rừng ngẫu nhiên chỉ dùng tối đa được 100 cây","Các cây mới học lại y hệt những cây đã có"],"answer":[0],"multi":false,"why":"Gộp nhiều cây làm giảm phần dao động ngẫu nhiên (variance). Sau vài trăm cây, phần này gần như hết, nên thêm cây không cải thiện nữa. Thêm cây cũng không gây quá khớp. Muốn tốt hơn cần đổi đặc trưng hoặc độ sâu cây."},{"id":"E008","muc":6,"q":"Một nút có 10 mẫu chia theo ba lớp với số lượng 6, 2, 2. Chỉ số Gini của nút là bao nhiêu?","options":["0,44","1,37","0,60","0,56"],"answer":[3],"multi":false,"why":"Gini = 1 − Σp² = 1 − (0,36 + 0,04 + 0,04) = 0,56. Con số 0,44 là Σp², quên lấy 1 trừ đi. Con số 1,37 là entropy cơ số 2 của nút. Gini và entropy cùng đo độ không thuần khiết."},{"id":"E002","muc":6,"q":"Ba láng giềng gần nhất của điểm truy vấn: một điểm lớp A ở khoảng cách 1, hai điểm lớp B ở khoảng cách 2 và 3. Bỏ phiếu theo trọng số 1/khoảng cách thì dự đoán là lớp nào?","options":["Lớp B","Hòa, cần thêm láng giềng","Không xác định vì k lẻ","Lớp A"],"answer":[3],"multi":false,"why":"Phiếu của A là 1/1 = 1; của B là 1/2 + 1/3 ≈ 0,83. A thắng. Nếu bỏ phiếu đều thì B thắng 2–1; trọng số theo khoảng cách cho láng giềng rất gần tiếng nói lớn hơn."},{"id":"MB009","muc":6,"q":"Muốn từng cây trong rừng ngẫu nhiên chính xác hơn, bạn cho mọi cây xét tất cả đặc trưng ở mỗi lần chia, thay vì một tập con ngẫu nhiên. Lỗi của cả rừng trên dữ liệu mới thường thế nào?","options":["Tăng, vì các cây giống nhau nên gộp ít lợi","Giảm, vì từng cây đã chính xác hơn trước","Tăng, vì mỗi cây có ít dữ liệu hơn để học","Không đổi, vì số cây trong rừng vẫn vậy"],"answer":[0],"multi":false,"why":"Gộp nhiều cây chỉ có lợi khi các cây sai theo những cách khác nhau. Cho cây nào cũng xét đủ đặc trưng thì cây nào cũng chọn những phép chia giống nhau, nên lỗi của chúng đi cùng chiều và bỏ phiếu không còn bù trừ được."},{"id":"E010","muc":6,"q":"Ba bộ phân loại độc lập, mỗi bộ đúng 70% số mẫu. Gộp bằng bỏ phiếu đa số. Accuracy của tổ hợp xấp xỉ bao nhiêu?","options":["70%","Khoảng 97%","Khoảng 78%","Khoảng 34%"],"answer":[2],"multi":false,"why":"Đúng khi ít nhất 2 trong 3 đúng: 0,7³ + 3·0,7²·0,3 = 0,343 + 0,441 = 0,784. Con số 97% là “ít nhất một đúng”. Thực tế các mô hình không độc lập hẳn nên lợi ích nhỏ hơn; rừng ngẫu nhiên cố làm các cây khác nhau để gần với giả định này."},{"id":"H011","muc":6,"q":"Cây quyết định đạt 100% trên train nhưng kém trên validation. Những cách nào giúp giảm quá khớp? Chọn tất cả cách đúng.","options":["Giới hạn độ sâu tối đa của cây","Đặt số mẫu tối thiểu ở mỗi lá","Cắt tỉa (pruning) những nhánh ít giúp ích","Chia tiếp cho đến khi mỗi lá chỉ còn một lớp"],"answer":[0,1,2],"multi":true,"why":"Giới hạn độ sâu, đặt số mẫu tối thiểu ở lá và cắt tỉa đều kìm độ phức tạp của cây. Chia đến khi mỗi lá thuần khiết thì ngược lại: cây học thuộc cả nhiễu trong train."},{"id":"B-M-6-01","muc":6,"q":"Nút cha có 8 mẫu, gồm 4 mẫu dương và 4 mẫu âm.\nMột phép chia tạo hai nút con.\nNút trái có 2 mẫu, cả hai đều dương.\nNút phải có 6 mẫu, gồm 2 dương và 4 âm.\nĐộ giảm Gini (Gini gain) của phép chia bằng bao nhiêu? Làm tròn đến 3 chữ số thập phân.","options":["0,278","0,333","0,167","0,056"],"answer":[2],"multi":false,"why":"Gini của nút cha là 0,5. Gini nút trái là 0. Gini nút phải là 1 − (1/9 + 4/9) = 4/9. Gini có trọng số = (2/8)·0 + (6/8)·(4/9) = 1/3. Gini gain = 0,5 − 1/3 ≈ 0,167. Chọn 0,278 là lấy trung bình hai nút con mà bỏ trọng số. Chọn 0,333 là lấy Gini có trọng số làm gain. Chọn 0,056 là chỉ trừ Gini nút phải."},{"id":"B-M-6-02","muc":6,"q":"Điểm cần dự đoán là (0, 0).\nChỉ có hai điểm huấn luyện:\n(3, 3), lớp A\n(5, 0), lớp B\nVới k = 1, kNN dự đoán lớp nào nếu dùng khoảng cách Manhattan, và lớp nào nếu dùng khoảng cách Euclid?","options":["Manhattan: lớp B; Euclid: lớp A","Manhattan: lớp A; Euclid: lớp B","Cả hai đều lớp A","Cả hai đều lớp B"],"answer":[0],"multi":false,"why":"Manhattan: (3, 3) cách 3 + 3 = 6 và (5, 0) cách 5, nên gần nhất là lớp B. Euclid: (3, 3) cách √18 ≈ 4,24 và (5, 0) cách 5, nên gần nhất là lớp A. Cách đo khoảng cách có thể đổi kết quả dự đoán."},{"id":"B-M-6-03","muc":6,"q":"Chọn tất cả phát biểu đúng về random forest, AdaBoost, kNN và bagging.","options":["AdaBoost tăng trọng số của các mẫu bị phân loại sai ở vòng trước.","Bagging huấn luyện mọi cây trên đúng cùng một tập dữ liệu, không lấy mẫu lại.","Ở mỗi lần tách, random forest chỉ xét một tập con ngẫu nhiên các đặc trưng để giảm tương quan giữa các cây.","kNN với k = 1 có variance thấp và bias cao."],"answer":[0,2],"multi":true,"why":"Chọn ngẫu nhiên đặc trưng làm các cây ít giống nhau, nên trung bình của chúng giảm variance tốt hơn. AdaBoost tăng trọng số mẫu sai để vòng sau chú ý đến chúng. kNN với k = 1 thì ngược lại: bias thấp và variance cao. Bagging dùng mẫu bootstrap khác nhau cho mỗi cây."},{"id":"B-M-6-04","muc":6,"q":"Một nút có 6 mẫu, gồm 2 mẫu dương và 4 mẫu âm.\nCho log₂3 ≈ 1,585.\nEntropy của nút này (dùng log₂) bằng bao nhiêu? Làm tròn đến 3 chữ số thập phân.","options":["0,667","0,528","0,585","0,918"],"answer":[3],"multi":false,"why":"Với p = (1/3, 2/3), entropy = (1/3)·log₂3 + (2/3)·log₂(3/2) = log₂3 − 2/3 ≈ 1,585 − 0,667 = 0,918. Chọn 0,667 là lấy xác suất lớp âm. Chọn 0,528 là chỉ tính số hạng của lớp dương. Chọn 0,585 là lấy log₂3 − 1."},{"id":"MB013","muc":7,"q":"K-means++ chọn tâm đầu tiên là (0, 0). Các điểm còn lại là (1, 2), (2, 3), (3, 1), (4, 1). Mỗi điểm được chọn làm tâm thứ hai với xác suất tỉ lệ với bình phương khoảng cách đến tâm gần nhất. Điểm nào dễ được chọn nhất?","options":["(2, 3), xác suất khoảng 0,29","(4, 1), xác suất khoảng 0,25","(4, 1), xác suất khoảng 0,38","(3, 1), xác suất khoảng 0,22"],"answer":[2],"multi":false,"why":"Bình phương khoảng cách đến (0, 0) là 5, 13, 10 và 17, tổng 45. Điểm (4, 1) có xác suất 17 / 45 ≈ 0,38. K-means++ ưu tiên điểm ở xa các tâm đã có, nên các tâm ban đầu tản ra và ít rơi vào nghiệm tồi."},{"id":"MB012","muc":7,"q":"Một cụm của K-means gồm các điểm 1, 2, 3 và một điểm lạc 100 trên trục số. Tâm của cụm này nằm ở đâu?","options":["2","2,5","50,5","26,5"],"answer":[3],"multi":false,"why":"Tâm cụm là trung bình: (1 + 2 + 3 + 100) / 4 = 26,5, bị điểm lạc kéo đi rất xa. Vì dùng trung bình nên K-means nhạy với ngoại lai. Các biến thể như K-medoids chọn tâm là một điểm thật nên chịu ngoại lai tốt hơn."},{"id":"HB024","muc":7,"q":"Phân cụm gộp dần với single linkage (khoảng cách giữa hai cụm là khoảng cách giữa hai điểm gần nhau nhất). Đặc điểm nào đúng?","options":["Luôn ra các cụm tròn, kích thước đều","Cần biết trước số cụm như K-means","Không bị ảnh hưởng bởi thang đo","Dễ nối thành cụm dài dạng chuỗi"],"answer":[3],"multi":false,"why":"Chỉ cần một cặp điểm gần nhau là hai cụm được gộp, nên các điểm xếp nối tiếp tạo thành chuỗi dài. Điều này tốt với cụm hình dạng lạ, nhưng một dải điểm nhiễu cũng có thể nối hai cụm thật làm một."},{"id":"MC002","muc":7,"q":"Bốn điểm P1 = (2, 3, −1), P2 = (3, 1, 1), P3 = (5, −2, 3), P4 = (3, 3, 3). Phân cụm phân cấp kiểu gộp dần, dùng khoảng cách Manhattan. Hai điểm nào được gộp đầu tiên?","options":["P1 và P2","P2 và P3","P3 và P4","P2 và P4"],"answer":[3],"multi":false,"why":"Khoảng cách Manhattan là tổng trị tuyệt đối của chênh lệch từng tọa độ. P2–P4: 0 + 2 + 2 = 4, nhỏ nhất. P1–P2 và P1–P4 cùng bằng 5, P2–P3 và P3–P4 bằng 7, P1–P3 bằng 12. Phân cụm gộp dần luôn gộp cặp gần nhất trước."},{"id":"MC007","muc":7,"q":"Phép biến đổi nào trên bảng dữ liệu làm thay đổi các thành phần chính của PCA?","options":["Cộng cùng một hằng số vào mọi ô","Thêm một cột có giá trị như nhau ở mọi mẫu","Đổi thứ tự các mẫu trong bảng","Nhân một cột đặc trưng với một hằng số"],"answer":[3],"multi":false,"why":"PCA trừ trung bình trước, nên dời cả dữ liệu không đổi gì. Cột hằng số có phương sai 0 nên không thành thành phần chính. Nhưng phóng to một cột làm phương sai của nó tăng, kéo các thành phần chính về phía cột đó. Vì vậy người ta thường chuẩn hóa trước khi chạy PCA."},{"id":"MB028","muc":7,"q":"Muốn vẽ dữ liệu 50 chiều lên mặt phẳng để xem các cụm lân cận có tách nhau không. Phát biểu nào về UMAP là đúng?","options":["Giữ đúng mọi khoảng cách giữa các cặp điểm","Là một phép chiếu tuyến tính giống như PCA","Ưu tiên giữ quan hệ lân cận hơn khoảng cách xa","Buộc mọi cụm có kích thước bằng nhau trên hình"],"answer":[2],"multi":false,"why":"UMAP và t-SNE giữ được điểm nào gần điểm nào, nên hiện cụm rất rõ. Đổi lại, khoảng cách giữa các cụm xa nhau và kích thước cụm trên hình không đáng tin. PCA thì tuyến tính và giữ phương sai toàn cục."},{"id":"B-M-7-01","muc":7,"q":"Dữ liệu một chiều gồm năm điểm: 1, 3, 7, 9, 14.\nK-Means chạy với K = 2, hai tâm ban đầu là c₁ = 1 và c₂ = 9.\nSau một vòng (gán điểm rồi cập nhật tâm), hai tâm mới là gì?","options":["c₁ = 2; c₂ = 10","c₁ = 2; c₂ = 9","c₁ = 1; c₂ = 8,25","c₁ = 3; c₂ = 14"],"answer":[0],"multi":false,"why":"Gán điểm: 1 và 3 gần c₁ hơn, còn 7, 9 và 14 gần c₂ hơn. Tâm mới: c₁ = (1 + 3)/2 = 2 và c₂ = (7 + 9 + 14)/3 = 10. Chọn c₂ = 9 là không cập nhật tâm thứ hai. Chọn c₁ = 1 và c₂ = 8,25 là gán nhầm điểm 3 sang cụm 2."},{"id":"B-M-7-02","muc":7,"q":"Bốn điểm A, B, C, D có khoảng cách từng cặp như sau.\nd(A, B) = 2\nd(A, C) = 6\nd(A, D) = 10\nd(B, C) = 5\nd(B, D) = 9\nd(C, D) = 4\nPhân cụm phân cấp gộp dần cho đến khi còn một cụm.\nKhoảng cách ở lần gộp cuối cùng theo single linkage và theo complete linkage lần lượt là bao nhiêu?","options":["10 và 5","5 và 10","4 và 10","5 và 9"],"answer":[1],"multi":false,"why":"Cả hai cách đều gộp {A, B} ở mức 2 rồi {C, D} ở mức 4. Lần gộp cuối nối {A, B} với {C, D}. Single linkage lấy nhỏ nhất trong các khoảng cách 6, 10, 5, 9, tức 5. Complete linkage lấy lớn nhất, tức 10."},{"id":"B-M-7-03","muc":7,"q":"Ma trận hiệp phương sai của dữ liệu hai chiều là\n[3  1]\n[1  3]\nChỉ giữ thành phần chính thứ nhất (PC1).\nTỉ lệ phương sai giữ lại bằng bao nhiêu?","options":["50%","33,3%","200%","66,7%"],"answer":[3],"multi":false,"why":"Vết bằng 6 và định thức bằng 8, nên trị riêng thỏa λ² − 6λ + 8 = 0, tức λ = 4 và λ = 2. Tỉ lệ của PC1 là 4/6 ≈ 66,7%. Chọn 50% là lấy 3/6 từ đường chéo. Chọn 33,3% là tỉ lệ của PC2. Chọn 200% là chia 4 cho 2."},{"id":"B-M-7-04","muc":7,"q":"Chọn tất cả phát biểu đúng về PCA, K-Means và t-SNE.","options":["K-Means có thể rơi vào cực tiểu cục bộ, nên thường chạy nhiều lần với khởi tạo khác nhau.","Nên trừ trung bình của từng đặc trưng (căn giữa dữ liệu) trước khi làm PCA.","PC2 là hướng có phương sai lớn nhất.","Hai cụm xa nhau trong ảnh t-SNE chắc chắn cũng xa nhau trong không gian gốc."],"answer":[0,1],"multi":true,"why":"PCA dựa trên ma trận hiệp phương sai nên cần căn giữa dữ liệu. K-Means chỉ đảm bảo hội tụ về cực tiểu cục bộ. Hướng có phương sai lớn nhất là PC1, không phải PC2. Khoảng cách giữa các cụm trong ảnh t-SNE không có ý nghĩa định lượng."},{"id":"MB069","muc":8,"q":"Khối đặc trưng có kích thước 28 × 28 × 256. Đi qua lớp tích chập 1 × 1 với 64 bộ lọc thì được gì?","options":["28 × 28 × 64: giữ kích thước, giảm kênh","1 × 1 × 64: mất hết mọi thông tin vị trí","28 × 28 × 256: không đổi gì cả","14 × 14 × 64: thu nhỏ một nửa"],"answer":[0],"multi":false,"why":"Bộ lọc 1 × 1 trộn các kênh tại từng vị trí, không nhìn sang pixel lân cận. Nó hay được dùng để giảm số kênh trước một lớp tích chập lớn hơn, nhờ vậy tiết kiệm tính toán."},{"id":"MB056","muc":8,"q":"Ảnh 6 × 6, bộ lọc 3 × 3. Kích thước ra là ⌊(n + 2p − k) / s⌋ + 1. Muốn đầu ra 3 × 3, cặp stride và padding nhỏ nhất là gì?","options":["Stride 1, padding 0","Stride 2, padding 1","Stride 2, padding 0","Stride 3, padding 1"],"answer":[1],"multi":false,"why":"Stride 1, padding 0 cho 4 × 4. Stride 2, padding 0 cho ⌊3 / 2⌋ + 1 = 2. Stride 2, padding 1 cho ⌊5 / 2⌋ + 1 = 3. Lưu ý dấu làm tròn xuống: hàng và cột đệm cuối cùng không được bộ lọc phủ tới."},{"id":"HB026","muc":8,"q":"Hồi quy logistic có 300 đặc trưng đầu vào. Thêm một lớp ẩn 80 nơ-ron, đầu ra vẫn là một nơ-ron sigmoid. Mạng có bao nhiêu tham số?","options":["24 080","301","24 161","24 381"],"answer":[2],"multi":false,"why":"Trọng số: 300·80 + 80·1 = 24 080. Bias: 80 + 1 = 81. Tổng 24 161. 24 080 là quên bias, 301 là số tham số của hồi quy logistic ban đầu."},{"id":"M041","muc":8,"q":"Sau một lần cập nhật quá lớn, một nơ-ron ReLU cho ra 0 với mọi đầu vào. Vì sao nó khó tự hồi phục?","options":["Ở vùng âm, đạo hàm ReLU bằng 0","ReLU chỉ nhận đầu vào dương","Dropout đã tắt nơ-ron đó vĩnh viễn","Ở vùng âm, đạo hàm ReLU bằng 1"],"answer":[0],"multi":false,"why":"Gradient đi qua nơ-ron đó luôn bằng 0, nên trọng số của nó đứng yên mãi. Leaky ReLU cho vùng âm một độ dốc nhỏ, ví dụ 0,01x, để gradient vẫn đi qua được."},{"id":"M085","muc":8,"q":"Trong attention, điểm q·k được chia cho √d trước softmax. Bỏ phép chia này khi d lớn thì sao?","options":["Softmax chia đều cho mọi token","Softmax dồn gần hết vào một token","Không ảnh hưởng gì đến kết quả","Chạy nhanh hơn và chính xác hơn"],"answer":[1],"multi":false,"why":"Tích vô hướng của hai vector d chiều có độ lớn tăng theo √d. Điểm lớn làm softmax rất nhọn, các vị trí còn lại có gradient gần 0, nên mô hình học khó."},{"id":"MB036","muc":8,"q":"Mạng có một lớp ẩn và sigmoid ở đầu ra, nhưng quên đặt hàm kích hoạt ở lớp ẩn: ŷ = σ(W2(W1x + b1) + b2). Mạng này tương đương với mô hình nào?","options":["Mạng hai lớp đầy đủ, vì vẫn có hai ma trận","Hồi quy logistic, w = W2W1, b = W2b1 + b2","Hồi quy tuyến tính không có sigmoid","Không tương đương mô hình nào đơn giản hơn"],"answer":[1],"multi":false,"why":"Ghép hai phép biến đổi tuyến tính vẫn là một phép biến đổi tuyến tính: W2(W1x + b1) + b2 = (W2W1)x + (W2b1 + b2). Có sigmoid ở cuối thì đó đúng là hồi quy logistic. Lớp ẩn chỉ có ích khi có hàm kích hoạt phi tuyến."},{"id":"B-M-8-01","muc":8,"q":"Một mạng CNN nhỏ xử lý ảnh xám 28×28 (1 kênh).\nLớp 1: Conv2D, bộ lọc 3×3, 8 bộ lọc, padding 0, stride 1.\nLớp 2: MaxPooling 2×2, stride 2.\nLớp 3: Flatten.\nLớp 4: Dense với 10 nơ-ron.\nTổng số tham số học được của mạng (tính cả bias) bằng bao nhiêu?","options":["13600","13592","54170","13610"],"answer":[3],"multi":false,"why":"Conv: (3·3·1 + 1)·8 = 80, đầu ra 26×26×8. Pooling cho 13×13×8, không có tham số. Flatten ra 13·13·8 = 1352. Dense: (1352 + 1)·10 = 13530. Tổng = 80 + 13530 = 13610. Chọn 13600 là quên bias của Dense. Chọn 13592 là quên mọi bias. Chọn 54170 là quên bước pooling (26·26·8 = 5408 đầu vào cho Dense)."},{"id":"B-M-8-02","muc":8,"q":"Ảnh đầu vào có chiều rộng W = 32.\nLớp Conv2D dùng bộ lọc K = 3, padding P = 1 và stride S = 2.\nChiều rộng đầu ra bằng bao nhiêu?","options":["15","17","16","32"],"answer":[2],"multi":false,"why":"W_out = ⌊(32 − 3 + 2·1)/2⌋ + 1 = ⌊31/2⌋ + 1 = 15 + 1 = 16. Chọn 15 là quên +1. Chọn 17 là làm tròn lên 15,5 thành 16 rồi cộng 1. Chọn 32 là nhầm với stride 1."},{"id":"B-M-8-03","muc":8,"q":"Self-attention có một truy vấn q = (1, 2) và ba khóa.\nk₁ = (2, −1)\nk₂ = (−2, 1)\nk₃ = (4, −2)\nBa giá trị tương ứng:\nv₁ = (3, 0)\nv₂ = (0, 6)\nv₃ = (3, 3)\nChiều của khóa là d = 2.\nĐầu ra softmax(qKᵀ/√d)V bằng bao nhiêu?","options":["(6, 9)","(0, 0)","(3, 3)","(2, 3)"],"answer":[3],"multi":false,"why":"Các điểm số q·k lần lượt là 2 − 2 = 0, −2 + 2 = 0 và 4 − 4 = 0. Chia cho √2 vẫn bằng 0. Softmax của ba số 0 cho trọng số 1/3 mỗi giá trị. Đầu ra = trung bình của ba vector v = ((3 + 0 + 3)/3, (0 + 6 + 3)/3) = (2, 3). Chọn (6, 9) là cộng mà quên chia 3."},{"id":"B-M-8-04","muc":8,"q":"Chọn tất cả phát biểu đúng về BatchNorm, sigmoid và dropout.","options":["Dropout với p = 0,5 làm số tham số của mạng giảm đi một nửa.","Khi dự đoán, BatchNorm tính lại trung bình và phương sai từ chính mẫu đang dự đoán.","Khi huấn luyện, BatchNorm dùng trung bình và phương sai của mini-batch hiện tại.","Đạo hàm của sigmoid tối đa là 0,25, nên nhiều lớp sigmoid xếp chồng dễ làm gradient nhỏ dần."],"answer":[2,3],"multi":true,"why":"Khi huấn luyện, BatchNorm chuẩn hóa theo thống kê của mini-batch. Khi dự đoán, nó dùng trung bình và phương sai tích lũy lúc huấn luyện. Vì σ'(z) ≤ 0,25, tích của nhiều đạo hàm sẽ nhỏ dần (vanishing gradient). Dropout chỉ tắt tạm nơ-ron, không đổi số tham số."},{"id":"A-M-9-01","muc":9,"q":"An chưa xem phim X. Ba người dùng khác đã chấm phim X.\nBình có độ giống An là 0,5 và chấm 4.\nChi có độ giống 0,3 và chấm 2.\nDũng có độ giống −0,2 và chấm 5.\nDự đoán của An = Σ sim·r / Σ |sim|. Kết quả bằng bao nhiêu?","options":["1,6","2,67","3,25","3,67"],"answer":[0],"multi":false,"why":"Tử số: 0,5·4 + 0,3·2 + (−0,2)·5 = 2 + 0,6 − 1 = 1,6. Mẫu số: 0,5 + 0,3 + 0,2 = 1. Dự đoán là 1,6. Số 2,67 là do chia cho Σ sim = 0,6 thay vì Σ |sim|. Số 3,25 là bỏ Dũng ((2 + 0,6)/0,8). Số 3,67 là trung bình cộng ba điểm."},{"id":"A-M-9-02","muc":9,"q":"Hồ sơ người dùng theo ba thể loại (hành động, hài, tình cảm) là (2, 1, 2). Phim X có vector thể loại (1, 2, 2). Cosine giữa hồ sơ và phim X bằng bao nhiêu?","options":["8/3","8","8/9","4/3"],"answer":[2],"multi":false,"why":"Tích vô hướng: 2·1 + 1·2 + 2·2 = 8. Độ dài hồ sơ là √(4 + 1 + 4) = 3 và độ dài phim là √(1 + 4 + 4) = 3. Cosine = 8/(3·3) = 8/9. Số 8 là tích vô hướng. Số 8/3 là chia cho một độ dài. Số 4/3 là chia cho tổng hai độ dài (3 + 3 = 6) và vô lý vì cosine không vượt 1."},{"id":"A-M-9-03","muc":9,"q":"Một từ xuất hiện 2 lần trong tài liệu d. Kho có N = 16 tài liệu, trong đó 4 tài liệu chứa từ này. Em dùng TF là số lần xuất hiện và IDF = log₂(N/DF). TF-IDF của từ trong d bằng bao nhiêu?","options":["8","4","2","12"],"answer":[1],"multi":false,"why":"IDF = log₂(16/4) = log₂ 4 = 2, nên TF-IDF = 2·2 = 4. Số 8 là do quên log (2·16/4). Số 2 là chỉ IDF, quên nhân TF. Số 12 là do dùng N − DF = 12 thay cho log₂(N/DF)."},{"id":"A-M-9-04","muc":9,"q":"Về vấn đề người dùng mới và sản phẩm mới (cold-start). Chọn tất cả phát biểu đúng.","options":["Người dùng mới chưa chấm gì thì collaborative filtering thuần túy không có dữ liệu để so sánh.","Content-based cần điểm đánh giá của những người dùng khác.","Content-based gặp đúng khó khăn như collaborative filtering với phim mới.","Phim mới chưa ai chấm thì collaborative filtering không gợi ý được, còn content-based vẫn gợi ý được."],"answer":[0,3],"multi":true,"why":"Collaborative filtering cần điểm đánh giá, nên người dùng mới hay phim mới đều thiếu dữ liệu. Content-based chỉ cần đặc điểm của phim và hồ sơ người dùng, nên phim mới vẫn gợi ý được ngay."},{"id":"A-M-9-05","muc":9,"q":"Em dự đoán điểm của An cho phim T bằng item-based. An đã chấm phim X là 5 và phim Y là 3. Độ giống giữa T và X là 0,9, giữa T và Y là 0,3. Dự đoán = Σ sim·r / Σ |sim|. Kết quả bằng bao nhiêu?","options":["4,5","4","5,4","2,7"],"answer":[0],"multi":false,"why":"Tử số: 0,9·5 + 0,3·3 = 4,5 + 0,9 = 5,4. Mẫu số: 0,9 + 0,3 = 1,2. Dự đoán = 5,4/1,2 = 4,5. Số 4 là trung bình cộng không trọng số. Số 5,4 là quên chia. Số 2,7 là chia tử số cho số láng giềng (2) thay vì cho Σ |sim|."},{"id":"A-M-9-06","muc":9,"q":"Tác nhân nhận lần lượt các phần thưởng 1, 2, 4 và 8 ở bước 0, 1, 2 và 3. Hệ số chiết khấu γ = 0,5. Return G = Σ γᵗ·rₜ bằng bao nhiêu?","options":["15","8","7,5","4"],"answer":[3],"multi":false,"why":"G = 1 + 0,5·2 + 0,25·4 + 0,125·8 = 1 + 1 + 1 + 1 = 4. Số 15 là tổng không chiết khấu. Số 8 là do dùng γ không lũy thừa (1 + 0,5·(2 + 4 + 8)). Số 7,5 là tổng chia đôi."},{"id":"A-M-9-07","muc":9,"q":"Tác nhân có Q(s, a) = 1. Nó làm hành động a, nhận r = 2 và sang trạng thái s′ với max Q(s′, ·) = 5. Biết α = 0,5 và γ = 0,9. Q(s, a) mới bằng bao nhiêu?","options":["6,5","3,75","1,5","3,25"],"answer":[1],"multi":false,"why":"Mục tiêu = 2 + 0,9·5 = 6,5. Q mới = 1 + 0,5·(6,5 − 1) = 3,75. Số 6,5 là mục tiêu, chưa cập nhật. Số 1,5 là quên phần tương lai (1 + 0,5·(2 − 1)). Số 3,25 là 0,5·6,5, quên giữ lại phần (1 − α)·Q cũ."},{"id":"A-M-9-08","muc":9,"q":"Mỗi bước, tác nhân nhận phần thưởng 1 và chuỗi bước không bao giờ kết thúc. Hệ số chiết khấu γ = 0,5. Return G = Σ γᵗ·rₜ với t chạy từ 0 đến vô hạn bằng bao nhiêu?","options":["2","1","4","∞"],"answer":[0],"multi":false,"why":"G = 1 + 0,5 + 0,25 + … = 1/(1 − γ) = 1/0,5 = 2. Số 1 chỉ là phần thưởng đầu. Số 4 là 1/(1 − γ)², nhầm công thức. Số ∞ là khi không chiết khấu (γ = 1)."},{"id":"A-M-9-09","muc":9,"q":"Về công thức Q ← Q + α[r + γ·max Q(s′, ·) − Q]. Chọn tất cả phát biểu đúng.","options":["Với ε = 0, tác nhân vẫn khám phá hành động ngẫu nhiên.","Với γ = 0, Q chỉ phản ánh phần thưởng tức thời.","Với α = 1, Q mới bằng đúng giá trị mục tiêu r + γ·max Q(s′, ·).","Công thức lấy min thay vì max của Q(s′, ·)."],"answer":[1,2],"multi":true,"why":"Khi γ = 0, mục tiêu chỉ còn r. Khi α = 1, Q + 1·(mục tiêu − Q) = mục tiêu. ε = 0 nghĩa là không bao giờ chọn ngẫu nhiên. Công thức Q-learning dùng max, không phải min."},{"id":"A-M-9-10","muc":9,"q":"Tác nhân có hai lựa chọn. Lựa chọn thứ nhất cho 4 điểm ngay ở bước 0. Lựa chọn thứ hai cho 10 điểm ở bước 2 và không cho gì ở bước 0, 1. Hệ số chiết khấu γ = 0,5. Tác nhân nên chọn gì?","options":["Chờ, vì 10 > 4.","Chờ, vì 5 > 4.","Nhận ngay, vì 4 > 1,25.","Nhận ngay, vì 4 > 2,5."],"answer":[3],"multi":false,"why":"Phần thưởng 10 ở bước 2 có giá trị 0,5²·10 = 2,5, nhỏ hơn 4, nên nhận ngay. Chọn chờ vì 10 > 4 là quên chiết khấu. Số 5 là do chỉ nhân γ một lần. Số 1,25 là do dùng γ³."},{"id":"B-M-10-01","muc":10,"q":"Đồ thị có hướng có trọng số sau có đỉnh xuất phát là S, đích là G.\nS → A: 1\nS → B: 4\nA → B: 2\nA → C: 5\nB → C: 1\nB → D: 5\nC → G: 3\nD → G: 1\nUCS (uniform-cost search) luôn mở đỉnh có g nhỏ nhất. Khi hai đỉnh có g bằng nhau, UCS chọn đỉnh đứng trước theo bảng chữ cái.\nUCS mở các đỉnh theo thứ tự nào, cho đến khi mở G?","options":["S, A, B, C, D, G","S, B, D, G","S, A, B, C, G","S, B, A, C, G"],"answer":[2],"multi":false,"why":"g(A) = 1, g(B) = min(4, 1 + 2) = 3, g(C) = min(1 + 5, 3 + 1) = 4, g(D) = 3 + 5 = 8, g(G) = 4 + 3 = 7. Thứ tự g tăng dần là S (0), A (1), B (3), C (4), G (7), nên D (8) không được mở. Các phương án khác là thứ tự của BFS, DFS hoặc greedy."},{"id":"B-M-10-02","muc":10,"q":"Đồ thị có hướng có trọng số sau có đỉnh xuất phát là S, đích là G.\nS → A: 2\nS → B: 3\nA → G: 7\nB → C: 1\nC → G: 2\nBFS không quan tâm đến trọng số, chỉ tìm đường có ít cạnh nhất. Khi có nhiều cách, BFS xét đỉnh kề theo thứ tự bảng chữ cái.\nChi phí của đường đi mà BFS trả về và chi phí đường đi tối ưu lần lượt là bao nhiêu?","options":["6 và 6","9 và 6","9 và 9","6 và 9"],"answer":[1],"multi":false,"why":"BFS tìm thấy G sớm nhất qua S → A → G, đường có 2 cạnh và tốn 2 + 7 = 9. Đường S → B → C → G có 3 cạnh nhưng chỉ tốn 3 + 1 + 2 = 6, và đó là đường tối ưu mà UCS sẽ tìm ra."},{"id":"B-M-10-03","muc":10,"q":"Đồ thị có hướng có trọng số sau có đỉnh xuất phát là S, đích là G.\nS → A: 1\nS → B: 2\nS → C: 4\nA → D: 3\nB → D: 2\nB → E: 3\nC → E: 1\nD → G: 4\nE → G: 2\nGiá trị heuristic:\nh(S) = 6\nh(A) = 6\nh(B) = 4\nh(C) = 2\nh(D) = 3\nh(E) = 2\nh(G) = 0\nA* mở đỉnh có f = g + h nhỏ nhất. Khi hai đỉnh có f bằng nhau, A* chọn đỉnh đứng trước theo bảng chữ cái.\nA* mở các đỉnh theo thứ tự nào, cho đến khi mở G?","options":["S, A, B, C, D, E, G","S, C, E, G","S, C, B, A, D, E, G","S, B, C, A, D, E, G"],"answer":[3],"multi":false,"why":"Mở S: f(A) = 7, f(B) = 6, f(C) = 6. Mở B (6): f(D) = 4 + 3 = 7, f(E) = 5 + 2 = 7. Mở C (6, đứng trước các đỉnh f = 7). Rồi A, D, E đều có f = 7 và được mở theo bảng chữ cái; E đưa đến G với f = 7. Cuối cùng mở G. Các phương án khác là thứ tự của UCS, của greedy hoặc của BFS."},{"id":"B-M-10-04","muc":10,"q":"Đồ thị có hướng có trọng số sau có đích là G.\nS → A: 2\nS → B: 5\nA → G: 6\nB → G: 2\nChi phí thật nhỏ nhất đến G của mỗi đỉnh là h*(S) = 7, h*(A) = 6, h*(B) = 2. Ta luôn có h(G) = 0.\nChọn tất cả bộ heuristic admissible.","options":["h(S) = 6, h(A) = 6, h(B) = 2","h(S) = 7, h(A) = 6, h(B) = 3","h(S) = 8, h(A) = 6, h(B) = 2","h(S) = 5, h(A) = 3, h(B) = 2"],"answer":[0,3],"multi":true,"why":"Heuristic admissible khi h(v) ≤ h*(v) ở mọi đỉnh. Bộ h(S) = 6, h(A) = 6, h(B) = 2 và bộ h(S) = 5, h(A) = 3, h(B) = 2 đều thỏa. Bộ có h(S) = 8 vi phạm vì 8 > 7. Bộ có h(B) = 3 vi phạm vì 3 > 2."},{"id":"B-M-10-05","muc":10,"q":"Cây trò chơi có ba tầng. Gốc R là nút MAX, hai nút con A và B là nút MIN, và mỗi nút con của chúng là nút MAX.\nR (MAX): A, B\nA (MIN): A1, A2\nB (MIN): B1, B2\nA1 (MAX): 3, 7\nA2 (MAX): 5, 2\nB1 (MAX): 6, 1\nB2 (MAX): 4, 9\nGiá trị minimax của gốc R bằng bao nhiêu?","options":["5","7","6","9"],"answer":[2],"multi":false,"why":"Nút MAX ở tầng dưới: A1 = 7, A2 = 5, B1 = 6, B2 = 9. Nút MIN: A = min(7, 5) = 5, B = min(6, 9) = 6. Gốc MAX lấy max(5, 6) = 6. Chọn 7 hoặc 9 là lấy lá lớn nhất của một nhánh."},{"id":"B-M-10-06","muc":10,"q":"Cây trò chơi có ba tầng như sau. Alpha-beta duyệt các lá từ trái sang phải.\nR (MAX): A, B\nA (MIN): A1, A2\nB (MIN): B1, B2\nA1 (MAX): 5, 3\nA2 (MAX): 8, 4\nB1 (MAX): 4, 2\nB2 (MAX): 6, 7\nAlpha-beta duyệt bao nhiêu lá (tính cả các lá được duyệt nhưng không bị cắt)?","options":["5","8","6","4"],"answer":[0],"multi":false,"why":"A1 duyệt 5 và 3 (giá trị 5). Ở A2, β = 5, lá 8 ≥ 5 nên cắt, bỏ lá 4. A = 5, nên α = 5 ở gốc. B1 duyệt 4 và 2, được giá trị 4 ≤ α = 5, nên B không thể vượt 5 và B2 bị cắt cả hai lá. Số lá duyệt: 2 + 1 + 2 = 5."},{"id":"B-M-10-07","muc":10,"q":"Ba biến A, B, C đều có miền {1, 2, 3}.\nRàng buộc:\nA ≠ B\nA < C\nB < C\nTa gán A = 2. Forward checking cập nhật miền của các biến chưa gán.\nMiền của B và C sau bước này là gì?","options":["B ∈ {1}; C ∈ {3}","B ∈ {1, 3}; C ∈ {3}","B ∈ {1, 3}; C ∈ {1, 2, 3}","B ∈ {1, 2, 3}; C ∈ {3}"],"answer":[1],"multi":false,"why":"A = 2 làm B ≠ 2, nên B ∈ {1, 3}. A < C nên C > 2, tức C ∈ {3}. Forward checking chỉ lọc các biến có ràng buộc trực tiếp với biến vừa gán. Nó không dùng C ∈ {3} để loại tiếp B = 3 theo B < C. Việc đó cần AC-3."},{"id":"B-M-10-08","muc":10,"q":"Chọn tất cả suy diễn hợp lệ.","options":["Từ P → Q và P, suy ra Q.","Từ P → Q và Q, suy ra P.","Từ P → Q và ¬P, suy ra ¬Q.","Từ P → Q và ¬Q, suy ra ¬P."],"answer":[0,3],"multi":true,"why":"Từ P → Q và P suy ra Q là modus ponens. Từ P → Q và ¬Q suy ra ¬P là modus tollens. Cả hai luôn hợp lệ. Hai suy diễn còn lại là lỗi hay gặp. Khi P sai và Q đúng thì P → Q và Q đều đúng nhưng P sai, nên không suy ra được P. Cũng trường hợp đó, P → Q và ¬P đều đúng nhưng ¬Q sai."},{"id":"B-M-10-09","muc":10,"q":"Công ty muốn dự đoán nhân viên có nghỉ việc trong 6 tháng tới hay không. Trong dữ liệu, 4% nhân viên nghỉ việc.\nCột lương bị thiếu giá trị ở vài dòng và có vài mức lương rất lớn (ngoại lai).\nCó bốn cách làm. Cách nào đúng?","options":["Điền giá trị thiếu bằng mean tính trên toàn bộ dữ liệu trước khi chia. Dùng hồi quy logistic với log loss. Đánh giá bằng accuracy.","Chia train/test có phân tầng. Điền giá trị thiếu của cột lương bằng median tính trên train. Dùng hồi quy logistic với log loss. Đánh giá bằng PR-AUC và recall.","Chia train/test có phân tầng. Điền giá trị thiếu bằng median tính trên train. Dùng hồi quy tuyến tính với MSE. Đánh giá bằng accuracy.","Chia train/test có phân tầng. Điền giá trị thiếu bằng median tính trên tập test, để giá trị sát với dữ liệu cần dự đoán. Dùng hồi quy logistic với log loss. Đánh giá bằng PR-AUC."],"answer":[1],"multi":false,"why":"Nhãn nhị phân và lệch lớp (4%), nên dùng mô hình phân loại, log loss, và đánh giá bằng PR-AUC hoặc recall. Median chống chịu ngoại lai, và tham số của imputer chỉ được tính trên train. Cách điền mean trên toàn bộ dữ liệu sai vì bị data leakage và còn dùng accuracy. Cách dùng hồi quy tuyến tính với MSE sai vì đây là bài toán phân loại lệch lớp. Cách tính median trên tập test sai vì bị data leakage."},{"id":"B-M-10-10","muc":10,"q":"Một dịch vụ giao hàng muốn dự đoán thời gian giao hàng (đơn vị: phút).\nVài đơn bị trễ vài giờ do sự cố, nên dữ liệu có vài giá trị ngoại lai rất lớn.\nChọn tất cả lựa chọn hợp lý.","options":["Dùng Huber loss hoặc MAE làm hàm mất mát để giảm ảnh hưởng của ngoại lai.","Dùng sigmoid ở đầu ra và log loss, vì thời gian luôn là số dương.","Đánh giá bằng F1, vì F1 dùng được cho mọi bài toán.","Dùng hồi quy và đánh giá bằng MAE, vì MAE ít nhạy với ngoại lai hơn MSE."],"answer":[0,3],"multi":true,"why":"Thời gian giao hàng là một số thực, nên đây là hồi quy. MSE phạt ngoại lai rất nặng vì bình phương sai số, còn MAE và Huber loss ít nhạy hơn. Sigmoid với log loss và F1 dành cho bài toán phân loại."}]},{"id":"high","title":"High","minutes":180,"questions":[{"id":"MXC012","muc":1,"q":"Dự đoán khách hàng có rời bỏ dịch vụ trong tháng tới. Đặc trưng nào gây rò rỉ dữ liệu?","options":["Số tháng đã dùng dịch vụ","Số cuộc gọi hủy dịch vụ tháng tới","Số lần nạp tiền trong 3 tháng qua","Gói cước khách đang dùng"],"answer":[1],"multi":false,"why":"Đặc trưng này chỉ có sau khi sự kiện cần đoán đã xảy ra, nên lúc dùng thật không có. Mô hình sẽ đạt điểm rất cao khi đánh giá rồi thất bại khi triển khai."},{"id":"MXC011","muc":1,"q":"Gộp dữ liệu train (gắn nhãn 0) và dữ liệu thật mới (gắn nhãn 1), huấn luyện một bộ phân loại phân biệt hai nguồn. AUC trên tập kiểm định đạt 0,95. Kết luận gì?","options":["Hai nguồn dữ liệu giống nhau","Dữ liệu mới đã lệch khỏi dữ liệu train","Mô hình chính đang quá khớp","Nhãn của dữ liệu mới bị sai"],"answer":[1],"multi":false,"why":"Đây là adversarial validation. Nếu hai nguồn giống nhau, không bộ phân loại nào phân biệt được, AUC quanh 0,5. AUC 0,95 cho thấy có dịch chuyển phân phối; xem đặc trưng quan trọng của bộ phân loại để biết cột nào lệch."},{"id":"MB029","muc":1,"q":"Người thu nhập cao thường bỏ trống ô thu nhập. Ta điền ô trống bằng trung vị. Nên làm thêm gì để không mất thông tin?","options":["Xóa luôn cột thu nhập khỏi bảng","Điền thêm số 0 vào mọi ô trống","Thêm cột đánh dấu ô từng bị trống","Không cần làm gì thêm nữa"],"answer":[2],"multi":false,"why":"Ở đây việc bỏ trống tự nó đã mang thông tin: người bỏ trống thường giàu. Điền trung vị xóa mất tín hiệu đó. Cột đánh dấu “thiếu” (0 hoặc 1) giữ lại nó cho mô hình dùng."},{"id":"M021","muc":1,"q":"Bảng có 20 cột, 15% số ô bị trống, rải ngẫu nhiên. Nếu xóa mọi dòng có ít nhất một ô trống thì còn lại khoảng bao nhiêu phần trăm số dòng?","options":["Khoảng 85%","Khoảng 15%","Khoảng 4%","Không mất dòng nào"],"answer":[2],"multi":false,"why":"Mỗi ô có 85% khả năng không trống. Một dòng đủ cả 20 ô có xác suất 0,85²⁰ ≈ 0,04. Xóa dòng thiếu sẽ bỏ khoảng 96% dữ liệu, nên ở đây cần điền giá trị hoặc dùng mô hình chịu được ô trống."},{"id":"EB024","muc":1,"q":"Cột “giờ” có giá trị 0 đến 23. Dùng thẳng số giờ thì 23 giờ và 1 giờ cách nhau 22 đơn vị. Cách mã hóa nào làm hai giờ này gần nhau như 12 giờ và 14 giờ?","options":["giờ/24","One-hot 24 cột, mỗi giờ một cột riêng","log(giờ + 1)","(sin(2π·giờ/24), cos(2π·giờ/24))"],"answer":[3],"multi":false,"why":"Đặt mỗi giờ lên đường tròn thì 23 và 1 cách nhau đúng như 12 và 14, khoảng 0,52. Chia 24 chỉ đổi thang đo. One-hot làm mọi giờ cách đều nhau, mất luôn thông tin “gần nhau”."},{"id":"L033","muc":1,"q":"Bộ ảnh khuôn mặt có nhiều ảnh của cùng một người. Nếu ảnh của một người nằm ở cả train lẫn test thì sao?","options":["Điểm test thấp hơn thực tế","Điểm test cao hơn thực tế","Không ảnh hưởng gì, vì không có hai ảnh nào giống hệt","Mô hình sẽ không học được gì"],"answer":[1],"multi":false,"why":"Mô hình có thể nhận ra người đã gặp lúc học, chứ chưa chắc làm tốt với người lạ. Nên chia theo người: mỗi người chỉ nằm ở một tập."},{"id":"A-H-1-01","muc":1,"q":"Cột trên tập train gồm 10, 20, 30, 90 và một ô thiếu. Em điền ô thiếu bằng median của bốn giá trị có sẵn, rồi tính min và max trên cột đã điền để chuẩn hóa min-max. Một mẫu test cũng thiếu giá trị ở cột này. Em điền bằng median đó rồi chuẩn hóa. Giá trị sau chuẩn hóa của mẫu test bằng bao nhiêu?","options":["0,1875","0,34","0","0,28"],"answer":[0],"multi":false,"why":"Median của 10, 20, 30, 90 là (20 + 30)/2 = 25. Cột train đã điền có min = 10 và max = 90, nên giá trị là (25 − 10)/80 = 0,1875. Số 0,34 là khi điền bằng mean 37,5. Số 0 là khi điền ô thiếu bằng 0: min của cột thành 0 nên giá trị điền cũng thành 0. Số 0,28 là 25/90, quên trừ min."},{"id":"A-H-1-02","muc":1,"q":"Chọn tất cả quy trình gây rò rỉ dữ liệu (data leakage).","options":["Fit PCA trên cả train và test rồi mới chia.","Tính trung bình nhãn theo từng giá trị của một đặc trưng (target encoding) trên toàn bộ dữ liệu.","Fit scaler chỉ trên các fold dùng để huấn luyện trong mỗi lượt cross-validation.","Nhân bản mẫu lớp hiếm (oversampling) trước khi chia train và validation."],"answer":[0,1,3],"multi":true,"why":"PCA fit trên cả test dùng thông tin của test. Target encoding trên toàn bộ dữ liệu dùng nhãn của test. Nhân bản mẫu trước khi chia làm cùng một mẫu xuất hiện ở cả train và validation. Fit scaler riêng trong mỗi lượt cross-validation là cách làm đúng."},{"id":"A-H-1-03","muc":1,"q":"Tập train có hai đặc trưng. Độ lệch chuẩn của đặc trưng thứ nhất là 2 và của đặc trưng thứ hai là 10. Em dùng 1-NN để tìm điểm gần P = (1, 1000) nhất trong hai điểm Q = (2, 1010) và R = (5, 1000). Khoảng cách Euclid được tính hai lần: một lần trên số liệu gốc, một lần sau khi chia mỗi đặc trưng cho độ lệch chuẩn của nó. Điểm gần P nhất là điểm nào?","options":["Trước khi chuẩn hóa là Q, sau khi chuẩn hóa là R.","Cả hai lần đều là R.","Cả hai lần đều là Q.","Trước khi chuẩn hóa là R, sau khi chuẩn hóa là Q."],"answer":[3],"multi":false,"why":"Số liệu gốc: d(P, Q) = √(1 + 100) ≈ 10,05 và d(P, R) = 4, nên R gần hơn. Sau khi chia: P = (0,5; 100), Q = (1; 101), R = (2,5; 100). Khi đó d(P, Q) = √(0,25 + 1) ≈ 1,12 và d(P, R) = 2, nên Q gần hơn. Đặc trưng có số đo lớn đã lấn át khoảng cách trước khi chuẩn hóa."},{"id":"A-H-1-04","muc":1,"q":"Về việc chuẩn hóa đặc trưng. Chọn tất cả phát biểu đúng.","options":["Lasso (hồi quy với phạt L1) nên được chuẩn hóa đặc trưng, vì độ lớn trọng số phụ thuộc thang đo.","Gradient boosting trên cây không cần chuẩn hóa đặc trưng.","Biến đổi log lên một đặc trưng dương không làm đổi cách một cây quyết định chia.","K-Means không bị ảnh hưởng bởi thang đo của các đặc trưng."],"answer":[0,1,2],"multi":true,"why":"Phạt L1 tác động lên độ lớn trọng số, mà độ lớn này đổi theo thang đo của đặc trưng. Cây chỉ so sánh với ngưỡng nên chỉ phụ thuộc thứ tự các giá trị, và log giữ nguyên thứ tự. K-Means dùng khoảng cách nên nhạy với thang đo."},{"id":"E019","muc":2,"q":"Ba lớp có (dương đúng, dương sai, bỏ sót) lần lượt là A (50, 5, 5), B (30, 10, 10), C (1, 4, 4). Macro F1 và micro F1 xấp xỉ bao nhiêu?","options":["Macro 0,81; micro 0,62","Cả hai 0,81","Macro 0,62; micro 0,81","Macro 0,62; micro 0,62"],"answer":[2],"multi":false,"why":"F1 từng lớp: A ≈ 0,91; B = 0,75; C = 0,2; trung bình đều ≈ 0,62. Micro gộp số đếm: 81 dương đúng, 19 dương sai, 19 bỏ sót, F1 = 162/200 = 0,81. Lớp C hiếm kéo macro xuống, đó là lý do dùng macro khi lệch lớp."},{"id":"MXK004","muc":2,"q":"Trong 100 ca mô hình cho xác suất dương 0,9, thực tế chỉ 60 ca là dương. Điều này nói gì?","options":["Mô hình đã hiệu chỉnh tốt","Mô hình quá tự tin, cần hiệu chỉnh","Mô hình đang thiếu tự tin","Chỉ sửa được bằng thêm dữ liệu"],"answer":[1],"multi":false,"why":"Mô hình hiệu chỉnh tốt thì trong các ca nhận 0,9, khoảng 90% là dương. Ở đây chỉ 60%, nên xác suất bị phóng đại. Hiệu chỉnh chỉ đổi con số xác suất, không đổi thứ tự xếp hạng."},{"id":"UC010","muc":2,"q":"Thay mọi điểm số s bằng σ(3s − 1). AUC thay đổi thế nào?","options":["Không đổi","Tăng","Giảm","Không xác định được"],"answer":[0],"multi":false,"why":"AUC chỉ phụ thuộc thứ tự xếp hạng giữa mẫu dương và mẫu âm. σ(3s − 1) là hàm đồng biến ngặt nên giữ nguyên thứ tự. Accuracy ở ngưỡng cố định thì có thể đổi."},{"id":"EB006","muc":2,"q":"Nhà máy có 10% sản phẩm lỗi. Máy quét báo “lỗi” cho 90% sản phẩm lỗi và 5% sản phẩm tốt. Bỏ nhầm sản phẩm tốt mất 2 đô, để lọt sản phẩm lỗi mất 10 đô. Một sản phẩm bị báo lỗi, nên làm gì?","options":["Giữ lại, vì khả năng lỗi dưới 50%","Bỏ đi, vì khả năng lỗi là 2/3","Giữ lại, vì máy báo nhầm 5%","Bỏ đi, vì khả năng lỗi là 90%"],"answer":[1],"multi":false,"why":"P(lỗi | báo) = 0,09/(0,09 + 0,045) = 2/3. Bỏ đi thì kỳ vọng mất 2 × 1/3 ≈ 0,67 đô, giữ lại thì mất 10 × 2/3 ≈ 6,67 đô. 90% là P(báo | lỗi), không phải điều cần tính."},{"id":"HB022","muc":2,"q":"Mô hình phát hiện gian lận dự đoán “bình thường” cho mọi giao dịch. Precision của lớp gian lận bằng bao nhiêu?","options":["Bằng 1, vì không có báo nhầm nào","Bằng 0,5","Bằng tỉ lệ gian lận trong dữ liệu","Không xác định, vì 0/0"],"answer":[3],"multi":false,"why":"Precision = TP/(TP + FP), mà mô hình không báo dương lần nào nên tử và mẫu đều bằng 0. scikit-learn trả về 0 kèm cảnh báo. Recall thì xác định được và bằng 0, cho thấy mô hình vô dụng."},{"id":"MXC013","muc":2,"q":"Muốn vừa chọn siêu tham số vừa ước lượng không thiên lệch hiệu năng của cả quy trình chọn đó, khi dữ liệu ít. Cách nào đúng?","options":["Kiểm định chéo lồng nhau","Lấy điểm cao nhất trong các cấu hình đã thử của grid search","Chọn siêu tham số trên toàn bộ dữ liệu","Tăng số fold lên bằng số mẫu"],"answer":[0],"multi":false,"why":"Điểm cao nhất trong nhiều cấu hình đã thử được chọn ra chính vì nó cao, nên thiên lạc quan. Kiểm định chéo lồng nhau có vòng trong để chọn siêu tham số và vòng ngoài để đánh giá trên phần dữ liệu chưa tham gia việc chọn."},{"id":"A-H-2-01","muc":2,"q":"Một mô hình chạy trên 1000 mẫu, trong đó có 120 mẫu dương.\nTP = 60\nFN = 60\nFP = 20\nTN = 860\nChọn tất cả phát biểu đúng.","options":["Accuracy bằng 0,92.","Precision bằng 0,75.","Recall bằng 0,5.","F1 bằng 0,625."],"answer":[0,1,2],"multi":true,"why":"Accuracy = (60 + 860)/1000 = 0,92. Precision = 60/80 = 0,75. Recall = 60/120 = 0,5. F1 = 120/(120 + 20 + 60) = 0,6, không phải 0,625, vì 0,625 chỉ là trung bình cộng của precision và recall."},{"id":"A-H-2-02","muc":2,"q":"Mô hình cho điểm ba mẫu dương là 0,9; 0,6; 0,4 và ba mẫu âm là 0,7; 0,5; 0,2. ROC-AUC bằng xác suất một mẫu dương ngẫu nhiên có điểm cao hơn một mẫu âm ngẫu nhiên. Có 9 cặp dương–âm. ROC-AUC bằng bao nhiêu?","options":["5/9","7/9","2/3","1/2"],"answer":[2],"multi":false,"why":"Đếm cặp mà điểm dương cao hơn: mẫu 0,9 thắng cả 3 mẫu âm. Mẫu 0,6 thắng 0,5 và 0,2, được 2 cặp. Mẫu 0,4 thắng 0,2, được 1 cặp. Tổng 6 cặp trên 9, tức 2/3. Số 5/9 là đếm thiếu một cặp, 7/9 là đếm thừa một cặp, 1/2 là mức đoán ngẫu nhiên."},{"id":"A-H-2-03","muc":2,"q":"ROC-AUC của một mô hình phân loại nhị phân bằng 0,8. Điều đó có nghĩa gì?","options":["Mô hình dự đoán đúng 80% số mẫu.","Chọn ngẫu nhiên một mẫu dương và một mẫu âm, với xác suất 0,8 mô hình cho mẫu dương điểm cao hơn.","Tại ngưỡng 0,5, precision của mô hình bằng 0,8.","Tại mọi ngưỡng, TPR của mô hình bằng 0,8."],"answer":[1],"multi":false,"why":"ROC-AUC là xác suất mô hình xếp một mẫu dương ngẫu nhiên cao hơn một mẫu âm ngẫu nhiên, và nó không phụ thuộc ngưỡng. Accuracy và precision là những đại lượng khác, phụ thuộc vào ngưỡng được chọn."},{"id":"A-H-2-04","muc":2,"q":"Mô hình cho điểm tám mẫu như sau.\n0,9 nhãn dương\n0,8 nhãn âm\n0,7 nhãn dương\n0,6 nhãn dương\n0,5 nhãn âm\n0,4 nhãn dương\n0,3 nhãn âm\n0,1 nhãn âm\nEm hạ ngưỡng xuống 0,35, tức dự đoán dương khi điểm ≥ 0,35. F1 bằng bao nhiêu?","options":["0,67","0,8","0,83","0,75"],"answer":[1],"multi":false,"why":"Điểm ≥ 0,35 gồm 0,9; 0,8; 0,7; 0,6; 0,5; 0,4. Trong đó TP = 4 (0,9; 0,7; 0,6; 0,4), FP = 2 (0,8; 0,5), FN = 0. F1 = 8/(8 + 2 + 0) = 0,8. Số 0,67 là F1 ở ngưỡng 0,5 cũ. Số 0,83 là trung bình cộng của precision 2/3 và recall 1. Số 0,75 là recall ở ngưỡng cũ."},{"id":"MXC015","muc":3,"q":"Tăng bậc đa thức của mô hình hồi quy. Thành phần lỗi do bias và do variance thường thay đổi thế nào?","options":["Cả hai đều giảm","Bias tăng, variance giảm","Cả hai không đổi","Bias giảm, variance tăng"],"answer":[3],"multi":false,"why":"Mô hình linh hoạt hơn khớp được dạng phức tạp nên bias giảm. Nhưng nó cũng nhạy với từng mẫu train hơn nên variance tăng. Lỗi tổng thường có dạng chữ U theo độ phức tạp."},{"id":"UK001","muc":3,"q":"Tại một điểm x, nhiễu của dữ liệu có phương sai 0,1. Mô hình có bias 0,2 và phương sai dự đoán 0,05. Sai số bình phương kỳ vọng tại x bằng bao nhiêu?","options":["0,35","0,15","0,19","0,25"],"answer":[2],"multi":false,"why":"E[(y − f̂)²] = σ² + bias² + var = 0,1 + 0,04 + 0,05 = 0,19. Phương án 0,35 cộng bias mà quên bình phương. Phần σ² không giảm được bằng bất kỳ mô hình nào."},{"id":"EB013","muc":3,"q":"Dữ liệu thật có dạng chủ yếu bậc hai cộng nhiễu. Có 20 điểm train, khớp hồi quy đa thức bậc 1, 2, 8 và 10 (các bậc cao chứa mọi đặc trưng bậc thấp). Mô hình nào có lỗi train thấp nhất và lỗi test thấp nhất?","options":["Train: bậc 2; test: bậc 2","Train: bậc 10; test: bậc 10","Train: bậc 1; test: bậc 8","Train: bậc 10; test: bậc 2"],"answer":[3],"multi":false,"why":"Các mô hình lồng nhau nên bậc 10 luôn khớp train tốt nhất. Với 20 điểm, bậc 8 và 10 quá khớp nặng. Bậc 2 đúng với dạng thật nên khái quát hóa tốt nhất, còn bậc 1 chưa khớp."},{"id":"MC023","muc":3,"q":"Hồi quy tuyến tính có hệ số tự do, đo bằng MSE trên train. Việc nào không bao giờ làm lỗi train tăng?","options":["Dùng Lasso để trọng số thưa hơn","Thêm đặc trưng đa thức","Bỏ bớt đặc trưng để lỗi validation giảm","Tăng hệ số regularization"],"answer":[1],"multi":false,"why":"Có thêm đặc trưng, mô hình vẫn có thể đặt trọng số của nó bằng 0 để quay về nghiệm cũ, nên lỗi train chỉ giảm hoặc giữ nguyên. Ba việc kia thường cố ý chịu lỗi train cao hơn để đổi lấy lỗi validation thấp hơn."},{"id":"MC014","muc":3,"q":"Ridge regression không có hệ số tự do. Ba mẫu có y = 1,1; 1,9; 3,1. Khi λ rất lớn, MSE trên train tiến tới bao nhiêu?","options":["0","4,81","2,03","0,68"],"answer":[1],"multi":false,"why":"λ rất lớn đẩy θ về 0, nên mô hình luôn đoán 0. MSE = (1,1² + 1,9² + 3,1²) / 3 = 14,43 / 3 = 4,81. Nếu có hệ số tự do không bị phạt, mô hình sẽ đoán trung bình 2,03 và MSE chỉ còn khoảng 0,68."},{"id":"MXK002","muc":3,"q":"Với Lasso một đặc trưng đã chuẩn hóa, nghiệm là w = sign(ρ)·max(|ρ| − λ, 0), ρ là tương quan với nhãn. Với λ = 0,5, hai đặc trưng có ρ = 0,8 và ρ = 0,3 cho nghiệm nào?","options":["0,8 và 0,3","0,3 và −0,2","0,3 và 0","0,4 và 0,15"],"answer":[2],"multi":false,"why":"Đặc trưng đầu: 0,8 − 0,5 = 0,3. Đặc trưng sau: |0,3| < 0,5 nên bị cắt về đúng 0. Phép co rồi cắt này là lý do Lasso chọn đặc trưng. Phương án 0,4 và 0,15 là kiểu co theo tỉ lệ của Ridge."},{"id":"A-H-3-01","muc":3,"q":"Bốn mô hình có lỗi train và lỗi validation như sau.\nM1 có 15% và 16%.\nM2 có 2% và 14%.\nM3 có 6% và 7%.\nM4 có 0% và 30%.\nChọn tất cả phát biểu đúng.","options":["M1 bị underfit (bias cao).","M2 có khoảng cách train–validation lớn, dấu hiệu overfit.","M4 bị underfit vì lỗi train bằng 0.","M3 là mô hình tốt nhất trong bốn mô hình."],"answer":[0,1,3],"multi":true,"why":"M1 có lỗi cao ở cả hai tập nên bias cao. M2 và M4 có lỗi train thấp nhưng lỗi validation cao, tức overfit. M3 có lỗi validation thấp nhất (7%) nên là lựa chọn tốt nhất. Lỗi train bằng 0 là dấu hiệu overfit chứ không phải underfit."},{"id":"A-H-3-02","muc":3,"q":"Một mô hình có trọng số w = 4. Gradient của hàm lỗi dữ liệu theo w bằng 2. Em thêm hình phạt L2 là λ·w² với λ = 0,5. Learning rate η = 0,1. Sau một bước gradient descent trên tổng hàm lỗi, w bằng bao nhiêu?","options":["3,4","3,8","3,6","3,75"],"answer":[0],"multi":false,"why":"Gradient của hình phạt là 2λw = 2·0,5·4 = 4. Gradient tổng là 2 + 4 = 6. Vậy w = 4 − 0,1·6 = 3,4. Số 3,8 là quên hình phạt. Số 3,6 là dùng gradient phạt λw = 2 thiếu hệ số 2. Số 3,75 là dùng gradient của phạt L1 (λ = 0,5)."},{"id":"A-H-3-03","muc":3,"q":"Hai vector trọng số là a = (2, 0, 0, 0) và b = (1, 1, 1, 1). Hệ số λ = 1. Chọn tất cả phát biểu đúng.","options":["Hình phạt L1 khuyến khích mô hình dùng b hơn a.","Hình phạt L2 (tổng bình phương) của a và b bằng nhau.","Hình phạt L2 của a lớn hơn hình phạt L2 của b.","Hình phạt L1 của b lớn hơn hình phạt L1 của a."],"answer":[1,3],"multi":true,"why":"L2: a có 4 + 0 + 0 + 0 = 4 và b có 1 + 1 + 1 + 1 = 4, bằng nhau. L1: a có 2 còn b có 4, nên L1 phạt b nặng hơn và ưu tiên vector thưa a."},{"id":"A-H-3-04","muc":3,"q":"Một mô hình có variance 16. Em huấn luyện 8 mô hình như vậy, giả sử các mô hình độc lập với nhau và có cùng bias, rồi lấy trung bình dự đoán. Variance của dự đoán trung bình bằng bao nhiêu?","options":["16","4","2","128"],"answer":[2],"multi":false,"why":"Trung bình của n mô hình độc lập có variance giảm n lần: 16/8 = 2, còn bias giữ nguyên. Số 16 là khi tưởng lấy trung bình không giảm variance. Số 4 là độ lệch chuẩn √16 của một mô hình, không phải variance của trung bình. Số 128 là nhân thay vì chia."},{"id":"EB004","muc":4,"q":"10 email: 4 rác, 6 thường. Từ “offer” có trong 3 rác, 1 thường; “meeting” có trong 1 rác, 4 thường. Đặc trưng nhị phân, làm trơn Laplace α = 1. Email mới có “offer” nhưng không có “meeting”. Điểm chưa chuẩn hóa của lớp thường là bao nhiêu?","options":["0,15","Khoảng 0,056","Khoảng 0,094","Khoảng 0,178"],"answer":[1],"multi":false,"why":"P(offer | thường) = (1 + 1)/(6 + 2) = 0,25, P(meeting | thường) = (4 + 1)/8 = 0,625. Vì email không có “meeting”, phải nhân với 1 − 0,625. Điểm = 0,6 × 0,25 × 0,375 ≈ 0,056. Quên phần vắng mặt ra 0,15. Lớp rác được 0,178 nên thắng."},{"id":"MXK020","muc":4,"q":"Y ~ Bernoulli(1/2). Nếu Y = 1 thì X ~ Bernoulli(0,8), nếu Y = 0 thì X ~ Bernoulli(0,3). Bộ phân loại Bayes là gì và rủi ro của nó bằng bao nhiêu?","options":["Đoán Y = X, rủi ro 0,2","Đoán Y = X, rủi ro 0,25","Luôn đoán 1, rủi ro 0,5","Đoán Y = 1 − X, rủi ro 0,25"],"answer":[1],"multi":false,"why":"Khi X = 1: 0,8 > 0,3 nên đoán 1; khi X = 0: 0,2 < 0,7 nên đoán 0. Sai khi Y = 1 mà X = 0 (0,5·0,2) hoặc Y = 0 mà X = 1 (0,5·0,3), tổng 0,25."},{"id":"HB013","muc":4,"q":"Dữ liệu hai chiều đã trừ trung bình có ma trận hiệp phương sai [[4, 2], [2, 3]]. Thành phần chính thứ nhất giữ khoảng bao nhiêu phần phương sai?","options":["Khoảng 57%","Khoảng 64%","Khoảng 92%","Khoảng 79%"],"answer":[3],"multi":false,"why":"Vết bằng 7, định thức bằng 4·3 − 2·2 = 8. Trị riêng là (7 ± √17)/2, tức khoảng 5,56 và 1,44. Tỉ lệ 5,56/7 ≈ 0,79. Con số 57% là lấy 4/7, tức chỉ nhìn đường chéo."},{"id":"MXC007","muc":4,"q":"Thành phần chính ê là vector đơn vị cùng hướng với v = (1, −2, 3). Hình chiếu của x = (−1, −4, 6) lên ê bằng bao nhiêu?","options":["25/14","−11/√14","√14","25/√14"],"answer":[3],"multi":false,"why":"‖v‖ = √14, nên ê = v/√14. x·v = −1 + 8 + 18 = 25, hình chiếu = 25/√14. Con số 25/14 là hệ số của v khi viết hình chiếu dưới dạng vector, không phải độ dài theo ê."},{"id":"EB008","muc":4,"q":"P(mưa thứ Bảy) = 0,5, P(mưa Chủ nhật) = 0,3. Nếu thứ Bảy mưa thì khả năng Chủ nhật mưa gấp đôi so với khi thứ Bảy không mưa. Xác suất cả hai ngày đều không mưa là bao nhiêu?","options":["40%","35%","30%","45%"],"answer":[0],"multi":false,"why":"Gọi q = P(Chủ nhật mưa | thứ Bảy khô). 0,3 = 0,5 × 2q + 0,5 × q nên q = 0,2. P(cả hai khô) = 0,5 × (1 − 0,2) = 0,4. Coi hai ngày độc lập sẽ ra 0,5 × 0,7 = 35%."},{"id":"UK007","muc":4,"q":"Ma trận nào KHÔNG thể là ma trận hiệp phương sai?","options":["[[2, 1], [1, 2]]","[[1, 0], [0, 0]]","[[4, 2], [2, 1]]","[[1, 2], [2, 1]]"],"answer":[3],"multi":false,"why":"Hiệp phương sai phải đối xứng và nửa xác định dương. [[1, 2], [2, 1]] có trị riêng 3 và −1; trị riêng âm nghĩa là có tổ hợp tuyến tính với phương sai âm. [[4, 2], [2, 1]] có trị riêng 5 và 0, hợp lệ (hai biến phụ thuộc tuyến tính)."},{"id":"A-H-4-01","muc":4,"q":"Ma trận A có hàng thứ nhất là (1, 2) và hàng thứ hai là (2, −2). Tổng bình phương hai trị riêng của A bằng bao nhiêu?","options":["−11","1","7","13"],"answer":[3],"multi":false,"why":"Vết = 1 + (−2) = −1 và định thức = 1·(−2) − 2·2 = −6. Hai trị riêng thỏa λ² + λ − 6 = 0, tức 2 và −3, nên tổng bình phương là 4 + 9 = 13. Công thức: vết² − 2·định thức = 1 + 12. Số −11 là sai dấu (1 − 12). Số 1 chỉ là vết². Số 7 là vết² − định thức, quên hệ số 2."},{"id":"A-H-4-02","muc":4,"q":"Em tối thiểu hóa f(x, y) = x² + 3y². Điểm xuất phát là (2, 1) và learning rate η = 0,1. Sau 2 bước gradient descent, x và y bằng bao nhiêu?","options":["x = 1,28 và y = 0,16","x = 1,28 và y = 0,4","x = 1,6 và y = 0,4","x = 1,28 và y = 0,64"],"answer":[0],"multi":false,"why":"Gradient là (2x, 6y). Bước 1: (2, 1) → (2 − 0,4; 1 − 0,6) = (1,6; 0,4). Bước 2: gradient (3,2; 2,4) → (1,6 − 0,32; 0,4 − 0,24) = (1,28; 0,16). Phương án (1,6; 0,4) là sau một bước. Phương án y = 0,4 là quên cập nhật y ở bước 2. Phương án y = 0,64 là dùng đạo hàm 2y thay vì 6y."},{"id":"A-H-4-03","muc":4,"q":"Hai lớp spam và ham có xác suất tiên nghiệm bằng nhau (0,5). Từ điển có |V| = 10 từ.\nTrong lớp spam, tổng số từ là 20, từ “free” xuất hiện 4 lần và từ “meeting” xuất hiện 1 lần.\nTrong lớp ham, tổng số từ là 30, từ “free” xuất hiện 0 lần và từ “meeting” xuất hiện 9 lần.\nEm dùng Naive Bayes với làm trơn Laplace cho một thư có hai từ “free” và “meeting”. Xác suất thư là spam bằng bao nhiêu?","options":["1","0,69","0,64","0,36"],"answer":[2],"multi":false,"why":"Spam: (5/30)·(2/30) = 1/90. Ham: (1/40)·(10/40) = 1/160. Hai tiên nghiệm bằng nhau nên P(spam) = (1/90)/(1/90 + 1/160) = 160/250 = 0,64. Số 1 là khi không làm trơn (xác suất ham bằng 0). Số 0,69 là khi quên cộng |V| ở mẫu. Số 0,36 là xác suất ham."},{"id":"A-H-4-04","muc":4,"q":"Cho hai vector a = (2, 3, 6) và b = (3, 6, 2). Cosine của góc giữa a và b bằng bao nhiêu?","options":["36/7","36/49","36","6/7"],"answer":[1],"multi":false,"why":"Tích vô hướng: 6 + 18 + 12 = 36. Mỗi vector có độ dài √(4 + 9 + 36) = 7 hoặc √(9 + 36 + 4) = 7. Cosine = 36/(7·7) = 36/49. Số 36 là tích vô hướng. Số 36/7 là chia cho một độ dài. Số 6/7 là lấy căn của cosine."},{"id":"HB008","muc":5,"q":"SVM lề cứng có hai vector hỗ trợ x₁ = (1, 1) nhãn +1 và x₂ = (−1, −1) nhãn −1, cả hai có α = 1. Vector trọng số w bằng bao nhiêu?","options":["(0, 0)","(1, 1)","(2, −2)","(2, 2)"],"answer":[3],"multi":false,"why":"w = Σ αᵢyᵢxᵢ = 1·(+1)·(1, 1) + 1·(−1)·(−1, −1) = (2, 2). Chỉ các điểm có α > 0, tức vector hỗ trợ, góp vào w."},{"id":"UC004","muc":5,"q":"SVM kernel tuyến tính có hai vector hỗ trợ: x₁ = (1, 0), y₁ = +1, α₁ = 0,5 và x₂ = (−1, 0), y₂ = −1, α₂ = 0,5; b = 0. Giá trị f(x) = Σαᵢyᵢ(xᵢ·x) + b tại x = (0,4; 3) là bao nhiêu?","options":["0","3,4","0,4","−0,4"],"answer":[2],"multi":false,"why":"α₁y₁(x₁·x) = 0,5·0,4 = 0,2; α₂y₂(x₂·x) = 0,5·(−1)·(−0,4) = 0,2. Tổng 0,4. Tương đương w = Σαᵢyᵢxᵢ = (1, 0), nên tọa độ thứ hai của x không ảnh hưởng."},{"id":"MXC021","muc":5,"q":"SVM lề cứng cực tiểu ‖w‖² với ràng buộc yᵢ(w·xᵢ + b) ≥ 2 thay vì ≥ 1. Khoảng cách giữa hai siêu phẳng lề là bao nhiêu?","options":["4/‖w‖","2/‖w‖","1/‖w‖","8/‖w‖"],"answer":[0],"multi":false,"why":"Hai siêu phẳng lề là w·x + b = ±2, cách nhau 4/‖w‖. Nghiệm chỉ là nghiệm cũ nhân 2, ranh giới không đổi, nhưng công thức độ rộng lề phải theo đúng ràng buộc đã đặt."},{"id":"MXK012","muc":5,"q":"Dữ liệu đã tách được, SVM lề cứng cho nghiệm w*. Thêm một đặc trưng mới cho mọi điểm rồi huấn luyện lại. ‖w‖ tối ưu mới thế nào?","options":["Luôn lớn hơn, vì có thêm một chiều phải phạt","Luôn bằng như cũ","Bằng hoặc nhỏ hơn","Không xác định, có thể lớn hơn"],"answer":[2],"multi":false,"why":"Thêm số 0 vào cuối w* cho một nghiệm vẫn thỏa mọi ràng buộc với cùng chuẩn. Nghiệm tối ưu mới vì vậy không tệ hơn: lề không hẹp đi, có khi rộng ra nhờ đặc trưng mới."},{"id":"MC010","muc":5,"q":"Dữ liệu tách được tuyến tính. Có một điểm nằm rất xa, vẫn được phân loại đúng và ở ngoài lề của SVM. Bỏ điểm này rồi huấn luyện lại SVM, hồi quy logistic và 1-NN. Ranh giới của mô hình nào thay đổi ở vùng các điểm test?","options":["SVM lề cứng","Bộ phân loại 1-NN","Cả ba mô hình","Hồi quy logistic"],"answer":[3],"multi":false,"why":"SVM chỉ phụ thuộc các vector hỗ trợ, mà điểm này không phải vector hỗ trợ. 1-NN quyết định theo điểm gần nhất, mà điểm này ở rất xa vùng test. Loss của hồi quy logistic cộng trên mọi điểm, nên bỏ một điểm là ranh giới nhích đi một chút."},{"id":"UK003","muc":5,"q":"SVM lề cứng có w = (3, 4). Khoảng cách giữa hai siêu phẳng wᵀx + b = ±1 là bao nhiêu?","options":["0,2","0,4","5","2"],"answer":[1],"multi":false,"why":"Khoảng cách = 2/‖w‖ = 2/5 = 0,4. 0,2 là khoảng cách từ ranh giới tới một bên lề. Tối thiểu ‖w‖ chính là tối đa độ rộng lề."},{"id":"B-H-5-01","muc":5,"q":"Một SVM có w = (1, 1) và b = 0. Ta chạy một bước subgradient descent với learning rate 0,5 trên một mẫu duy nhất x = (2, 1), y = −1.\nHinge loss là max(0, 1 − y(wᵀx + b)). Khi y(wᵀx + b) < 1, subgradient theo w là −y·x và theo b là −y.\nSau một bước, w và b bằng bao nhiêu?","options":["w = (2; 1,5); b = 0,5","w = (0; 0,5); b = 0","w = (1; 1); b = 0","w = (0; 0,5); b = −0,5"],"answer":[3],"multi":false,"why":"Ta có wᵀx + b = 3 nên y(wᵀx + b) = −3 < 1, tức loss khác 0. Subgradient theo w là −y·x = (2, 1), theo b là −y = 1. Cập nhật: w = (1, 1) − 0,5·(2, 1) = (0; 0,5) và b = 0 − 0,5·1 = −0,5. Chọn w = (2; 1,5) là cộng thay vì trừ. Chọn b = 0 là quên cập nhật b. Chọn w = (1; 1), b = 0 là nghĩ rằng loss bằng 0 nên không đổi."},{"id":"B-H-5-02","muc":5,"q":"Chọn tất cả phát biểu đúng về SVM lề mềm (soft-margin).","options":["Giảm C làm lề rộng hơn và cho phép nhiều điểm vi phạm lề hơn.","Bỏ đi một điểm nằm ngoài lề (không phải support vector) thì siêu phẳng không đổi.","C càng lớn thì mô hình càng ít bị overfit.","Mọi điểm huấn luyện đều ảnh hưởng như nhau đến vị trí của siêu phẳng."],"answer":[0,1],"multi":true,"why":"C nhỏ ưu tiên lề rộng và chấp nhận nhiều vi phạm. C lớn phạt vi phạm nặng, nên dễ overfit hơn. Siêu phẳng chỉ phụ thuộc vào các support vector và các điểm vi phạm lề, nên bỏ một điểm nằm ngoài lề thì nghiệm không đổi."},{"id":"B-H-5-03","muc":5,"q":"Hồi quy logistic có w = 0 và b = 0. Tập huấn luyện có hai mẫu: (x = 1, y = 1) và (x = 3, y = 0).\nGradient của log loss là trung bình của (p − y)·x theo w và trung bình của (p − y) theo b.\nDùng learning rate 2, thực hiện một bước gradient descent.\nSau bước này, w và b bằng bao nhiêu?","options":["w = 1; b = 0","w = −2; b = 0","w = −1; b = 0","w = −0,5; b = 0"],"answer":[2],"multi":false,"why":"Khi w = 0, b = 0 thì p = 0,5 cho cả hai mẫu. Gradient theo w = ((0,5 − 1)·1 + (0,5 − 0)·3)/2 = (−0,5 + 1,5)/2 = 0,5. Gradient theo b = (−0,5 + 0,5)/2 = 0. Vậy w = 0 − 2·0,5 = −1 và b = 0. Chọn w = 1 là sai dấu. Chọn w = −2 là lấy tổng thay vì trung bình. Chọn w = −0,5 là quên learning rate."},{"id":"B-H-5-04","muc":5,"q":"Chọn tất cả phát biểu đúng về hồi quy logistic và hồi quy tuyến tính.","options":["Hồi quy tuyến tính huấn luyện bằng MSE luôn cho đầu ra nằm trong [0, 1].","Nhân đôi cả w và b thì biên quyết định (ngưỡng 0,5) đổi sang vị trí khác.","Với log loss, gradient theo z = wᵀx + b bằng p − y.","Với ngưỡng 0,5, biên quyết định của hồi quy logistic là siêu phẳng wᵀx + b = 0."],"answer":[2,3],"multi":true,"why":"σ(z) ≥ 0,5 khi và chỉ khi z ≥ 0, nên biên là wᵀx + b = 0. Với log loss, đạo hàm theo z chỉ còn p − y. Nhân đôi w và b chỉ làm sigmoid dốc hơn, còn tập điểm có z = 0 vẫn là siêu phẳng cũ. Hồi quy tuyến tính không bị chặn trong [0, 1]."},{"id":"MXC014","muc":6,"q":"Trong AdaBoost, bộ phân loại yếu có lỗi có trọng số ε = 0,25. Hệ số α = ½·ln((1 − ε)/ε) của nó xấp xỉ bằng bao nhiêu?","options":["1,10","0,25","0,55","0,75"],"answer":[2],"multi":false,"why":"α = ½·ln(0,75/0,25) = ½·ln 3 ≈ 0,549. Con số 1,10 là ln 3, quên nhân ½. Lỗi càng nhỏ thì α càng lớn, bộ phân loại càng có tiếng nói."},{"id":"MXC003","muc":6,"q":"Lấy mẫu bootstrap n lần có hoàn lại từ n mẫu, với n lớn. Tỉ lệ mẫu không được chọn lần nào (mẫu ngoài túi) xấp xỉ bao nhiêu?","options":["Khoảng 50%","Khoảng 36,8%","Khoảng 63,2%","0%"],"answer":[1],"multi":false,"why":"Xác suất một mẫu không được chọn là (1 − 1/n)ⁿ → 1/e ≈ 0,368. Rừng ngẫu nhiên dùng các mẫu này để ước lượng lỗi ngoài túi mà không cần tập kiểm định riêng."},{"id":"MXC004","muc":6,"q":"Mỗi cây có phương sai σ² = 1, hệ số tương quan giữa hai cây bất kỳ là ρ = 0,3. Phương sai của trung bình B cây là ρσ² + (1 − ρ)σ²/B. Khi B rất lớn, phương sai còn lại bao nhiêu?","options":["0","0,7","1","0,3"],"answer":[3],"multi":false,"why":"Số hạng thứ hai về 0 khi B lớn, còn lại ρσ² = 0,3. Thêm cây không xóa được phần tương quan; vì thế rừng ngẫu nhiên chọn ngẫu nhiên đặc trưng ở mỗi lần chia để giảm ρ."},{"id":"UK005","muc":6,"q":"Thêm cột “mã học sinh”, mỗi mẫu một giá trị khác nhau. Cây quyết định dùng độ lợi thông tin sẽ làm gì?","options":["Bỏ qua cột này vì nó không phải số","Chọn cột này vì độ lợi đạt tối đa","Chọn cột này nhưng độ lợi bằng 0","Báo lỗi vì cột có quá nhiều giá trị"],"answer":[1],"multi":false,"why":"Chia theo mã cho mỗi lá đúng một mẫu, entropy sau chia bằng 0, độ lợi bằng toàn bộ entropy gốc. C4.5 dùng tỉ số độ lợi (chia cho entropy của chính phép chia) để phạt các thuộc tính nhiều giá trị."},{"id":"UK009","muc":6,"q":"Độ quan trọng theo độ giảm tạp chất (impurity) của rừng ngẫu nhiên có thiên lệch gì?","options":["Đề cao đặc trưng có nhiều giá trị","Đề cao đặc trưng nhị phân","Không thiên lệch nếu đủ cây","Chỉ đúng với bài hồi quy"],"answer":[0],"multi":false,"why":"Đặc trưng nhiều giá trị có nhiều điểm chia để chọn, nên dễ tình cờ giảm tạp chất trên train. Độ quan trọng hoán vị, đo trên dữ liệu kiểm định, ít bị thiên lệch này hơn."},{"id":"E004","muc":6,"q":"kNN hồi quy với k = 3, trọng số 1/khoảng cách. Ba láng giềng có giá trị 10, 20, 40 ở khoảng cách 1, 2, 4. Dự đoán xấp xỉ bao nhiêu?","options":["Khoảng 23,3","Khoảng 17,1","20","Khoảng 14,3"],"answer":[1],"multi":false,"why":"Trọng số 1; 0,5; 0,25. Dự đoán = (10·1 + 20·0,5 + 40·0,25)/(1 + 0,5 + 0,25) = 30/1,75 ≈ 17,1. Trung bình thường là 23,3; trọng số kéo dự đoán về phía láng giềng gần nhất."},{"id":"B-H-6-01","muc":6,"q":"Nút cha có 12 mẫu, gồm 6 mẫu dương và 6 mẫu âm. Entropy của nút cha bằng 1. Cho log₂3 ≈ 1,585.\nPhép chia theo đặc trưng X tạo 3 nhánh, mỗi nhánh 4 mẫu:\nNhánh 1: 4 dương, 0 âm\nNhánh 2: 2 dương, 2 âm\nNhánh 3: 0 dương, 4 âm\nPhép chia theo đặc trưng Y tạo 2 nhánh, mỗi nhánh 6 mẫu:\nNhánh 1: 4 dương, 2 âm\nNhánh 2: 2 dương, 4 âm\nTheo information gain, nên chọn đặc trưng nào và information gain đó bằng bao nhiêu?","options":["Chọn Y; IG ≈ 0,082","Chọn X; IG ≈ 0,333","Chọn X; IG ≈ 0,667","Chọn Y; IG ≈ 0,918"],"answer":[2],"multi":false,"why":"Với X: hai nhánh thuần có entropy 0, nhánh giữa có entropy 1. Entropy có trọng số = (4/12)·1 = 1/3, nên IG = 1 − 1/3 ≈ 0,667. Với Y: mỗi nhánh có entropy log₂3 − 2/3 ≈ 0,918, nên IG ≈ 1 − 0,918 = 0,082. Chọn X. Chọn IG = 0,333 là lấy entropy có trọng số làm IG. Chọn 0,918 là lấy entropy của nhánh làm IG."},{"id":"B-H-6-02","muc":6,"q":"AdaBoost có 10 mẫu, ban đầu mỗi mẫu có trọng số 0,1. Một bộ phân loại yếu sai 2 mẫu, nên sai số có trọng số là ε = 0,2.\nHệ số của bộ phân loại là α = ½·ln((1 − ε)/ε).\nTrọng số được cập nhật: nhân với e^α cho mẫu bị sai, nhân với e^(−α) cho mẫu đúng. Sau đó chuẩn hóa để tổng bằng 1.\nSau khi chuẩn hóa, trọng số của mỗi mẫu bị phân loại sai bằng bao nhiêu?","options":["0,2","0,4","0,5","0,25"],"answer":[3],"multi":false,"why":"Ta có e^α = √((1 − ε)/ε) = √4 = 2. Mẫu sai: 0,1·2 = 0,2, hai mẫu cộng lại 0,4. Mẫu đúng: 0,1/2 = 0,05, tám mẫu cộng lại 0,4. Tổng bằng 0,8, chia cho 0,8 thì mỗi mẫu sai có trọng số 0,2/0,8 = 0,25. Chọn 0,5 là tổng trọng số của hai mẫu sai. Chọn 0,2 là quên bước chuẩn hóa."},{"id":"B-H-6-03","muc":6,"q":"Chọn tất cả phát biểu đúng về cây quyết định, random forest, bagging và boosting.","options":["Boosting với rất nhiều vòng thì không bao giờ overfit.","Tăng số cây trong random forest không làm tăng thêm overfit đáng kể.","Cây quyết định không cần chuẩn hóa đặc trưng.","Bagging chủ yếu giảm bias."],"answer":[1,2],"multi":true,"why":"Random forest lấy trung bình các cây, nên thêm cây chỉ làm variance giảm rồi bão hòa. Cây chia theo ngưỡng của từng đặc trưng nên không bị ảnh hưởng bởi thang đo. Bagging chủ yếu giảm variance, không phải bias. Boosting có thể overfit nếu chạy quá nhiều vòng, nhất là khi dữ liệu có nhiễu."},{"id":"B-H-6-04","muc":6,"q":"Hai đặc trưng là tuổi (min 20, max 60) và thu nhập (min 0, max 100, đơn vị triệu đồng).\nHai điểm huấn luyện: (tuổi 34, thu nhập 90), lớp A và (tuổi 50, thu nhập 52), lớp B.\nCần dự đoán điểm (tuổi 30, thu nhập 50) bằng 1-NN với khoảng cách Euclid.\nDự đoán sẽ là lớp nào trước khi chuẩn hóa, và lớp nào sau khi chuẩn hóa min-max cả hai đặc trưng về [0, 1]?","options":["Trước: lớp A; sau: lớp B","Trước: lớp A; sau: lớp A","Trước: lớp B; sau: lớp B","Trước: lớp B; sau: lớp A"],"answer":[3],"multi":false,"why":"Trước khi chuẩn hóa: bình phương khoảng cách tới A là 4² + 40² = 1616, tới B là 20² + 2² = 404, nên chọn B vì thu nhập lấn át. Sau min-max, điểm cần dự đoán là (0,25; 0,5), A là (0,35; 0,9), B là (0,75; 0,52). Bình phương khoảng cách tới A là 0,01 + 0,16 = 0,17, tới B là 0,25 + 0,0004 ≈ 0,25. Lúc này chọn A."},{"id":"EB007","muc":7,"q":"Ba điểm A = (0, 2), B = (0, 1), C = (1, 0), K = 2, tâm ban đầu đặt tại A và B. K-means dừng ở đâu, và cách chia đó có tối ưu không?","options":["Tâm (0; 1,5) và C; tối ưu","Tâm A và (0,5; 0,5); tối ưu","Tâm A và (0,5; 0,5); chưa tối ưu","Không hội tụ, dao động mãi"],"answer":[2],"multi":false,"why":"C gần B hơn A nên cụm 2 là {B, C}, tâm (0,5; 0,5); gán lại không đổi nên dừng, tổng bình phương khoảng cách 1. Chia {A, B} và {C} chỉ tốn 0,5. K-means luôn hội tụ nhưng có thể kẹt ở cực tiểu địa phương."},{"id":"MXK006","muc":7,"q":"Điều gì luôn đúng với thuật toán K-means (Lloyd)?","options":["Luôn tìm được nghiệm tối ưu toàn cục","Mục tiêu giảm ngặt mãi, không bao giờ dừng","Kết quả không phụ thuộc tâm ban đầu","Mục tiêu không tăng, dừng sau hữu hạn bước"],"answer":[3],"multi":false,"why":"Bước gán và bước cập nhật tâm đều không làm tăng hàm mục tiêu, và số cách gán điểm là hữu hạn, nên thuật toán dừng. Nhưng điểm dừng chỉ là cực tiểu cục bộ, tùy tâm ban đầu."},{"id":"UC005","muc":7,"q":"Ma trận dữ liệu đã trừ trung bình X (5 mẫu, 2 đặc trưng) có các giá trị suy biến 6 và 2. Thành phần chính thứ nhất giải thích bao nhiêu phần trăm phương sai?","options":["75%","60%","80%","90%"],"answer":[3],"multi":false,"why":"Phương sai theo mỗi thành phần tỉ lệ với bình phương giá trị suy biến (σᵢ²/(n − 1)). 36/(36 + 4) = 90%. Dùng thẳng giá trị suy biến cho 6/8 = 75%, sai."},{"id":"MXK015","muc":7,"q":"Dữ liệu đến dần, không lưu lại. Một cụm đang có tâm c = 2 và đã nhận n = 3 điểm. Điểm mới x = 6 được gán vào cụm này. Tâm mới là bao nhiêu?","options":["3","4","6","2,8"],"answer":[0],"multi":false,"why":"Chỉ cần lưu tâm và số điểm: c ← (n·c + x)/(n + 1) = (6 + 6)/4 = 3. Đây đúng là trung bình của mọi điểm đã gán, nên bộ nhớ không phụ thuộc độ dài luồng."},{"id":"H014","muc":7,"q":"Điểm p thuộc cụm C₁. Khoảng cách trung bình từ p tới các điểm khác trong C₁ là 0,4; tới cụm C₂ là 0,9; tới cụm C₃ là 0,6. Hệ số silhouette s(p) = (b − a)/max(a, b) bằng bao nhiêu?","options":["Khoảng 0,33","Khoảng 0,56","0,50","Khoảng −0,33"],"answer":[0],"multi":false,"why":"a = 0,4; b là khoảng cách tới cụm gần nhất khác C₁, tức min(0,9; 0,6) = 0,6. s = (0,6 − 0,4)/0,6 ≈ 0,33. Phương án 0,56 lấy nhầm cụm xa nhất, còn 0,50 chia cho a thay vì max(a, b)."},{"id":"MXC008","muc":7,"q":"Ma trận có các giá trị suy biến 5, 3, 1. Xấp xỉ hạng 1 tốt nhất theo chuẩn Frobenius có sai số bình phương tương đối ‖A − A₁‖²_F/‖A‖²_F bằng bao nhiêu?","options":["Khoảng 0,44","0,20","Khoảng 0,29","Khoảng 0,71"],"answer":[2],"multi":false,"why":"Theo Eckart–Young, giữ giá trị suy biến lớn nhất; sai số là tổng bình phương các giá trị bị bỏ: (9 + 1)/(25 + 9 + 1) = 10/35 ≈ 0,29. Con số 0,44 dùng giá trị suy biến thay vì bình phương: 4/9."},{"id":"B-H-7-01","muc":7,"q":"Năm điểm hai chiều: (0, 0), (0, 2), (4, 0), (4, 2), (10, 1).\nK-Means chạy với K = 2, hai tâm ban đầu là c₁ = (0, 0) và c₂ = (4, 0). Dùng khoảng cách Euclid.\nSau một vòng (gán điểm rồi cập nhật tâm), SSE là tổng bình phương khoảng cách từ mỗi điểm đến tâm mới của cụm đó.\nSSE bằng bao nhiêu?","options":["45","40","26","28"],"answer":[3],"multi":false,"why":"Gán điểm: (0, 0) và (0, 2) về c₁. (4, 0), (4, 2) và (10, 1) về c₂. Tâm mới: c₁ = (0, 1) và c₂ = (6, 1). SSE cụm 1 = 1 + 1 = 2. SSE cụm 2 = (4 + 1) + (4 + 1) + 16 = 26. Tổng = 28. Chọn 45 là tính SSE theo tâm cũ. Chọn 26 là quên cụm 1. Chọn 40 là cho c₂ = (4; 1), tức bỏ điểm (10, 1) khi tính trung bình."},{"id":"B-H-7-02","muc":7,"q":"Năm điểm một chiều: 1, 2, 6, 8, 15. Phân cụm phân cấp gộp dần hai cụm gần nhau nhất, với khoảng cách giữa hai điểm là hiệu tuyệt đối của chúng.\nTa cắt dendrogram ở độ cao 5, tức chỉ giữ các lần gộp có khoảng cách ≤ 5.\nSingle linkage và complete linkage lần lượt cho bao nhiêu cụm?","options":["3 và 2","2 và 2","3 và 3","2 và 3"],"answer":[3],"multi":false,"why":"Single linkage gộp ở các mức 1 ({1, 2}), 2 ({6, 8}), 4 (nối hai cụm đó, vì 6 − 2 = 4) và 7 (thêm điểm 15). Có 3 lần gộp ≤ 5, còn 5 − 3 = 2 cụm. Complete linkage gộp ở mức 1, 2, 7 (vì 8 − 1 = 7) và 14. Chỉ có 2 lần gộp ≤ 5, còn 5 − 2 = 3 cụm."},{"id":"B-H-7-03","muc":7,"q":"Ma trận hiệp phương sai của dữ liệu hai chiều là\n[5  2]\n[2  2]\nHướng của thành phần chính thứ nhất (PC1) và tỉ lệ phương sai mà PC1 giữ lại là bao nhiêu?","options":["Hướng (1, 2); 85,7%","Hướng (2, 1); 85,7%","Hướng (2, 1); 71,4%","Hướng (1, 2); 71,4%"],"answer":[1],"multi":false,"why":"Vết bằng 7, định thức bằng 5·2 − 2·2 = 6, nên λ² − 7λ + 6 = 0, tức λ = 6 và λ = 1. Với λ = 6: (5 − 6)x + 2y = 0, nên y = x/2 và hướng là (2, 1). Tỉ lệ phương sai = 6/7 ≈ 85,7%. Chọn 71,4% là lấy 5/7 từ phần tử đường chéo. Chọn hướng (1, 2) là đổi chỗ x và y."},{"id":"B-H-7-04","muc":7,"q":"Chọn tất cả phát biểu đúng về PCA, phân cụm phân cấp, K-Means và t-SNE.","options":["t-SNE là một phép biến đổi tuyến tính.","Single linkage dễ gây hiệu ứng chuỗi (chaining), nối các cụm dài thành một.","Hai thành phần chính ứng với hai trị riêng khác nhau của ma trận hiệp phương sai thì vuông góc với nhau.","K-Means luôn cho cùng một kết quả với mọi cách khởi tạo tâm."],"answer":[1,2],"multi":true,"why":"Ma trận hiệp phương sai đối xứng nên các vector riêng ứng với các trị riêng khác nhau vuông góc nhau. Single linkage chỉ cần một cặp điểm gần nhau để nối hai cụm, nên dễ tạo chuỗi. K-Means phụ thuộc vào khởi tạo và có thể ra kết quả khác nhau. t-SNE là phép biến đổi phi tuyến."},{"id":"HB057","muc":8,"q":"Ảnh 13 × 13 qua tích chập 3 bộ lọc 4 × 4 stride 1, rồi max pooling 2 × 2 stride 2, rồi ReLU, rồi lớp kết nối đầy đủ ra 4 số. Không có bias. Mạng có bao nhiêu trọng số, và ReLU tính trên bao nhiêu giá trị?","options":["1 248 trọng số, 300 giá trị","348 trọng số, 75 giá trị","348 trọng số, 300 giá trị","300 trọng số, 75 giá trị"],"answer":[1],"multi":false,"why":"Tích chập: 3·16 = 48, cho ra 3 @ 10 × 10. Pooling còn 3 @ 5 × 5 = 75 giá trị, ReLU áp lên 75 giá trị đó. Lớp cuối: 75·4 = 300. Tổng 348. Pooling và ReLU không có trọng số."},{"id":"EB051","muc":8,"q":"Trong LeNet, lớp C3 nhận 6 bản đồ đặc trưng và tạo 16 bản đồ bằng các bộ lọc 5 × 5, mỗi bộ lọc có một bias, nối với đủ 6 kênh vào. C3 có bao nhiêu tham số?","options":["416","2 400","1 216","2 416"],"answer":[3],"multi":false,"why":"Mỗi bộ lọc có 5·5·6 = 150 trọng số cộng 1 bias, 16 bộ lọc: 16·151 = 2 416. Quên rằng bộ lọc phủ cả 6 kênh ra 416. (LeNet gốc chỉ nối một phần kênh, ở đây giả sử nối đủ như đề.)"},{"id":"UC028","muc":8,"q":"Mạng có một lớp ẩn dùng hàm ngưỡng, cần ít nhất bao nhiêu nơ-ron ẩn để biểu diễn XOR của hai đầu vào nhị phân?","options":["1","3","4","2"],"answer":[3],"multi":false,"why":"XOR không tách được tuyến tính nên một nơ-ron không đủ. Hai nơ-ron đủ: một tính OR, một tính AND, đầu ra là OR và không AND."},{"id":"E085","muc":8,"q":"Một truy vấn có điểm q·k với hai token lần lượt là 2 và 0 (không chia √d). Value của hai token là 1 và 3. Đầu ra attention xấp xỉ bằng bao nhiêu?","options":["2,00","1,12","0,88","1,24"],"answer":[3],"multi":false,"why":"Softmax(2, 0) ≈ (0,881; 0,119). Đầu ra = 0,881·1 + 0,119·3 ≈ 1,24. Con số 2,00 là trung bình đều; 0,88 chỉ lấy trọng số của token đầu. Attention giúp tập trung vào phần quan trọng bằng chính các trọng số này."},{"id":"UC026","muc":8,"q":"Mạng ŷ = w₂·ReLU(w₁·x) với x = 1, w₁ = 2, w₂ = −1. Loss L = (ŷ − y)², y = 0. ∂L/∂w₂ và ∂L/∂w₁ bằng bao nhiêu?","options":["∂L/∂w₂ = 8, ∂L/∂w₁ = −4","∂L/∂w₂ = −8, ∂L/∂w₁ = 4","∂L/∂w₂ = −4, ∂L/∂w₁ = 2","∂L/∂w₂ = −8, ∂L/∂w₁ = 0"],"answer":[1],"multi":false,"why":"h = ReLU(2) = 2, ŷ = −2, ∂L/∂ŷ = 2(ŷ − y) = −4. ∂L/∂w₂ = −4·h = −8. ∂L/∂w₁ = −4·w₂·ReLU′(2)·x = −4·(−1)·1·1 = 4."},{"id":"UC027","muc":8,"q":"f(x) = ReLU(x) − ReLU(x − 1). Giá trị f(2,5) là bao nhiêu, và f là hàm gì?","options":["2,5; hàm đồng nhất","1,5; ReLU dịch phải","1; hàm kẹp x vào [0, 1]","0; hàm bậc thang"],"answer":[2],"multi":false,"why":"f(2,5) = 2,5 − 1,5 = 1. Với x ≤ 0 cả hai số hạng bằng 0; với 0 < x < 1 được x; với x ≥ 1 được 1. Mạng ReLU luôn biểu diễn hàm tuyến tính từng khúc."},{"id":"B-H-8-01","muc":8,"q":"Một mạng CNN nhận ảnh màu 32×32×3.\nLớp 1: Conv2D, bộ lọc 3×3, 16 bộ lọc, padding 1, stride 1.\nLớp 2: MaxPooling 2×2, stride 2.\nLớp 3: Conv2D, bộ lọc 3×3, 32 bộ lọc, padding 0, stride 1.\nLớp 4: GlobalAveragePooling (lấy trung bình mỗi kênh thành một số).\nLớp 5: Dense với 10 nơ-ron.\nTổng số tham số học được (tính cả bias) bằng bao nhiêu?","options":["5418","5360","67818","1674"],"answer":[0],"multi":false,"why":"Lớp 1: (3·3·3 + 1)·16 = 448, đầu ra 32×32×16. Pooling cho 16×16×16. Lớp 3: (3·3·16 + 1)·32 = 4640, đầu ra 14×14×32. Global average pooling cho 32 số. Dense: (32 + 1)·10 = 330. Tổng = 448 + 4640 + 330 = 5418. Chọn 5360 là quên bias. Chọn 67818 là dùng Flatten (6272 đầu vào) thay vì global average pooling. Chọn 1674 là dùng C_in = 3 cho lớp Conv thứ hai."},{"id":"B-H-8-02","muc":8,"q":"Một chiều của ảnh có độ dài W = 15.\nLớp Conv thứ nhất dùng K = 3, P = 1, S = 2. Lớp Conv thứ hai nhận đầu ra của lớp thứ nhất và dùng K = 3, P = 0, S = 2.\nĐộ dài đầu ra sau lớp thứ hai bằng bao nhiêu?","options":["3","2","4","8"],"answer":[0],"multi":false,"why":"Lớp 1: ⌊(15 − 3 + 2)/2⌋ + 1 = 7 + 1 = 8. Lớp 2: ⌊(8 − 3 + 0)/2⌋ + 1 = 2 + 1 = 3. Chọn 2 là quên +1 ở lớp 2. Chọn 4 là làm tròn lên 2,5 thành 3 rồi cộng 1. Chọn 8 là kết quả sau lớp 1."},{"id":"B-H-8-03","muc":8,"q":"Chọn tất cả phát biểu đúng về self-attention softmax(QKᵀ/√d)V.","options":["Chia cho √d giúp điểm số không tăng theo chiều d, tránh softmax bị bão hòa.","Mỗi cột của ma trận trọng số attention có tổng bằng 1.","Với n token, ma trận điểm QKᵀ có kích thước n × n.","Ma trận trọng số attention là tham số học được, có giá trị cố định cho mọi câu."],"answer":[0,2],"multi":true,"why":"Khi d lớn, tích vô hướng có thể rất lớn nên softmax gần như chỉ chọn một vị trí và gradient nhỏ. Chia cho √d giữ độ lớn ổn định. Ma trận QKᵀ có một điểm số cho mỗi cặp token, nên là n × n. Softmax chạy theo hàng nên tổng mỗi hàng bằng 1, không phải mỗi cột. Trọng số attention được tính lại từ Q và K cho từng câu."},{"id":"B-H-8-04","muc":8,"q":"Một lớp BatchNorm nhận mini-batch gồm 4 giá trị của một nơ-ron: 2, 2, 6, 6. Bỏ qua ε.\nLớp tính x̂ = (x − trung bình)/độ lệch chuẩn, rồi đầu ra y = γ·x̂ + β với γ = 2 và β = 1.\nBốn giá trị đầu ra y lần lượt là bao nhiêu?","options":["−2, −2, 2, 2","0, 0, 2, 2","−1, −1, 3, 3","−1, −1, 1, 1"],"answer":[2],"multi":false,"why":"Trung bình bằng 4, phương sai bằng 4, độ lệch chuẩn bằng 2. Do đó x̂ = (−1, −1, 1, 1). Đầu ra y = 2·x̂ + 1 = (−1, −1, 3, 3). Chọn −2, −2, 2, 2 là quên β. Chọn 0, 0, 2, 2 là chia cho phương sai 4 thay vì độ lệch chuẩn 2. Chọn −1, −1, 1, 1 là quên γ và β."},{"id":"A-H-9-01","muc":9,"q":"An và Bình cùng chấm bốn phim. An chấm 4, 2, 2, 0. Bình chấm 1, 3, 2, 2. Hệ số Pearson là cosine của hai vector sau khi trừ điểm trung bình của từng người. Pearson giữa An và Bình bằng bao nhiêu?","options":["0,67","0,5","−0,25","−0,5"],"answer":[3],"multi":false,"why":"Trung bình của An là 2 và của Bình là 2. Sau khi trừ: An = (2, 0, 0, −2) và Bình = (−1, 1, 0, 0). Tích vô hướng là −2. Độ dài là √8 và √2, tích bằng 4. Pearson = −2/4 = −0,5. Số 0,67 là cosine trên điểm gốc (14/√432). Số 0,5 là sai dấu. Số −0,25 là quên lấy căn mẫu (−2/8)."},{"id":"A-H-9-02","muc":9,"q":"Bốn người đã chấm phim X, với độ giống An như sau.\nBình có độ giống 0,6 và chấm 4.\nChi có độ giống 0,4 và chấm 1.\nDũng có độ giống 0,3 và chấm 5.\nGiang có độ giống 0,1 và chấm 5.\nEm chỉ dùng hai người giống An nhất. Dự đoán = Σ sim·r / Σ |sim|. Kết quả bằng bao nhiêu?","options":["3,43","2,5","2,8","1,4"],"answer":[2],"multi":false,"why":"Hai người giống nhất là Bình và Chi. Tử số: 0,6·4 + 0,4·1 = 2,8. Mẫu số: 0,6 + 0,4 = 1. Dự đoán là 2,8. Số 3,43 là khi dùng cả bốn người (4,8/1,4). Số 2,5 là trung bình cộng điểm của Bình và Chi. Số 1,4 là chia tử số cho số láng giềng thay vì cho Σ |sim|."},{"id":"A-H-9-03","muc":9,"q":"Kho có N = 16 tài liệu. Em dùng TF là số lần xuất hiện và IDF = log₂(N/DF). Trong tài liệu d, từ “cat” xuất hiện 3 lần và có DF = 4. Từ “dog” xuất hiện 1 lần và có DF = 2. Chọn tất cả phát biểu đúng.","options":["TF-IDF của “cat” trong d bằng 6.","TF-IDF của “dog” lớn hơn TF-IDF của “cat”.","TF-IDF của “dog” trong d bằng 3.","Một từ xuất hiện trong cả 16 tài liệu có IDF bằng 0."],"answer":[0,2,3],"multi":true,"why":"“cat”: IDF = log₂ 4 = 2, TF-IDF = 3·2 = 6. “dog”: IDF = log₂ 8 = 3, TF-IDF = 1·3 = 3. Vậy “cat” lớn hơn “dog”. Từ có DF = N thì IDF = log₂ 1 = 0, nên không giúp phân biệt tài liệu."},{"id":"A-H-9-04","muc":9,"q":"Một phim mới vừa ra mắt và chưa ai chấm điểm. Cách nào gợi ý được phim này ngay cho người dùng?","options":["Content-based: so thể loại, đạo diễn, diễn viên của phim với hồ sơ người dùng.","User-based collaborative filtering: tìm người dùng đã chấm phim này.","Item-based collaborative filtering: tính độ giống giữa phim này và các phim khác từ điểm đánh giá.","Tính Pearson giữa phim này và các phim khác từ điểm đánh giá."],"answer":[0],"multi":false,"why":"Phim mới chưa có điểm đánh giá, nên mọi cách dựa trên điểm đánh giá (user-based, item-based, Pearson) đều không có dữ liệu. Content-based chỉ cần đặc điểm của phim nên dùng được ngay."},{"id":"A-H-9-05","muc":9,"q":"Hệ thống có 10 triệu người dùng và 2000 phim. Điểm đánh giá của người dùng thay đổi liên tục, còn độ giống giữa các phim khá ổn định. Em nên chọn cách nào?","options":["User-based, vì ma trận độ giống 10 triệu × 10 triệu dễ tính hơn.","User-based, vì có nhiều người dùng nên họ giống nhau hơn.","Content-based, vì collaborative filtering không dùng được khi có nhiều người dùng.","Item-based, vì chỉ cần tính sẵn ma trận độ giống 2000 × 2000 rồi dùng lại."],"answer":[3],"multi":false,"why":"Số phim nhỏ và độ giống phim ổn định, nên item-based tính trước một lần, dùng lại nhiều lần. Ma trận độ giống giữa 10 triệu người dùng lớn hơn rất nhiều và đổi liên tục. Collaborative filtering vẫn dùng được khi có nhiều người dùng, thậm chí càng nhiều dữ liệu càng tốt."},{"id":"A-H-9-06","muc":9,"q":"Tác nhân học bằng Q-learning với α = 0,5 và γ = 0,5, mọi Q ban đầu bằng 0. Một lượt chơi gồm hai bước. Bước 1: ở s₁ làm hành động a, nhận r = 4, sang s₂. Bước 2: ở s₂ làm hành động b, nhận r = 2, rồi lượt chơi kết thúc (không còn trạng thái kế tiếp). Tác nhân chơi hai lượt giống hệt nhau, mỗi lượt cập nhật bước 1 rồi bước 2. Sau hai lượt, Q(s₁, a) bằng bao nhiêu?","options":["3","3,25","4,5","2"],"answer":[1],"multi":false,"why":"Lượt 1: Q(s₁, a) = 0 + 0,5·(4 + 0,5·0 − 0) = 2. Rồi Q(s₂, b) = 0,5·2 = 1. Lượt 2, bước 1: Q(s₁, a) = 2 + 0,5·(4 + 0,5·1 − 2) = 2 + 1,25 = 3,25. Số 3 là quên phần γ·max Q(s₂, ·). Số 4,5 là mục tiêu 4 + 0,5·1, chưa cập nhật. Số 2 là giá trị sau lượt 1."},{"id":"A-H-9-07","muc":9,"q":"Về Q-learning và ε-greedy. Chọn tất cả phát biểu đúng.","options":["ε-greedy với ε càng lớn thì tác nhân học càng nhanh.","Q-learning cần biết trước xác suất chuyển trạng thái.","Q-learning dùng max Q(s′, ·) trong mục tiêu, kể cả khi hành động thật sự được chọn tiếp theo (do ε-greedy) khác hành động tốt nhất.","Với α = 1, giá trị Q cũ bị thay hoàn toàn bằng r + γ·max Q(s′, ·)."],"answer":[2,3],"multi":true,"why":"Mục tiêu của Q-learning luôn dùng max, nên nó học giá trị của chính sách tham lam dù đang khám phá. Với α = 1 thì Q + (mục tiêu − Q) = mục tiêu. ε quá lớn thì tác nhân chọn ngẫu nhiên quá nhiều nên học chậm. Q-learning không cần mô hình môi trường."},{"id":"A-H-9-08","muc":9,"q":"Tác nhân nhận lần lượt các phần thưởng −1, −1, −1 và 10 ở bước 0, 1, 2 và 3. Hệ số chiết khấu γ = 0,9. Return G = Σ γᵗ·rₜ bằng bao nhiêu?","options":["7","−2,71","4,58","5,39"],"answer":[2],"multi":false,"why":"G = −1 − 0,9 − 0,81 + 0,729·10 = −2,71 + 7,29 = 4,58. Số 7 là tổng không chiết khấu. Số −2,71 là bỏ phần thưởng 10. Số 5,39 là chiết khấu phần thưởng 10 bằng γ² thay vì γ³ (−2,71 + 8,1)."},{"id":"A-H-9-09","muc":9,"q":"Tác nhân có 4 hành động và dùng ε-greedy với ε = 0,2. Với xác suất ε, nó chọn ngẫu nhiên đều trong cả 4 hành động, kể cả hành động tốt nhất. Xác suất tác nhân chọn hành động tốt nhất bằng bao nhiêu?","options":["0,85","0,8","0,2","0,25"],"answer":[0],"multi":false,"why":"Hành động tốt nhất được chọn khi khai thác (xác suất 0,8), hoặc khi khám phá và tình cờ trúng nó (0,2·1/4 = 0,05). Tổng là 0,85. Số 0,8 là quên trường hợp tình cờ trúng. Số 0,2 là xác suất khám phá. Số 0,25 là chọn đều cả 4."},{"id":"A-H-9-10","muc":9,"q":"Về return và policy trong học tăng cường. Chọn tất cả phát biểu đúng.","options":["Policy xác định hành động cần chọn ở mỗi trạng thái.","Hệ số γ lớn hơn 1 làm tác nhân coi trọng tương lai hơn mà return vẫn luôn hữu hạn.","Khi mọi phần thưởng đều dương, γ lớn hơn cho return lớn hơn.","Với γ = 0, return bằng phần thưởng tức thời r₀."],"answer":[0,2,3],"multi":true,"why":"Policy ánh xạ trạng thái sang hành động. Return = Σ γᵗ·rₜ, nên khi các rₜ đều dương thì γ tăng làm return tăng, và với γ = 0 chỉ còn r₀. Khi γ > 1 các số hạng lớn dần nên return có thể không hữu hạn."},{"id":"B-H-10-01","muc":10,"q":"Đồ thị có hướng có trọng số sau có đỉnh xuất phát là S, đích là G.\nS → A: 2\nS → B: 2\nS → C: 5\nA → D: 3\nB → D: 1\nB → E: 4\nC → E: 1\nD → G: 6\nE → F: 2\nE → G: 3\nF → G: 1\nUCS mở đỉnh có g nhỏ nhất. Khi hai đỉnh có g bằng nhau, UCS chọn đỉnh đứng trước theo bảng chữ cái.\nUCS mở các đỉnh theo thứ tự nào, cho đến khi mở G?","options":["S, A, B, C, D, E, G","S, A, D, G","S, A, B, D, C, E, F, G","S, A, B, C, D, E, F, G"],"answer":[2],"multi":false,"why":"g(A) = 2, g(B) = 2, g(D) = 2 + 1 = 3 (qua B), g(C) = 5, g(E) = min(2 + 4, 5 + 1) = 6, g(F) = 8, g(G) = min(3 + 6, 6 + 3, 8 + 1) = 9. Sắp theo g tăng dần, A đứng trước B vì cùng g = 2. Thứ tự mở là S, A, B, D, C, E, F, G."},{"id":"B-H-10-02","muc":10,"q":"Đồ thị có hướng sau có đỉnh xuất phát là S, đích là G.\nS → A\nS → B\nA → C\nA → D\nB → D\nB → E\nC → G\nD → C\nDFS dùng stack. Khi mở một đỉnh, thuật toán đẩy các đỉnh kề chưa mở vào stack theo thứ tự bảng chữ cái (đỉnh đứng trước đẩy trước). Đỉnh lấy ra khỏi stack mà đã mở rồi thì bị bỏ qua.\nDFS mở các đỉnh theo thứ tự nào, cho đến khi mở G?","options":["S, A, C, G","S, B, E, D, C, G","S, A, B, C, D, E, G","S, A, D, C, G"],"answer":[1],"multi":false,"why":"Mở S, đẩy A rồi B vào stack. B nằm trên cùng nên được mở trước, đẩy D rồi E. Lấy E ra: E không có đỉnh kề. Lấy D ra, đẩy C. Lấy C ra, đẩy G. Lấy G ra và dừng. Thứ tự là S, B, E, D, C, G. Thứ tự S, A, C, G là của DFS đệ quy xét đỉnh kề theo thứ tự bảng chữ cái, không phải dạng stack này."},{"id":"B-H-10-03","muc":10,"q":"Đồ thị có hướng có trọng số sau có đỉnh xuất phát là S, đích là G.\nS → A: 2\nS → B: 1\nS → C: 4\nA → D: 1\nB → D: 5\nB → E: 2\nC → E: 1\nD → G: 3\nE → G: 4\nGiá trị heuristic:\nh(S) = 6\nh(A) = 3\nh(B) = 4\nh(C) = 3\nh(D) = 3\nh(E) = 3\nh(G) = 0\nA* mở đỉnh có f = g + h nhỏ nhất. Khi hai đỉnh có f bằng nhau, A* chọn đỉnh đứng trước theo bảng chữ cái.\nA* mở các đỉnh theo thứ tự nào, cho đến khi mở G?","options":["S, B, A, D, E, C, G","S, A, B, D, E, G","S, A, C, D, G","S, A, B, C, D, E, G"],"answer":[1],"multi":false,"why":"Mở S: f(A) = 2 + 3 = 5, f(B) = 1 + 4 = 5, f(C) = 4 + 3 = 7. A và B cùng f = 5, nên mở A trước, được D với g = 3 và f = 6. Mở B: được E với g = 3 và f = 6, còn D qua B có g = 6 nên không tốt hơn. Tập biên có C (7), D (6), E (6). Mở D, được G với g = 6 và f = 6. Lúc này E và G cùng f = 6, E đứng trước theo bảng chữ cái nên mở E (G qua E có g = 7, không tốt hơn). Cuối cùng mở G."},{"id":"B-H-10-04","muc":10,"q":"Đồ thị có hướng có trọng số sau có đích là G.\nS → A: 1\nA → B: 1\nB → G: 3\nGiá trị heuristic:\nh(S) = 5\nh(A) = 1\nh(B) = 3\nh(G) = 0\nChi phí thật nhỏ nhất đến G là h*(S) = 5, h*(A) = 4, h*(B) = 3.\nChọn tất cả phát biểu đúng.","options":["Heuristic h là admissible.","Heuristic h là consistent.","Cạnh A → B vi phạm điều kiện consistent.","Cạnh S → A vi phạm điều kiện consistent."],"answer":[0,3],"multi":true,"why":"Admissible: h(S) = 5 ≤ 5, h(A) = 1 ≤ 4, h(B) = 3 ≤ 3, nên h là admissible. Consistent cần h(u) ≤ c(u, v) + h(v) ở mọi cạnh. Cạnh S → A cho 5 ≤ 1 + 1 = 2, sai, nên h không consistent. Cạnh A → B cho 1 ≤ 1 + 3 = 4, đúng. Cạnh B → G cho 3 ≤ 3 + 0, đúng."},{"id":"B-H-10-05","muc":10,"q":"Cây trò chơi có ba tầng. Gốc R là nút MAX có ba nút con MIN, mỗi nút MIN có hai nút con MAX. Alpha-beta duyệt các lá từ trái sang phải.\nR (MAX): A, B, C\nA (MIN): A1, A2\nB (MIN): B1, B2\nC (MIN): C1, C2\nA1 (MAX): 4, 7\nA2 (MAX): 5, 3\nB1 (MAX): 2, 3\nB2 (MAX): 6, 1\nC1 (MAX): 8, 10\nC2 (MAX): 11, 4\nGiá trị của gốc R và số lá bị cắt tỉa lần lượt là bao nhiêu?","options":["10 và 3","10 và 2","9 và 3","8 và 4"],"answer":[0],"multi":false,"why":"Nhánh A: A1 = max(4, 7) = 7. Ở A2 có β = 7 nhưng 5 và 3 đều nhỏ hơn 7 nên duyệt hết, A2 = 5, A = 5 và α = 5 ở gốc. Nhánh B: B1 = max(2, 3) = 3 ≤ α = 5, nên B không thể vượt 5 và cắt B2 (2 lá). Nhánh C: C1 = max(8, 10) = 10, nên β = 10. Ở C2, lá 11 ≥ 10 nên cắt lá 4 (1 lá). Giá trị C = min(10, ≥ 11) = 10, và gốc = max(5, ≤ 3, 10) = 10. Số lá bị cắt = 2 + 1 = 3."},{"id":"B-H-10-06","muc":10,"q":"Cây trò chơi có ba tầng. Gốc R là nút MIN, hai nút con A và B là nút MAX, và mỗi nút con của chúng là nút MIN. Alpha-beta duyệt các lá từ trái sang phải.\nR (MIN): A, B\nA (MAX): A1, A2\nB (MAX): B1, B2\nA1 (MIN): 5, 8\nA2 (MIN): 7, 1\nB1 (MIN): 9, 6\nB2 (MIN): 2, 4\nGiá trị của gốc R và số lá alpha-beta phải duyệt lần lượt là bao nhiêu?","options":["5 và 6","5 và 8","6 và 6","4 và 5"],"answer":[0],"multi":false,"why":"A1 = min(5, 8) = 5. A2 duyệt 7 rồi 1, được min = 1. A = max(5, 1) = 5, nên gốc MIN có β = 5 sau nhánh A (đã duyệt 4 lá). Ở nhánh B, B1 = min(9, 6) = 6 (duyệt 2 lá), nên B ≥ 6 ≥ β = 5. Nút B không thể làm giá trị gốc nhỏ hơn 5, nên cắt B2 (2 lá). Gốc = min(5, ≥ 6) = 5. Số lá duyệt = 4 + 2 = 6."},{"id":"B-H-10-07","muc":10,"q":"Ba biến X, Y, Z đều có miền {1, 2, 3, 4}.\nRàng buộc:\nX < Y\nY < Z\nX + Z = 6\nSau khi chạy AC-3 cho đến khi không còn thay đổi, miền của các biến là gì?","options":["X ∈ {2}; Y ∈ {3}; Z ∈ {4}","X ∈ {1, 2}; Y ∈ {2, 3}; Z ∈ {3, 4}","X ∈ {2}; Y ∈ {2, 3}; Z ∈ {4}","X ∈ {1, 2, 3}; Y ∈ {2, 3, 4}; Z ∈ {3, 4}"],"answer":[0],"multi":false,"why":"Từ X < Y và Y < Z, ta loại dần: X ∈ {1, 2}, Y ∈ {2, 3}, Z ∈ {3, 4}. Với X + Z = 6: Z = 3 cần X = 3 (không còn), nên Z ∈ {4}. Rồi X = 1 cần Z = 5 (không có), nên X ∈ {2}. Từ X < Y, Y ∈ {3}. Kiểm tra lại Y < Z: 3 < 4 đúng. Chọn kết quả X ∈ {1, 2}, Y ∈ {2, 3}, Z ∈ {3, 4} là bỏ qua ràng buộc X + Z = 6."},{"id":"B-H-10-08","muc":10,"q":"Cơ sở tri thức (KB) có ba mệnh đề dạng CNF:\n(P ∨ Q)\n(¬P ∨ R)\n(¬Q ∨ R)\nChọn tất cả mệnh đề được suy ra từ KB.","options":["R","¬R","Q ∨ R","P ∧ Q"],"answer":[0,2],"multi":true,"why":"Hợp giải (P ∨ Q) với (¬P ∨ R) cho (Q ∨ R). Hợp giải (Q ∨ R) với (¬Q ∨ R) cho R. Vậy R được suy ra, và Q ∨ R cũng được suy ra. ¬R mâu thuẫn với R. P ∧ Q không được suy ra: mô hình P đúng, Q sai, R đúng vẫn thỏa KB."},{"id":"B-H-10-09","muc":10,"q":"Một nhóm xây dựng mô hình lọc thư rác (spam) từ nội dung thư bằng TF-IDF và hồi quy logistic. Thư rác chỉ chiếm 3% dữ liệu.\nChọn tất cả lựa chọn hợp lý.","options":["Dùng MSE làm hàm mất mát với đầu ra sigmoid vì dễ tính hơn.","Tính IDF (và từ vựng) chỉ trên tập train rồi áp dụng cho tập test.","Đánh giá bằng F1 hoặc PR-AUC, vì thư rác chiếm tỉ lệ nhỏ.","Tính trung bình và độ lệch chuẩn của các đặc trưng trên toàn bộ dữ liệu trước khi chia train/test."],"answer":[1,2],"multi":true,"why":"IDF và từ vựng là tham số học từ dữ liệu, nên chỉ fit trên train để tránh data leakage. Dữ liệu lệch lớp nên cần F1 hoặc PR-AUC. MSE với sigmoid làm bài toán tối ưu khó hơn, log loss mới là lựa chọn chuẩn. Chuẩn hóa bằng thống kê của toàn bộ dữ liệu là data leakage."},{"id":"B-H-10-10","muc":10,"q":"Một nhà máy dùng mô hình dự đoán xác suất p để sản phẩm bị lỗi.\nNếu báo nhầm (FP) thì mất chi phí 1. Nếu bỏ sót (FN) thì mất chi phí 4. Dự đoán đúng thì không mất gì.\nNhà máy gắn nhãn \"lỗi\" khi p > t, và giả sử p là xác suất đúng.\nNgưỡng t nào làm chi phí kỳ vọng nhỏ nhất?","options":["0,25","0,2","0,5","0,8"],"answer":[1],"multi":false,"why":"Nếu gắn nhãn \"lỗi\" thì chi phí kỳ vọng là (1 − p)·1. Nếu không gắn thì chi phí kỳ vọng là p·4. Nên gắn nhãn khi (1 − p) < 4p, tức p > 1/5 = 0,2. Chọn 0,25 là lấy 1/4 (tỉ lệ chi phí thay vì chia cho tổng). Chọn 0,5 là ngưỡng mặc định. Chọn 0,8 là đảo vai hai loại chi phí."}]}]};
